# [v7.24 신규] 2단계 키워드 리서치 API — 복지로 서브프로그램에서 그대로
# 이식. 목적: 프롬프트A [2단계]의 경쟁 강도 실측을 지금까지는 AI가 매번
# 크롬으로 직접 검색해서 확인했는데, 여기에 API로 미리 확보한 정량
# 데이터(월간검색량 실측치, 블로그 상위 제목의 실제 포화 표현)를 추가로
# 얹어준다. "제목 패턴 변형 실측"도 오픈API 블로그검색 결과에서 자주
# 등장하는 조합(예: "총정리", "완벽정리")을 자동으로 뽑아주므로 상당
# 부분 대체된다. 크롬 직접검색은 확정·시행형 임박 판단처럼 AI의 정성적
# 판단이 꼭 필요한 영역에만 남겨둔다 — 이 크롬 직접검색은 [v7.29]부터
# 비로그인 임시 프로필로 열리며(IP 체크는 기존 그대로 유지, 별개 목적).
# 정책뉴스는 requests가 아니라 urllib.request를 쓰는 관례라 그에 맞춰
# 구현했다(복지로 서브프로그램은 requests 기반 — 로직은 동일).
# ════════════════════════════════════════════════════════════

RESEARCH_CACHE_FILE_NAME = "keyword_research_cache.json"


def get_research_cache_path() -> str:
    return os.path.join(BASE_DIR, MAIN_WORK_FOLDER, RESEARCH_CACHE_FILE_NAME)


def load_research_cache() -> dict:
    path = get_research_cache_path()
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except (json.JSONDecodeError, OSError):
            return {}
    return {}


def save_research_cache(cache: dict):
    path = get_research_cache_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(cache, f, ensure_ascii=False, indent=2)


def get_cached_research(keyword: str):
    return load_research_cache().get(keyword)


def set_cached_research(keyword: str, data: dict):
    cache = load_research_cache()
    cache[keyword] = data
    save_research_cache(cache)


def get_research_api_keys() -> dict:
    cfg = load_config()
    return {
        "naver_openapi_client_id": cfg.get("naver_openapi_client_id", ""),
        "naver_openapi_client_secret": cfg.get("naver_openapi_client_secret", ""),
        "naver_ad_api_key": cfg.get("naver_ad_api_key", ""),
        "naver_ad_secret_key": cfg.get("naver_ad_secret_key", ""),
        "naver_ad_customer_id": cfg.get("naver_ad_customer_id", ""),
    }


def _urllib_get_json(url: str, params: dict = None, headers: dict = None, timeout: int = 10) -> dict:
    """urllib 기반 공용 GET+JSON 파서 (정책뉴스 기존 관례에 맞춤)."""
    full_url = url
    if params:
        full_url = url + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(full_url, headers=headers or {})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


