# ════════════════════════════════════════════════════════════
# [영역 1] 환경설정
# ════════════════════════════════════════════════════════════

def _path_is_usable(path: str) -> bool:
    """경로 문자열이 현재 PC에서 실제로 만들 수 있는 경로인지 확인.
    드라이브 문자가 다르거나 권한이 없는 경우 등을 미리 걸러낸다."""
    if not path or not path.strip():
        return False
    try:
        if os.path.exists(path):
            return os.path.isdir(path) or True
        os.makedirs(path, exist_ok=True)
        return True
    except Exception:
        return False


def _resolve_program_dir(stored: str, default_abs: str) -> str:
    """config.json에 저장된 프롬프트/완성글 폴더 값을 이 PC에서 실제로 쓸
    절대경로로 해석한다. 회사 PC ↔ 집 PC처럼 Windows 사용자 계정 경로
    ("C:\\Users\\xxx\\...")가 서로 다른 여러 대를 오가며 작업해도 항상
    똑같이 동작하도록, 다음 순서로 처리한다:
      1) 비어있으면 → 기본 경로(default_abs, 이미 BASE_DIR 기준 절대경로)
      2) 상대경로(폴더명)면 → BASE_DIR과 결합 (정상 케이스 — Ver7.24부터
         config.json에는 항상 이 형태로만 저장된다)
      3) 절대경로면(예전 버전 config.json과의 호환용) → 이 PC에서 그대로
         쓸 수 있으면 그대로 쓰고, 아니면 마지막 폴더명만 살려 BASE_DIR과
         다시 결합해 복구를 시도한다."""
    if not stored:
        return default_abs
    if not os.path.isabs(stored):
        return os.path.join(BASE_DIR, stored)
    if _path_is_usable(stored):
        return stored
    return os.path.join(BASE_DIR, os.path.basename(os.path.normpath(stored)))


def _to_stored_dir(abs_path: str) -> str:
    """설정 저장 시 절대경로 대신 'BASE_DIR 기준 폴더 이름(상대경로)'만
    config.json에 저장한다. 여러 PC를 오가며 작업할 때 특정 PC의 사용자
    계정 경로("C:\\Users\\xxx\\...")가 그대로 저장돼 다른 PC에서 안 맞는
    문제를 막기 위함 — 이 파일의 POSTING_MD_FOLDER/MAIN_WORK_FOLDER 등
    다른 경로 상수들이 이미 절대경로가 아니라 폴더명만 쓰는 것과 동일한
    원칙을 설정 폴더(prompt_dir/output_dir)에도 그대로 적용한 것이다."""
    if not abs_path:
        return ""
    try:
        rel = os.path.relpath(abs_path, BASE_DIR)
        if not rel.startswith(".."):
            return rel.replace("\\", "/")
    except Exception:
        pass
    # BASE_DIR 바깥의 완전히 다른 위치를 골랐다면(드문 경우) 폴더 이름만이라도 저장
    return os.path.basename(os.path.normpath(abs_path))


def load_config() -> dict:
    if not os.path.exists(CONFIG_PATH):
        save_config(DEFAULT_CONFIG)
        return json.loads(json.dumps(DEFAULT_CONFIG))
    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
        try:
            cfg = json.load(f)
        except Exception:
            # 설정 파일 자체가 깨진 경우 기본값으로 복구
            cfg = json.loads(json.dumps(DEFAULT_CONFIG))
    for k, v in DEFAULT_CONFIG.items():
        if k not in cfg:
            cfg[k] = v

    # [Ver7.24 수정] prompt_dir/output_dir을 항상 BASE_DIR 기준으로 해석한다.
    # config.json에는 폴더명(상대경로)만 저장돼 있는 게 정상이고(_to_stored_dir),
    # 예전 버전에서 절대경로로 저장된 파일이 남아있어도 _resolve_program_dir이
    # 안전하게 복구한다 — 이 in-memory cfg 값은 항상 "지금 이 PC에서 실제로
    # 쓸 수 있는 절대경로"이므로, 이 값을 그대로 쓰는 다른 모든 코드(TAB6/TAB9
    # 등)는 수정할 필요가 없다.
    cfg["prompt_dir"] = _resolve_program_dir(cfg.get("prompt_dir", ""), PROMPT_DIR)
    cfg["output_dir"] = _resolve_program_dir(cfg.get("output_dir", ""), OUTPUT_DIR)
    # [Ver7.14] 키워드 엑셀은 파일 경로라 _path_is_usable을 그대로 쓸 수
    # 없다(디렉터리 여부를 검사하는 함수라서) — 부모 폴더가 이 PC에서
    # 쓸 수 있는지만 확인한다. 비어있으면(기본값 사용 의미) 그대로 둔다.
    # 여기서 _get_keyword_excel_path()를 부르면 그 함수가 다시
    # load_config()를 불러 무한 재귀가 되므로 절대 쓰지 않는다.
    kw_path = cfg.get("keyword_excel_path", "").strip()
    if kw_path and not _path_is_usable(os.path.dirname(kw_path) or "."):
        cfg["keyword_excel_path"] = ""

    # RSS 종료 마이그레이션: 예전에 저장된 config.json에 /rss/*.xml URL이
    # (부처별로 여러 개) 남아있으면, 전부 죽은 URL이므로 2개의 종합 리스트
    # 페이지로 자동 교체한다. 부처 구분은 run_collect의 dept_hint가 대신한다.
    feeds = cfg.get("feeds", {})
    if any("korea.kr/rss/" in url for url in feeds.values()):
        cfg["feeds"] = dict(DEFAULT_CONFIG["feeds"])
        save_config(cfg)

    return cfg


def save_config(cfg: dict):
    with open(CONFIG_PATH, "w", encoding="utf-8") as f:
        json.dump(cfg, f, ensure_ascii=False, indent=2)


# ════════════════════════════════════════════════════════════
# [영역 2] 수집 로직
# ════════════════════════════════════════════════════════════

def clean_title(t: str) -> str:
    return html.unescape(t).strip()


def strip_html(text: str) -> str:
    """RSS description에 섞인 HTML 태그를 제거해 순수 텍스트만 남긴다.
    부처명 추출(_ORG_PAT)과 classify 키워드 매칭의 정확도를 위해,
    태그 잔재 때문에 매칭이 틀어지는 것을 막는다."""
    if not text:
        return ""
    text = html.unescape(text)
    text = re.sub(r'<[^>]+>', ' ', text)
    text = re.sub(r'\s+', ' ', text)
    return text.strip()


def classify(title: str, body_snippet: str, good_kw: list, bad_kw: list) -> bool:
    """제목+본문 앞부분을 종합 판단한다.
    - good_keywords: 제목 또는 본문 앞부분 어디에 있어도 인정한다 (넓게 본다).
      제목에는 안 보여도 본문 서두에 "~지원금을 신청하세요" 식으로
      구체적 내용이 나오는 경우가 많아서다.
    - bad_keywords: 제목에 있을 때만 걸러낸다 (좁게 본다).
      "회의", "점검"처럼 흔한 단어가 본문 300자 안에 우연히 한 번
      섞여 있다고 전체를 차단하면, 진짜 가치 있는 기사까지 같이
      걸러지는 부작용이 더 크다. 이 기사 자체가 회의/간담회 안내라면
      그 사실이 보통 제목에 그대로 드러난다."""
    combined = title + " " + (body_snippet or "")
    has_good = any(k in combined for k in good_kw)
    has_bad_in_title = any(k in title for k in bad_kw)
    return has_good and not has_bad_in_title


def get_body_type(link: str) -> str:
    if "policyNewsView.do" in link:
        return "본문있음"
    if "pressReleaseView.do" in link:
        return "첨부파일만"
    return "확인필요"


# 공공누리 "변경금지" 조건 문구 — 정책브리핑 기사 하단에 실제로 쓰이는
# 표현들을 그대로 모았다. 대부분의 정책뉴스/보도자료는 "출처표시의 조건에
# 따라 자유이용이 가능"(제1유형, 각색 가능)이지만, 드물게 "출처표시 및
# 변경을 금하는 조건"(변경 불가)이 붙는 경우가 있어 그것만 걸러낸다.
_LICENSE_NO_EDIT_PAT = re.compile(r"변경을?\s*금(하는|지)")


def _parse_meta_published_time(iso_str: str) -> str:
    """[Ver7.14 추가] og/article published_time 메타태그(ISO 8601, 보통
    UTC 'Z' 표기)를 한국 시각(KST, UTC+9) "YYYY-MM-DD HH:MM" 문자열로
    변환한다. 타임존 오프셋이 'Z'가 아니라 '+09:00'처럼 이미 붙어있는
    경우도 datetime.fromisoformat + astimezone으로 정확히 처리된다.
    파싱 실패 시 빈 문자열(호출부에서 기존 방식으로 폴백)."""
    if not iso_str:
        return ""
    try:
        s = iso_str.strip().replace("Z", "+00:00")
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            # 오프셋 정보가 아예 없으면 이미 한국 로컬 시각이라고 가정
            return dt.strftime("%Y-%m-%d %H:%M")
        dt_kst = dt.astimezone(timezone(timedelta(hours=9)))
        return dt_kst.strftime("%Y-%m-%d %H:%M")
    except Exception:
        return ""


def fetch_article_detail_info(link: str, log=print) -> dict:
    """기사 원문 페이지를 한 번 열어서 세 가지를 같이 확인한다:
      1) license_warn: 하단 공공누리 이용조건에 '변경금지'가 걸려있는지
         (True면 각색하지 말고 원문 그대로만 인용해야 함)
      2) published_time: <meta property="article:published_time"> 태그의
         실제 발행 일시(분 단위까지, KST로 환산)
      3) [Ver7.15 추가] title: <meta property="og:title"> 태그의 제목
         — TAB1 "➕ 수동 등록"에서 링크만 붙여넣고 자동 채우기를 할 때
         재사용한다.
    [Ver7.14 수정] 예전에는 이 함수(당시 이름 check_license_restriction)가
    라이선스 문구만 확인하고 끝났는데, 정작 리스트 페이지 스크래핑
    (_scrape_korea_news_list)은 카드에 찍힌 날짜만 읽을 수 있어서
    "발행일 00:00"처럼 시간이 항상 자정으로 고정되는 문제가 있었다.
    실제 발행 시각은 상세 페이지의 메타태그에만 있는데, 후보로 확정된
    기사는 이미 이 함수로 상세 페이지를 한 번 열고 있으므로(라이선스
    확인 목적), 그 김에 같이 읽어오면 네트워크 호출을 추가로 늘리지
    않고 정확한 시간을 얻을 수 있다.
    원문 접속에 실패해도 수집 자체가 막히면 안 되므로, 실패 시에는
    "모르니 일단 안전하게 취급"하지 않고 license_warn=False로 넘어간다 —
    페이지 구조 확인이 안 된 기사까지 전부 경고 뜨면 오히려 신호를 잃는다.
    대신 실패는 로그로 남겨서 사람이 필요하면 원문을 직접 확인하게 한다."""
    result = {"license_warn": False, "published_time": "", "title": ""}
    try:
        req = urllib.request.Request(link, headers={
            "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                           "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"),
            "Accept-Language": "ko-KR,ko;q=0.9",
            "Referer": "https://www.korea.kr/",
        })
        with urllib.request.urlopen(req, timeout=6) as resp:
            body = resp.read().decode("utf-8", errors="replace")
        result["license_warn"] = bool(_LICENSE_NO_EDIT_PAT.search(body))

        m = re.search(
            r'<meta[^>]+(?:property|name)=["\']article:published_time["\'][^>]*content=["\']([^"\']+)["\']',
            body
        )
        if not m:
            # 속성 순서가 반대(content가 먼저)인 경우도 있어 한 번 더 시도
            m = re.search(
                r'<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name)=["\']article:published_time["\']',
                body
            )
        if m:
            result["published_time"] = _parse_meta_published_time(m.group(1))

        tm = re.search(
            r'<meta[^>]+(?:property|name)=["\']og:title["\'][^>]*content=["\']([^"\']+)["\']',
            body
        )
        if not tm:
            tm = re.search(
                r'<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name)=["\']og:title["\']',
                body
            )
        if tm:
            result["title"] = html.unescape(tm.group(1)).strip()
    except Exception as e:
        log(f"  [확인 필요] 원문 상세정보 확인 실패(원문 직접 확인 권장): {link} ({e})")
    return result


def parse_published(pub_str: str) -> datetime:
    for fmt in ("%a, %d %b %Y %H:%M:%S %Z", "%a, %d %b %Y %H:%M:%S %z",
                "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%d %H:%M:%S",
                "%Y-%m-%d %H:%M"):
        # 마지막 포맷("%Y-%m-%d %H:%M")은 초 단위가 없는 형식이다.
        # 후보군 엑셀에 발행일을 저장할 때 분 단위까지만 쓰기 때문에
        # (save_candidate_xlsx에서 strftime("%Y-%m-%d %H:%M")), 엑셀에서
        # 다시 불러올 때 이 포맷이 없으면 전부 파싱 실패 → datetime.min이
        # 되어 "최근 N일" 같은 날짜 필터를 걸면 전부 걸러지는 버그가 있었다.
        try:
            return datetime.strptime(pub_str[:31].strip(), fmt)
        except Exception:
            pass
    return datetime.min


def _get_seen_path() -> str:
    """중복방지 json 경로 - 완성글 저장 폴더(output_dir) 루트"""
    cfg = load_config()
    output_dir = cfg.get("output_dir", OUTPUT_DIR)
