# [Ver7.08 추가] newsId 기준 링크 정규화
_CANON_PATTERNS = [
    ("briefing", "pressReleaseView"),
    ("news",     "policyNewsView"),
    ("briefing", "actuallyView"),
    ("multi",    "visualNewsView"),
]

def _canonicalize_news_link(url: str) -> str:
    """korea.kr 기사 링크를 newsId 기준 표준형으로 정규화한다.
    같은 기사인데도 call_from=rsslink, pWise=sub&pWiseSub=R4, 심지어
    페이지네이션 POST 폼 파라미터(pageIndex·startDate·repCodeType 등)가
    그대로 꼬리표로 붙어 나오는 경우가 있어서, URL 문자열 그대로
    비교·저장하면 같은 기사를 계속 "새 기사"로 오인하는 문제가 있었다
    (실측: 중복방지 목록 2,053건 중 623건이 이런 꼬리표 차이로 인한
    중복이었음 — 고유 기사는 1,430건뿐). newsId와 기본 경로만으로
    URL을 다시 만들어서, 꼬리표가 뭐가 붙어있든 항상 같은 문자열이
    되게 한다."""
    m = re.search(r"newsId=(\d+)", url)
    if not m:
        return url.strip()
    news_id = m.group(1)
    for seg, view in _CANON_PATTERNS:
        if f"/{seg}/{view}" in url:
            return f"https://www.korea.kr/{seg}/{view}.do?newsId={news_id}"
    # 알려진 경로 패턴이 아니면(사이트 구조가 더 바뀐 경우) newsId만이라도
    # 표준 키로 써서 최소한의 dedup은 되게 한다.
    return f"newsId:{news_id}"


# [Ver7.09 추가] 메인 오토포스팅 프로그램 연동 (지식인 서브프로그램의
# add_approved_keywords / copy_approved_files_to_markdown_folder 로직을
# 정책뉴스용으로 참조해서 만듦). 세 경로 모두 프로그램 실행 위치의
# 공용폴더 루트에 있는 상대경로다(지식인 프로그램과 동일한 방식).
#
# 이 기능 자체는 "필수"가 아니다 — 메인 프로그램이 자체적으로도 중복체크를
# 하기 때문에 없어도 동작한다. 다만 사람이 눈으로 한 번 더 확인하면서
# 더 꼼꼼하게 점검하기 위한 보조 기능으로 추가하는 것이다.
POSTING_MD_FOLDER  = "Naver_blog_keyword_perplexity_gpt_manual_markdown_for_posting"
MAIN_WORK_FOLDER   = "Naver_blog_정책뉴스_markdown_work_folder"
# [Ver7.13 수정] 키워드 엑셀 기본 위치를 공용폴더 루트가 아니라
# MAIN_WORK_FOLDER 안으로 변경. 다른 경로는 그대로 루트 상대경로다.
# ⚠️ 이 파일은 메인 오토포스팅 프로그램(별도 파일)도 같은 경로로 읽는다
# — 이 프로그램에서만 옮기면 안 되고, 메인 프로그램 쪽의 키워드 엑셀
# 경로 설정도 반드시 같은 위치로 같이 바꿔줘야 두 프로그램이 계속
# 같은 파일을 보게 된다.
# [Ver7.14 추가] 이 기본값은 "파일이 아예 없을 때"만 쓰는 값이고, 실제로는
# 설정 탭에서 "찾기" 버튼으로 사용자가 원하는 위치를 지정할 수 있다
# (config의 "keyword_excel_path" 키, _get_keyword_excel_path() 참고).
# 메인 프로그램의 키워드 엑셀이 이미 다른 위치에 있다면, 이 경로를 옮기지
# 말고 설정 탭에서 그 위치를 그대로 가리키게 하는 쪽이 더 안전하다.
DEFAULT_KEYWORD_EXCEL_PATH = os.path.join(MAIN_WORK_FOLDER, "Naver_blog_정책뉴스_keyword.xlsx")
# [Ver7.11 수정] 중복 의심 문서 격리 폴더 — 별도 공용폴더가 아니라
# "작업 폴더/{날짜}/" 안에 만든다. 어차피 포스팅에 안 쓰고 확인 후
# 지울 물건이라, 날짜 폴더 하나만 지우면 같이 정리되는 쪽이 낫다.
DUP_SUBFOLDER_NAME = "Naver_blog_정책뉴스_markdown_duplicated"


def _get_keyword_excel_path() -> str:
    """[Ver7.14 추가] 키워드 엑셀 파일의 실제 경로를 반환한다.
    설정 탭에서 "찾기"로 지정한 절대경로가 있으면 그걸 쓰고,
    지정 안 했으면(빈 문자열) DEFAULT_KEYWORD_EXCEL_PATH(작업폴더 안)를
    쓴다. 다른 경로 함수들(_get_dup_db_path 등)과 동일한 패턴으로,
    이 파일 안에서 키워드 엑셀을 읽고 쓰는 모든 곳은 이 함수를
    통해서만 경로를 얻어야 한다(KEYWORD_EXCEL_PATH 상수를 직접
    쓰지 않는다)."""
    cfg = load_config()
    path = cfg.get("keyword_excel_path", "").strip()
    return path if path else DEFAULT_KEYWORD_EXCEL_PATH


def _get_unified_keyword_excel_path() -> str:
    """✅ [2026-09-05] 통합 키워드 엑셀 경로. 설정 안 했으면 빈 문자열을
    반환한다(기본값 폴더로 자동 추정하지 않음 - 통합 파일은 명시적으로
    지정한 경우에만 써야 함)."""
    cfg = load_config()
    return cfg.get("unified_keyword_excel_path", "").strip()


# ✅ [2026-09-29] 게시판 설정 엑셀 조회 - 파일 수정 시각이 바뀔 때만 다시 읽는다.
_BOARD_CFG_CACHE = {"path": None, "mtime": None, "cfg": None}


def _get_board_config_path() -> str:
    """설정 탭에서 지정한 경로, 없으면 프로그램 폴더의 기본 파일명(존재할 때만)."""
    if not HAS_BOARD_MODULE:
        return ""
    p = load_config().get("board_config_path", "").strip()
    if p:
        return p
    default = os.path.join(str(BASE_DIR), board_mod.BOARD_CONFIG_FILENAME)
    return default if os.path.exists(default) else ""


def _load_board_cfg() -> dict:
    """게시판 설정을 읽어 dict로 돌려준다. 모듈/파일이 없거나 형식이 다르면
    {"ok": False, "error": ...} - 호출부는 이 경우 예전 방식으로 동작한다."""
    if not HAS_BOARD_MODULE:
        return {"ok": False, "error": "게시판 모듈 없음", "boards": []}
    path = _get_board_config_path()
    if not path:
        return {"ok": False, "error": "게시판 설정 엑셀 미지정", "boards": []}
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        mtime = None
    c = _BOARD_CFG_CACHE
    if c["cfg"] is not None and c["path"] == path and c["mtime"] == mtime:
        return c["cfg"]
    cfg = board_mod.load_board_config(path)
    c.update({"path": path, "mtime": mtime, "cfg": cfg})
    return cfg


def _build_board_prompt_note() -> str:
    """프롬프트A 복사 시 끝에 덧붙일 게시판 판정 지시문(설정이 없으면 빈 문자열)."""
    cfg = _load_board_cfg()
    if not cfg.get("ok"):
        return ""
    return "\n" + board_mod.build_board_prompt_block(cfg)


def _get_last_used_keyword_category_from_excel() -> str:
    """키워드 엑셀 B열에서 "데이터가 있는 마지막 행"의 카테고리 값을
    읽어온다(_append_titles_to_keyword_excel이 카테고리 입력란을 비워둔
    채 등록할 때 재사용하는 것과 동일한 규칙). 파일이 없거나 읽기
    실패하면 빈 문자열."""
    try:
        path = _get_keyword_excel_path()
        if not os.path.exists(path):
            return ""
        wb = load_workbook(path, read_only=True, data_only=True)
        ws = wb.active
        last_category = ""
        for r in range(ws.max_row, 1, -1):
            v = ws.cell(row=r, column=2).value
            if v not in (None, ""):
                last_category = str(v)
                break
        wb.close()
        return last_category
    except Exception:
        return ""


def _get_default_keyword_category() -> str:
    """✅ [2026-09-05] TAB7 "카테고리" 입력란의 기본값을 결정한다.
    (배경: 복지로 서브프로그램은 키워드 등록 시 카테고리를 직접 입력하는
    란이 있는데, 정책뉴스 서브프로그램에는 없어서 항상 "엑셀의 직전
    카테고리 재사용" 방식뿐이었음 - 복지로와 동일하게 입력란을 추가함.)
    config.json에 저장된 직전 값이 있으면 그것을 우선 쓰고(프로그램을
    껐다 켜도 유지됨), 없으면 기존 방식대로 키워드 엑셀 B열의 마지막
    값을 쓴다."""
    cfg_value = load_config().get("kw_last_category", "").strip()
    if cfg_value:
        return cfg_value
    return _get_last_used_keyword_category_from_excel()


def _save_last_used_keyword_category(category: str):
    """카테고리 값을 config.json에 저장(다음 실행 시 입력란 기본값으로
    복원 - 복지로 서브프로그램의 save_last_used_keyword_category와
    동일한 방식)."""
    cfg = load_config()
    cfg["kw_last_category"] = category
    save_config(cfg)


def _normalize_title_for_match(title: str) -> str:
    """제목 비교용 정규화 — 파일명 금지문자 제거 + 공백 정리 + 대소문자
    무시. 키워드 엑셀에 이미 있는 제목인지 판단할 때 쓴다(지식인 프로그램의
    sanitize_filename과 동일한 금지문자 기준)."""
    s = re.sub(r'[\\/:*?"<>|]', "", title or "")
    s = re.sub(r"\s+", " ", s).strip()
    return s.lower()


def _load_keyword_excel_titles() -> set:
    """키워드 엑셀(A열)에 이미 등록된 제목들을 정규화해서 set으로 반환.
    파일이 없으면 빈 set(전부 신규로 처리됨)."""
    path = _get_keyword_excel_path()
    if not OPENPYXL_OK or not os.path.exists(path):
        return set()
    try:
        wb = load_workbook(path, read_only=True)
        ws = wb.active
        titles = set()
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row and row[0]:
                titles.add(_normalize_title_for_match(str(row[0])))
        wb.close()
        return titles
    except Exception:
        return set()


def _find_history_record_by_title(title: str) -> dict:
    """[Ver7.13 추가] 제목으로 이력에서 레코드를 찾는다.
    TAB7 항목(_list_md_items_in_date_folder)은 MD 파일의 H1에서 제목만
    뽑아오므로 링크 정보가 없다 — 실제 확정(핵심DB 등록 + 포스팅완료
    전환) 시점에 이력의 link를 알아야 하므로, 저장 시점에 남겨둔
    saved_title/final_title/title과 정규화 비교해서 역으로 찾는다."""
    norm = _normalize_title_for_match(title)
    for r in load_history():
        for field in ("saved_title", "final_title", "title"):
            if r.get(field) and _normalize_title_for_match(r.get(field, "")) == norm:
                return r
    return {}


def _append_titles_to_keyword_excel(titles: list, category="") -> str:
    """승인된 제목들을 키워드 엑셀 A/B열에 추가한다.
    지식인 프로그램의 add_approved_keywords와 동일한 규칙을 따른다:
    B열(카테고리)은 원래 B열에서 '데이터가 있는 마지막 행'의 값을 그대로
    재사용했으나, ✅ [2026-09-05] 복지로 서브프로그램과 동일하게 호출부
    (TAB7 "카테고리" 입력란)에서 값을 받을 수 있도록 category 매개변수를
    추가했다 - 값을 주면 그 값을 쓰고, 비워두면(기본값) 기존 방식대로
    직전 값을 재사용한다(하위호환 - category를 안 넘기던 기존 호출부도
    그대로 동작). C열은 비워둔다(메인 프로그램이 C열을 자체적으로 채우는
    구조로 보임). 반환값은 실제 사용된 카테고리 값(로그 표시용).

    ✅ [2026-09-29] category에 titles와 같은 길이의 list를 주면 제목마다
    다른 값(게시판 번호/이름)을 그대로 기록한다. 이 경우에는 '직전 값
    재사용'을 하지 않는다 - 빈 문자열(미분류)은 B열을 빈칸으로 둔다."""
    # [Ver7.13] 키워드 엑셀 폴더가 첫 실행 등으로 아직 없을 수 있어
    # 미리 만들어둔다. [Ver7.14] 경로 자체는 설정 탭에서 바꿀 수 있으므로
    # 항상 _get_keyword_excel_path()로 조회한다.
    path = _get_keyword_excel_path()
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    if os.path.exists(path):
        wb = load_workbook(path)
    else:
        wb = Workbook()
        ws0 = wb.active
        ws0["A1"] = "키워드"
        ws0["B1"] = "카테고리"
    ws = wb.active

    per_title = isinstance(category, (list, tuple))
    if per_title:
        if len(category) != len(titles):
            raise ValueError("titles와 카테고리 목록의 길이가 다릅니다.")
        cats = [str(c).strip() if c not in (None, "") else "" for c in category]
        last_category = ", ".join(sorted({c for c in cats if c}))
    else:
        cats = None
        last_category = category.strip() if category and category.strip() else ""
        if not last_category:
            for r in range(ws.max_row, 1, -1):
                v = ws.cell(row=r, column=2).value
                if v not in (None, ""):
                    last_category = str(v)
                    break

    write_row = ws.max_row + 1 if ws.max_row >= 1 else 2
    safe_titles = []  # ✅ [2026-09-05] 통합 키워드 파일에도 "실제로 원본에 쓴 값"
                       # (safe_filename 적용 후)을 그대로 넘기기 위해 따로 모아둔다.
    for idx, title in enumerate(titles):
        # [Ver8.19 수정] 제목을 그대로 쓰지 않고 safe_filename()을 거친
        # 값을 쓴다 — 프롬프트B 제목 규칙이 물음표(?)로 끝나는 질문형으로
        # 바뀐 뒤로, 폴더명(safe_filename(it["title"])으로 생성, "?"
        # 제거됨)과 이 키워드 엑셀의 A열 값(원문 제목 그대로, "?" 포함)이
        # 서로 달라지는 문제가 있었다. 폴더 찾기가 이 엑셀의 키워드 값을
        # 기준으로 이뤄지는 구조라, "?"가 남아있으면 같은 이름의 폴더를
        # 못 찾는다. safe_filename()은 Windows 금지문자(\/:*?"<>|)를
        # 제거하고 80자로 자르므로, 폴더명 생성 로직과 완전히 동일한
        # 규칙을 여기서도 적용해 항상 일치하게 만든다.
        safe_title = safe_filename(title)
        ws.cell(row=write_row, column=1, value=safe_title)
        ws.cell(row=write_row, column=2, value=(cats[idx] if per_title else last_category))
        safe_titles.append(safe_title)
        write_row += 1

    wb.save(path)
    wb.close()

    # ✅ [2026-09-05] 통합 키워드 파일 dual-write - 원본 파일에 실제로 쓴 값
    # (safe_filename 적용 후 텍스트)과 카테고리를 통합 파일에도 그대로
    # 추가한다. 통합 경로가 비어있거나 모듈이 없으면 조용히 건너뛴다(이
    # 서브프로그램 자체의 등록 흐름은 이미 위에서 끝났으므로 절대 영향받지 않음).
    if HAS_UNIFIED_MODULE:
        unified_path = _get_unified_keyword_excel_path()
        if unified_path:
            ok, msg = append_titles_to_unified_keyword_excel(
                unified_path, safe_titles, (cats if per_title else last_category), "정책뉴스")
            if not ok:
                print(f"[통합 키워드 파일] {msg}")

    return last_category


def _get_work_folder() -> str:
    """[Ver10.04 신규] 8)키워드 등록 탭이 읽는 작업 폴더 = MD 저장 폴더(설정의 output_dir).
    예전에는 고정 상수 MAIN_WORK_FOLDER를 봐서, 설정에서 완성글 저장 폴더를 바꾸면 TAB4가
    저장한 글이 8)키워드 등록 탭에 보이지 않았다. 기본 설정에서는 두 값이 같은 폴더다."""
    return load_config().get("output_dir", OUTPUT_DIR)


def _list_work_folder_dates() -> list:
    """작업 폴더(_get_work_folder) 안의 날짜(YYYY-MM-DD) 하위폴더 목록을 최신순으로
    반환한다. 폴더 자체가 없으면 빈 리스트."""
    work = _get_work_folder()
    if not os.path.isdir(work):
        return []
    dates = [d for d in os.listdir(work)
             if re.match(r"\d{4}-\d{2}-\d{2}$", d)
             and os.path.isdir(os.path.join(work, d))]
    return sorted(dates, reverse=True)


def _list_md_items_in_date_folder(date_str: str) -> list:
    """선택한 날짜 폴더 안의 MD 항목을 전부 찾아 반환한다.
    [{title, md_path, asset_folder, is_folder}] 형태.
    - flat: 날짜폴더에 .md 파일이 바로 있는 경우
    - 폴더형: 날짜폴더 안에 제목별 폴더가 있고, 그 안에 .md가 있는 경우
    (지식인 프로그램의 두 가지 저장 방식을 모두 지원)"""
    base = os.path.join(_get_work_folder(), date_str)
    items = []
    if not os.path.isdir(base):
        return items
    for entry in os.listdir(base):
        # [Ver7.11 추가] 격리 하위폴더 자체는 스캔 대상에서 제외한다.
        # (구조상 자연히 안 걸리긴 하지만, 명시적으로 막아두는 게 안전)
        if entry == DUP_SUBFOLDER_NAME:
            continue
        entry_path = os.path.join(base, entry)
        if entry.endswith(".md") and os.path.isfile(entry_path):
            md_path, asset_folder, is_folder = entry_path, base, False
        elif os.path.isdir(entry_path):
            md_in_folder = next((f for f in os.listdir(entry_path) if f.endswith(".md")), None)
            if not md_in_folder:
                continue
            md_path, asset_folder, is_folder = os.path.join(entry_path, md_in_folder), entry_path, True
        else:
            continue
        try:
            with open(md_path, "r", encoding="utf-8") as f:
                content = f.read()
        except Exception:
            continue
        title = extract_h1_title(content)
        if not title:
            continue
        items.append({"title": title, "md_path": md_path,
                      "asset_folder": asset_folder, "is_folder": is_folder})
    return items


def load_seen() -> set:
    if not os.path.exists(_get_seen_path()):
        return set()
    with open(_get_seen_path(), "r", encoding="utf-8") as f:
        try:
            raw = json.load(f)
        except Exception as e:
            print(f"[경고] 중복방지 파일 로드 실패({e}) — 빈 목록으로 시작합니다. "
                  f"파일이 깨졌을 수 있으니 확인하세요: {_get_seen_path()}")
            return set()
    # [Ver7.08 추가] 예전(RSS 시절 등)에 저장된 링크는 call_from=rsslink,
    # pWise=sub&pWiseSub=R4, 페이지네이션 폼 파라미터 등 꼬리표가 붙어있는
    # 경우가 있어, 불러올 때 항상 newsId 기준 표준형으로 정규화한다. 이렇게
    # 하면 다음 저장(save_seen) 때 자연스럽게 꼬리표 중복이 정리된다.
    return {_canonicalize_news_link(link) for link in raw}


def save_seen(links: set):
    with open(_get_seen_path(), "w", encoding="utf-8") as f:
        json.dump(sorted(links), f, ensure_ascii=False, indent=2)


def _scrape_korea_news_list(list_url: str, seen: set = None, log=print, max_pages: int = 30) -> list:
    """korea.kr 뉴스 리스트 페이지(policyNewsList.do / pressReleaseList.do)를
    직접 파싱해서 feedparser entry와 동일한 인터페이스(title/link/published/
    summary 속성)를 갖는 객체 리스트를 반환한다.
    RSS(/rss/*.xml)가 서비스 종료되어(2026-07-01 전후 서버가 404 반환) 그
    대체로 만든 함수 — run_collect() 쪽 로직은 그대로 두고 여기서만 바꾼다.

    페이지네이션: 이 사이트의 "2 3 4..." 페이지 번호는 단순 URL 파라미터가
    아니라 POST 폼 제출 방식이다(브라우저 개발자도구 Network 탭으로 직접
    확인함 — pageIndex/startDate/endDate 등을 담아 같은 URL에 POST).
    한 번에 최근 1년치를 다 훑을 필요는 없으니, seen(이전에 수집된 링크
    집합)에 이미 있는 링크만으로 채워진 페이지를 만나면 그 뒤는 더 오래된
    글뿐이라는 뜻이므로 거기서 멈춘다 — RSS가 끊긴 동안 밀린 분량만
    정확히 채우고, 그 이후에는 다시 최근 1페이지만 확인하고 끝난다."""
    if not BS4_OK:
        log("[오류] beautifulsoup4 미설치. pip install beautifulsoup4 --break-system-packages 실행 후 다시 시도하세요.")
        return []

    seen = seen or set()
    today       = datetime.now().strftime("%Y-%m-%d")
    a_year_ago  = (datetime.now() - timedelta(days=365)).strftime("%Y-%m-%d")

    headers = {
        "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                       "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"),
        "Accept-Language": "ko-KR,ko;q=0.9,en;q=0.8",
        "Referer": list_url,
        "Origin": "https://www.korea.kr",
        "Content-Type": "application/x-www-form-urlencoded",
    }

    all_entries = []
    all_ids = set()
    # [Ver7.17 추가] korea.kr 리스트·상세 페이지 어디에도 실제 "시:분"
    # 정보가 없다는 걸 직접 확인했다(카드·상세 페이지 모두 날짜만 표시,
    # article:published_time 같은 메타태그도 없음 — 진짜 배포 시각은
    # 첨부 PDF/HWP 안에만 있어 목록 수집 단계에서는 알 수 없다). 그렇다고
    # 전부 "00:00"으로 고정하면 같은 날짜 기사가 전부 동시각으로 보여
    # 실제와 다르게 느껴지므로, 이 사이트가 최신순으로 내려주는 목록
    # 순서를 살려 같은 날짜 안에서 23:59부터 1분씩 감소하는 가상 시각을
    # 부여한다. 진짜 배포 시각이 아니라 "그 날짜 안에서의 상대적 순서"만
    # 정확하다는 점에 유의 — 그리드가 전부 00:00으로 뭉치는 문제와
    # 최신순 정렬이 실제 목록 순서와 어긋나는 문제를 동시에 해결한다.
    date_seq_counter = {}

    for page in range(1, max_pages + 1):
        form = {
            "pageIndex":    str(page),
            "repCodeType":  "",
            "repCode":      "",
            "startDate":    a_year_ago,
            "endDate":      today,
            "srchWord":     "",
            "cateId":       "",
            "period":       "",
            "nRepCode":     "",
            "smenu":        "",
        }
        data = urllib.parse.urlencode(form).encode("utf-8")
        try:
            req = urllib.request.Request(list_url, data=data, headers=headers, method="POST")
            with urllib.request.urlopen(req, timeout=10) as resp:
                html_bytes = resp.read()
        except Exception as e:
            log(f"  [경고] {list_url} {page}페이지 접속 실패: {e}")
            break

        soup = BeautifulSoup(html_bytes, "html.parser")
        page_entries = []

        for a in soup.find_all("a", href=re.compile(r"(policyNewsView|pressReleaseView)\.do\?newsId=\d+")):
            href = a.get("href", "")
            m = re.search(r"newsId=(\d+)", href)
            if not m:
                continue
            news_id = m.group(1)
            if news_id in all_ids:
                continue
            all_ids.add(news_id)

            link = _canonicalize_news_link(
                href if href.startswith("http") else f"https://www.korea.kr{href}"
            )
            full_text = a.get_text(" ", strip=True)

            # 카드 텍스트 끝부분 "... 2026.06.12 문화체육관광부" 패턴에서 날짜·부처 분리
            date_m = re.search(r"(\d{4})\.(\d{2})\.(\d{2})\s*([^\d]{1,20})$", full_text)
            if date_m:
                date_str = f"{date_m.group(1)}-{date_m.group(2)}-{date_m.group(3)}"
                # 같은 날짜 안에서 목록 등장 순서(=최신순)를 살려 23:59부터
                # 1분씩 감소시킨다. 하루에 1440건 넘게 나오는 경우는 없으므로
                # 실질적으로 항상 00:00 이상을 유지한다.
                seq = date_seq_counter.get(date_str, 0)
                date_seq_counter[date_str] = seq + 1
                minute_offset = max(0, 23 * 60 + 59 - seq)
                published = f"{date_str} {minute_offset // 60:02d}:{minute_offset % 60:02d}"
                dept_hint = date_m.group(4).strip()
            else:
                published = ""
                dept_hint = ""

            title_tag = a.find(["strong", "b"])
            if title_tag:
                title = title_tag.get_text(" ", strip=True)
            elif date_m:
                title = full_text[:date_m.start()].strip()[:80]
            else:
                title = full_text[:80]

            page_entries.append(SimpleNamespace(
                title=title,
                link=link,
                published=published,
                summary=full_text[:300],
                dept_hint=dept_hint,
            ))

        if not page_entries:
            # 더 이상 목록이 없음 — 마지막 페이지에 도달
            break

        all_entries.extend(page_entries)

        # 이 페이지의 기사가 전부 이전에(RSS가 살아있을 때 등) 이미 수집된
        # 적 있는 링크라면, 그 뒤 페이지는 전부 더 오래된 글뿐이므로 멈춘다.
        if seen and all(e.link in seen for e in page_entries):
            break

        time.sleep(0.3)  # 서버에 짧은 간격으로 예의를 지킨다

    if not all_entries:
        log(f"  [경고] {list_url}: 목록에서 기사 링크를 하나도 못 찾았습니다 "
            f"(페이지 구조가 바뀌었을 수 있음 — 확인 필요)")
    elif page >= max_pages:
        log(f"  [참고] {list_url}: 최대 {max_pages}페이지까지 수집하고 멈췄습니다 "
            f"(그보다 더 오래된 글이 남아있을 수 있음)")
    return all_entries


def fetch_feed(name: str, url: str, seen: set = None, log=print) -> list:
    """RSS(feedparser)는 더 이상 쓰지 않는다 — korea.kr의 /rss/*.xml이
    2026-07-01 전후로 전면 중단되어(서버가 진짜 404를 반환) feedparser로는
    수집이 안 되는 게 확인됐다(curl로 직접 검증함). 대신 사람이 보는 뉴스
    리스트 페이지를 파싱한다. 다른 도메인의 일반 RSS(.xml)는 예전처럼
    feedparser로 시도한다(하위 호환용)."""
    if "korea.kr" in url and ("policyNewsList.do" in url or "pressReleaseList.do" in url):
        return _scrape_korea_news_list(url, seen=seen, log=log)

    if "korea.kr/rss/" in url and url.rstrip().lower().endswith(".xml"):
        log(f"  [경고] {name}: korea.kr RSS 서비스는 종료되었습니다. "
            f"TAB6 설정에서 리스트 페이지 URL로 교체하세요. "
            f"(예: https://www.korea.kr/news/policyNewsList.do , "
            f"https://www.korea.kr/briefing/pressReleaseList.do)")
        return []

    if feedparser is None:
        log("[오류] feedparser 미설치. pip install feedparser")
        return []
    try:
        feed = feedparser.parse(url)
        return feed.entries
    except Exception as e:
        log(f"[경고] {name} RSS 실패: {e}")
        return []


def extract_dept_from_text(title: str, summary: str) -> str:
    """RSS entry의 제목+본문에서 실제 발표 부처명을 추출한다.
    정책뉴스/보도자료 종합 피드는 entry 자체에 부처 필드가 없고
    본문 텍스트 안에 "OOO부는 ~"처럼 섞여 있어서, _ORG_PAT로 찾는다.
    제목에 먼저 등장하는 경우가 가장 신뢰도가 높고, 없으면 본문 앞부분에서 찾는다.
    못 찾으면 "확인필요"를 반환한다."""
    m = _ORG_PAT.search(title)
    if m:
        return m.group(1)
    m = _ORG_PAT.search(summary[:300] if summary else "")
    if m:
        return m.group(1)
    return "확인필요"


def run_collect(log=print) -> list:
    """RSS 수집 → 후보 리스트 반환
    [{title, link, dept, published, pub_dt, body_type, is_new, license_warn}].
    feeds는 종합 피드(정책뉴스/보도자료) 2개뿐이며, dept(발표 부처)는
    entry 제목+본문에서 추출한다. classify도 제목만이 아니라 본문 일부까지
    같이 봐서, 제목엔 안 보이지만 본문에 good_keyword가 있는 기사를 놓치지 않는다.
    license_warn=True면 원문 하단에 공공누리 "변경금지" 조건이 붙어있다는
    뜻으로, 각색하지 말고 원문 그대로만 인용해야 한다."""
    cfg = load_config()
    good_kw = cfg["good_keywords"]
    bad_kw  = cfg["bad_keywords"]
    seen    = load_seen()
    results = []

    total_feeds  = len(cfg["feeds"])
    empty_feeds  = []
    total_entries = 0
    dept_counter  = {}

    for i, (feed_name, url) in enumerate(cfg["feeds"].items(), 1):
        entries = fetch_feed(feed_name, url, seen=seen, log=log)
        total_entries += len(entries)
        if len(entries) == 0:
            empty_feeds.append(feed_name)
            log(f"  [{i}/{total_feeds}] {feed_name}: 0건 ⚠ (URL을 확인하세요)")
        else:
            log(f"  [{i}/{total_feeds}] {feed_name}: {len(entries)}건")
        for entry in entries:
            title     = clean_title(getattr(entry, "title", ""))
            link      = getattr(entry, "link", "").strip()
            published = getattr(entry, "published", "")
            if not link:
                continue
            # 한 번이라도 수집된 적 있는 링크는 다시 보지 않는다.
            # 상태(패스/작성중/발행준비완료/포스팅완료 등) 구분은 이력·엑셀 쪽에서 하면 되고,
            # 수집 단계에서는 "이미 본 적 있는가"만 본다.
            if link in seen:
                continue
            summary   = strip_html(getattr(entry, "summary", "") or getattr(entry, "description", ""))
            # classify는 제목과 본문 앞부분을 구분해서 본다
            # (good은 둘 다 넓게, bad는 제목만 좁게 — 위 classify() 설명 참고)
            body_snippet = summary[:300] if summary else ""
            is_candidate = classify(title, body_snippet, good_kw, bad_kw)
            if is_candidate:
                # 리스트 페이지 스크래핑 항목에는 사이트가 직접 표시한 부처명
                # (dept_hint)이 있다 — 본문 정규식 추출보다 훨씬 정확하므로
                # 있으면 그걸 우선 쓰고, 없으면(예: 구형 RSS entry) 기존 방식대로
                # 본문에서 정규식으로 추출한다.
                dept_hint = getattr(entry, "dept_hint", "").strip()
                dept = dept_hint if dept_hint else extract_dept_from_text(title, summary)
                dept_counter[dept] = dept_counter.get(dept, 0) + 1
                # 후보로 확정된 기사만 원문을 한 번 더 열어 공공누리 이용조건과
                # 실제 발행 시각(메타태그)을 같이 확인한다(전체 수집 기사가
                # 아니라 실제 후보만 대상으로 해서 불필요한 네트워크 호출을
                # 줄인다).
                detail_info  = fetch_article_detail_info(link, log=log)
                license_warn = detail_info["license_warn"]
                # [Ver7.14] 상세 페이지에 article:published_time 메타태그가
                # 있으면 그걸로 실제 시:분을 교체한다. 다만 korea.kr은 직접
                # 확인 결과 이 메타태그 자체가 없어(리스트·상세 페이지 모두
                # 날짜만 표시) 사실상 항상 미스이며, 그 경우
                # _scrape_korea_news_list가 이미 채워둔 "날짜별 역순 가상
                # 시각"(Ver7.16, 목록 순서 기반 23:59부터 1분씩 감소)이
                # 그대로 유지된다 — 예전처럼 전부 "00:00"으로 뭉치지 않는다.
                if detail_info["published_time"]:
                    published = detail_info["published_time"]
                results.append({
                    "title":        title,
                    "link":         link,
                    "dept":         dept,
                    "published":    published,
                    "pub_dt":       parse_published(published),
                    "body_type":    get_body_type(link),
                    "is_new":       True,
                    "license_warn": license_warn,
                })
                if license_warn:
                    log(f"  [⚠️ 변경금지] {title[:40]}")
            seen.add(link)

    save_seen(seen)
    results.sort(key=lambda x: x['pub_dt'], reverse=True)
    log(f"[완료] 피드 {total_feeds}개 / 전체기사 {total_entries}건 → 후보 {len(results)}건 수집 (발행일 최신순)")
    if empty_feeds:
        log(f"[확인 필요] 0건 피드 {len(empty_feeds)}개: {', '.join(empty_feeds)}")
    unidentified = dept_counter.get("확인필요", 0)
    if unidentified:
        pct = round(unidentified / max(len(results), 1) * 100)
        log(f"[부처 추출] 본문에서 부처명을 못 찾은 기사 {unidentified}건 ({pct}%) — '확인필요'로 표시됨")
    return results


# ════════════════════════════════════════════════════════════
# [영역 3] 이력 관리
# ════════════════════════════════════════════════════════════

def load_history() -> list:
    if not os.path.exists(_get_history_path()):
        return []
    with open(_get_history_path(), "r", encoding="utf-8") as f:
        try:
            return json.load(f)
        except Exception:
            return []


def save_history(records: list):
    with open(_get_history_path(), "w", encoding="utf-8") as f:
        json.dump(records, f, ensure_ascii=False, indent=2)


def extract_news_id(url: str) -> str:
    """링크에서 newsId 값만 뽑아낸다. 같은 기사라도 "&call_from=rsslink"
    같은 부가 파라미터가 붙거나 빠질 수 있어서, 전체 URL 문자열을 그대로
    비교하면 같은 기사인데도 다른 링크로 취급되는 문제가 있다. newsId
    숫자만 비교하면 이 문제를 피할 수 있다."""
    m = re.search(r'newsId=(\d+)', url or "")
    return m.group(1) if m else ""


def parse_screening_result(text: str) -> list:
    """프롬프트0(후보 1차 선별)의 표 출력을 파싱한다.
    형식: 탭 구분 표, 첫 행은 헤더(링크/제목/우선순위/한줄사유),
    마지막에 "[요약] ..." 줄이 있을 수 있다(무시).
    줄 끝의 trailing whitespace, 빈 줄, 헤더 행은 건너뛴다.

    복사·붙여넣기 과정에서 탭 문자가 공백 여러 개로 바뀌는 경우가
    흔하다(특정 메신저·메모장 등을 거치면 발생). 그래서 구분자를
    탭 하나로만 제한하지 않고, 탭 또는 공백 2개 이상을 모두 구분자로
    인정한다. 그래도 못 나뉘면 줄에서 링크(http로 시작하는 토큰)만이라도
    뽑아 제목 없이 최소한으로 살린다 — 완전히 못 쓰는 것보다, 우선순위·
    사유 없이라도 검토중으로 표시되는 쪽이 낫다.

    반환: [{"link":..., "title":..., "priority":..., "reason":...}, ...]
    """
    results = []
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip():
            continue
        if line.strip().startswith("[요약]") or line.strip().startswith("링크"):
            continue

        # 1차: 탭 또는 공백 2개 이상을 구분자로 분리
        parts = [p.strip() for p in re.split(r'\t| {2,}', line) if p.strip()]

        if parts and re.match(r'^https?://\S+$', parts[0]):
            link     = parts[0]
            title    = parts[1] if len(parts) > 1 else ""
            priority = parts[2] if len(parts) > 2 else ""
            reason   = parts[3] if len(parts) > 3 else ""
            results.append({"link": link, "title": title,
                             "priority": priority, "reason": reason})
            continue

        # 2차 fallback: 구분자 분리에 실패했어도, 줄 안에 링크 토큰이
        # 있으면 링크만이라도 뽑아낸다 (제목·우선순위·사유는 빈 값)
        m = re.search(r'https?://\S+', line)
        if m:
            link = m.group(0)
            # 링크를 제외한 나머지 텍스트를 제목 후보로 사용
            rest = line.replace(link, "").strip()
            results.append({"link": link, "title": rest,
                             "priority": "", "reason": ""})
    return results


def parse_prompt_a_result(text: str) -> dict:
    """프롬프트A(전략 브리핑) 결과 텍스트를 파싱해 TAB2 자동 채우기용
    dict를 만든다.

    프롬프트A [최종 출력 형식]에서 전체 출력을 하나의 코드블럭(```)으로
    감싸도록 지시해두었으므로, 코드블럭이 있으면 그 안쪽만 사용한다.
    다만 사용자가 코드블럭 없이 본문만 복사해도 동작하도록, 코드블럭이
    없으면 원문 전체를 그대로 파싱 대상으로 삼는다(방어적 처리).

    반환:
        {
            "judgement": "통과"/"보류"/"",
            "core_keyword": str,
            "sub_keywords": [str, str, str],
            "brief": str,           # 강조할 부분 + 전개 방향 제안을 합친 텍스트
            "announce_type": str,   # ANNOUNCE_TYPE_LIST 중 매칭값(없으면 "")
            "competition": str,     # COMPETITION_LIST 중 매칭값(없으면 "")
        }
    """
    t = (text or "").strip()

    # 코드블럭(``` 또는 ```markdown 등) 안쪽만 취한다.
    # [Ver9.09 수정] V5 프롬프트A의 1차 출력([0단계]~[2단계])에는 "##"
    # 섹션 전체를 감싸는 큰 코드블럭이 없고, [2단계]의 키워드 요청
    # 목록만 담은 작은 코드블럭(```키워드1, 키워드2```)이 따로 있다.
    # 예전처럼 첫 코드블럭을 무조건 집어 쓰면 이 작은 코드블럭만 뽑혀
    # "## 강조할 부분" 등 나머지 내용이 통째로 사라진다. 그래서 코드블럭
    # 안에 "##" 섹션 헤더가 있을 때만 그 코드블럭을 진짜 감싸는
    # 코드블럭으로 신뢰하고, 없으면(=키워드 목록뿐인 작은 코드블럭)
    # 무시하고 원문 전체를 그대로 파싱 대상으로 삼는다.
    fence_m = re.search(r"```[a-zA-Z]*\r?\n(.*?)```", t, re.S)
    if fence_m and "##" in fence_m.group(1):
        t = fence_m.group(1).strip()

    result = {
        "judgement": "",
        "core_keyword": "",
        "sub_keywords": ["", "", ""],
        "brief": "",
        "announce_type": "",
        "competition": "",
        "board": None,   # [2026-09-29] "## 게시판" 섹션 판정 {name, number, conf, reason}
    }

    def _section(name: str) -> str:
        # "## 이름" 부터 다음 "## " 헤더 전까지(또는 끝까지)를 뽑는다.
        pat = rf"##\s*{re.escape(name)}\s*\r?\n(.*?)(?=\r?\n##\s|\Z)"
        m = re.search(pat, t, re.S)
        return m.group(1).strip() if m else ""

    # ── 0단계: 포스팅 가치 판정 (판정 여부·발표 유형) ──
    judge_sec = _section("포스팅 가치 판정")
    if judge_sec:
        jm = re.search(r"판정\s*:\s*(통과|보류)", judge_sec)
        if jm:
            result["judgement"] = jm.group(1)
        tm = re.search(r"발표\s*유형\s*:\s*([^\r\n]+)", judge_sec)
        if tm:
            type_raw = tm.group(1)
            for cand in ANNOUNCE_TYPE_LIST:
                if cand and cand in type_raw:
                    result["announce_type"] = cand
                    break

    # ── 1단계 + 3단계: 강조할 부분 / 전개 방향 → 한 텍스트로 합침 ──
    emph_sec = _section("강조할 부분")
    direction_sec = _section("글의 전개 방향 제안")
    brief_parts = []
    if emph_sec:
        brief_parts.append("[강조할 부분]\n" + emph_sec)
    if direction_sec:
        brief_parts.append("[글의 전개 방향 제안]\n" + direction_sec)
    result["brief"] = "\n\n".join(brief_parts)

    # ── 2단계: 핵심 키워드 (첫 "덩어리" = 키워드, 경쟁 예상 함께 추출) ──
    # [Ver8.21 수정] 기존엔 core_sec의 lines[0](첫 줄)만 그대로 썼는데,
    # Claude 웹 화면에서 자동 줄바꿈(소프트 랩)된 상태로 복사하면 실제
    # 개행문자가 같이 딸려와 (1) 여는 괄호만 있고 닫는 괄호는 다음 줄에
    # 남아 잘리거나, (2) 헤딩 기호(#, ##, ### 등)가 줄 앞에 그대로
    # 남는 문제가 있었다. 첫 줄부터 시작해 괄호가 짝이 맞을 때까지(또는
    # "선택 이유"/"경쟁 예상" 같은 다음 필드 줄을 만날 때까지) 여러 줄을
    # 이어붙이고, 마지막에 선행 마크다운 헤딩 기호(#)를 제거한다.
    core_sec = _section("핵심 키워드")
    if core_sec:
        lines = [l.strip() for l in core_sec.splitlines() if l.strip()]
        if lines and not lines[0].startswith(("선택 이유", "경쟁 예상")):
            kw_lines = []
            for l in lines:
                if l.startswith(("선택 이유", "경쟁 예상")):
                    break
                kw_lines.append(l)
                joined = " ".join(kw_lines)
                opens  = joined.count("(") + joined.count("（")
                closes = joined.count(")") + joined.count("）")
                if opens <= closes:
                    break
            raw_kw = re.sub(r'^#+\s*', '', " ".join(kw_lines))
            result["core_keyword"] = raw_kw.strip("()（） ").strip()
        cm = re.search(r"경쟁\s*예상\s*:\s*([^\r\n]+)", core_sec)
        if cm:
            comp_raw = cm.group(1)
            # [V15 반영] "수요 미확인 — …경쟁정도 낮음…"이 뒤쪽 "낮음"에 먼저
            # 걸리지 않도록 새 값만 먼저 확인한다. 나머지는 원본 동작 그대로.
            # [V17 반영] "조합 수요 미확인"은 "수요 미확인"을 포함하므로 더 긴 값을 먼저 확인한다.
            if "조합 수요 미확인" in comp_raw:
                result["competition"] = "조합 수요 미확인"
            elif "수요 미확인" in comp_raw:
                result["competition"] = "수요 미확인"
            else:
                for cand in COMPETITION_LIST:
                    if cand and cand in comp_raw:
                        result["competition"] = cand
                        break

    # ── 2단계: 참고용 키워드 후보 [후보 N] 키워드 ──
    cand_sec = _section("참고용 키워드 후보")
    if cand_sec:
        for idx_str, kw in re.findall(r"\[\s*후보\s*(\d)\s*\]\s*([^\r\n]+)", cand_sec):
            idx = int(idx_str) - 1
            if 0 <= idx < 3:
                # [Ver8.21] 핵심 키워드와 동일한 헤딩 기호(#) 잔존 문제 방지
                cleaned = re.sub(r'^#+\s*', '', kw.strip())
                result["sub_keywords"][idx] = cleaned.strip("()（） ")

    # ── [2026-09-29] 게시판 판정: _copy_prompt_a()가 덧붙인 지시에 따라 2차
    # 출력 끝에 붙는 "## 게시판" 섹션. 설정이 없으면 건너뛴다.
    if HAS_BOARD_MODULE:
        try:
            result["board"] = board_mod.parse_board_section(text, _load_board_cfg())
        except Exception as e:
            print(f"[게시판 판정 파싱] 실패: {e}")

    return result


def policy_count_blog_search_results(source: str):
    """[Ver9.12 신규] 블로그tab 검색결과 페이지(따옴표 없는 자연어
    검색) HTML에서 결과 건수를 센다. Naver_blog_rank_module의
    rank_extract_result_items()와 같은 방식(data-template-id="ugcItem"
    컨테이너 개수)을 쓰되, 여기서는 특정 blog_id를 찾는 게 아니라
    "건수 + 완전 미인식 여부"만 필요하므로 개수만 반환하는 경량 버전.

    반환: (count:int, no_result:bool)
    no_result=True면 "'...'에 대한 검색결과가 없습니다"라는 빨간
    안내문이 뜬 것 — 프롬프트A V10 [검색결과 없음(미인식) 판정]에
    따라 이 표현은 후보에서 제외해야 한다.
    """
    try:
        text = source.replace('\\/', '/')
        if '에 대한 검색결과가 없습니다' in text:
            return 0, True
        count = text.count('data-template-id="ugcItem"')
        return count, False
    except Exception as e:
        print(f"❌ [제목정밀검색] 블로그tab 결과 파싱 오류: {e}")
        return 0, False


def policy_count_integrated_search_results(source: str):
    """[Ver9.12 신규] 통합검색 결과(따옴표 없는 자연어 검색) HTML에서,
    광고(파워링크)/AI브리핑/추천위젯을 제외한 "진짜 검색결과"만 센다.
    Naver_blog_rank_module의 rank_extract_integrated_result_positions()와
    같은 방식(data-block-id="web|review|kin|video/..." 컨테이너)을 쓴다.

    반환: (count:int, no_result:bool)
    """
    try:
        text = source.replace('\\/', '/')
        if '에 대한 검색결과가 없습니다' in text:
            return 0, True
        count = len(re.findall(r'data-block-id="(?:web|review|kin|video)/[^"]*"', text))
        return count, False
    except Exception as e:
        print(f"❌ [제목정밀검색] 통합검색 결과 파싱 오류: {e}")
        return 0, False


# [Ver10.02] 제목의 구분 쉼표. "1,200만 원"처럼 숫자 사이에 낀 천 단위 쉼표는 구분 쉼표로 보지 않는다.
_TITLE_COMMA_RE = re.compile(r"(?<!\d)[,，、]|[,，、](?!\d)")


def policy_split_title_front(title: str) -> str:
    """[Ver9.19 신규, Ver9.29 주석 갱신] 제목의 "앞 핵심구"를 자른다. 프롬프트A V17 제목 구조가
    "[메인 + 서브 + 변화], [롱테일 + 세부사항]"이므로(V16은 "[본문 핵심 키워드 + 변화], [서브 키워드]")
    첫 콤마 앞이 앞 핵심구다. 콤마가 없으면 앞 30자 안쪽(어절 단위)으로 자른다."""
    t = (title or "").strip().rstrip("?？!！. ").strip()
    m = _TITLE_COMMA_RE.search(t)
    if m:
        # [Ver10.06] A V20 앞부분의 작은따옴표 속마음 후킹은 검색어가 아니므로 빼고 메인·서브만 쓴다.
        front = policy_strip_title_hook(t[:m.start()])
        if len(front) >= 4:
            return front
    t = policy_strip_title_hook(t)
    if len(t) <= 30:
        return t
    cut = t[:30]
    sp = cut.rfind(" ")
    return (cut[:sp] if sp >= 8 else cut).strip()


def policy_resolve_keyword_for_title(title: str, candidates: list) -> tuple:
    """[Ver9.19 신규] 제목에 맞는 "핵심 키워드"를 정한다.
    - 제목이 A 후보 제목과 같으면(공백 무시) 그 후보의 핵심키워드
    - 아니면 제목의 뒷 구절(첫 콤마 뒤) — [Ver10.02] 후보의 핵심키워드와 같은 롱테일 축으로 맞춘다
    - 쉼표가 없어 뒷 구절이 없으면 앞 핵심구
    반환: (keyword, source, cand_index) — source는 "candidate"/"back"/"front"/"".
    프롬프트A V16·V17에서 후보의 핵심키워드는 뒷부분(서브·롱테일) 축이고, 중복체크·
    핵심DB(keyword)·A의 자기잠식 확인이 이 값을 쓴다."""
    t = (title or "").strip()
    if not t:
        return "", "", -1
    norm = lambda x: re.sub(r"\s+", "", x or "")
    for i, c in enumerate(candidates or []):
        if c.get("title") and norm(c["title"]) == norm(t) and c.get("core_keyword"):
            return c["core_keyword"].strip(), "candidate", i
    back = policy_split_title_back(t)
    if back:
        return back, "back", -1
    return policy_split_title_front(t), "front", -1


def policy_split_title_back(title: str) -> str:
    """[Ver9.26 신규] 제목의 첫 쉼표 뒤 구절(뒷구). 쉼표가 없거나 4자 미만이면 빈 문자열.
    앞구(policy_split_title_front)는 선점용이라 검색이 거의 없고 실제 유입은 뒷구가 받는다."""
    t = (title or "").strip().rstrip("?？!！. ").strip()
    m = _TITLE_COMMA_RE.search(t)
    if not m:
        return ""
    back = t[m.end():].strip()
    return back if len(back) >= 4 else ""


def policy_extract_result_items(source: str) -> list:
    """[Ver9.20 신규, Ver9.27 수정] 블로그tab 결과 HTML에서 결과 항목을 등장 순서대로 뽑는다.
    Naver_blog_rank_module의 rank_extract_result_items()와 같은 방식이다 —
    항목 컨테이너(data-template-id="ugcItem") 단위로 나누고, 블로그명
    (articleSourceJSX_title)과 제목 링크(data-heatmap-target=".*blg" +
    headline1 span)를 정규식으로 읽는다. 티스토리 등 다른 플랫폼 글도 같은 목록에
    순서대로 섞여 나오므로 도메인으로 거르지 않는다.
    정규식이 안 맞는 카드(화면 구조가 바뀐 경우)는 카드 안 첫 링크 텍스트(6자 이상,
    블로그명 제외)를 제목으로 대체 추출한다. [Ver9.27] 그래도 제목을 못 찾은 카드는 버리지
    않고 "(제목 추출 실패)"와 카드 원문 일부를 담아 남긴다(자료를 걸러내지 않기 위함).
    반환: [{"title","link","source_name","text","anchors","parse_failed","raw"}, ...]"""
    def _strip(x):
        return re.sub(r"<[^>]+>", "", x or "").strip()

    try:
        text = (source or "").replace("\\/", "/")
        items = []
        for block in text.split('data-template-id="ugcItem"')[1:]:
            m_name = re.search(r'articleSourceJSX_title"[^>]*><span[^>]*>(.*?)</span>', block, re.S)
            m_title = re.search(
                r'href="([^"]+)"[^>]*data-heatmap-target="\.[a-z]*blg"[^>]*>'
                r'<span[^>]*sds-comps-text-type-headline1[^>]*>(.*?)</span>',
                block, re.S)
            source_name = html.unescape(_strip(m_name.group(1))) if m_name else ""
            link, title = "", ""
            if m_title:
                link = html.unescape(m_title.group(1))
                title = re.sub(r"\s+", " ", html.unescape(_strip(m_title.group(2)))).strip()
            else:
                for href, inner in re.findall(r'<a\b[^>]*href="([^"]+)"[^>]*>(.*?)</a>', block[:8000], re.S):
                    t = re.sub(r"\s+", " ", html.unescape(_strip(inner))).strip()
                    if len(t) >= 6 and t != source_name:
                        link, title = html.unescape(href), t
                        break
            if not title:
                raw = re.sub(r"\s+", " ", html.unescape(_strip(block[:6000]))).strip()[:200]
                items.append({"title": "(제목 추출 실패)", "link": "", "source_name": source_name,
                              "text": raw, "anchors": [], "parse_failed": True, "raw": raw})
                continue
            items.append({"title": title, "link": link, "source_name": source_name,
                          "text": title, "anchors": [title], "parse_failed": False, "raw": ""})
        return items
    except Exception as e:
        print(f"❌ [제목정밀검색] 결과 항목 추출 오류: {e}")
        return []


def policy_check_captcha(driver):
    """[Ver9.20 신규, Ver9.24 재작성] 캡차/차단 감지. 반환: (차단 여부, 사유)
    순위 모듈의 rank_check_naver_captcha()는 모듈 안에서 호출된 적이 없고, 페이지 소스
    전체에서 문구를 찾아 정상 페이지에도 걸릴 수 있어(스크립트에 "잠시 후 다시" 등이
    들어 있음) 그대로 쓰지 않는다. 판단 순서:
      1) 주소가 로그인 페이지/captcha면 차단
      2) 결과 카드(ugcItem)가 있으면 정상
      3) 카드가 없을 때만, 화면에 보이는 글자(innerText)에서 캡차 고유 문구를 찾는다"""
    try:
        url = driver.current_url or ""
        if "nid.naver.com/nidlogin" in url:
            return True, "로그인 페이지로 이동됨"
        if "captcha" in url.lower():
            return True, "주소에 captcha 포함"
        page = driver.page_source or ""
        if 'data-template-id="ugcItem"' in page:
            return False, ""
        try:
            visible = driver.execute_script("return document.body ? document.body.innerText : ''") or ""
        except Exception:
            visible = ""
        for kw in ["자동입력 방지", "로봇이 아님을 확인", "비정상적인 접근", "일시적으로 제한", "보안문자"]:
            if kw in visible:
                return True, f"화면에 '{kw}' 문구"
        if len(visible.strip()) < 400 and "잠시 후 다시" in visible:
            return True, "짧은 오류 화면에 '잠시 후 다시' 문구"
    except Exception:
        pass
    return False, ""


def policy_collect_blog_results(driver, keyword: str, max_results: int = 30, progress_fn=None,
                                info=None, rounds=None):
    """[Ver9.20 신규, Ver9.27 수정] 블로그탭을 따옴표 없이 검색해 결과 항목을 스크롤하며 모은다
    (rank_selenium_collect_results()의 수집 로직 이식). 페이지 구조상 결과는 스크롤할수록
    더 로드되므로 max_results건이 모이거나 새 항목이 두 번 연속 안 늘면 멈춘다.
    progress_fn(수집 건수)가 있으면 수집이 늘 때마다 호출한다(진행 표시용).
    info(dict)를 주면 수집 종료 사유("stop": cap/end/rounds/red), 제목 추출 실패 건수
    ("parse_failed")를 채우고, 차단으로 판정했을 때는 사유·주소·페이지 제목·화면 문구 일부도 채운다.
    반환: (items, status) — status: "ok" / "red"(빨간 안내문) / "captcha"(차단 의심) / "error"."""
    rounds = rounds or PRECHECK_SCROLL_ROUNDS
    try:
        url = ("https://search.naver.com/search.naver?ssc=tab.blog.all&sm=tab_jum"
               f"&query={urllib.parse.quote(keyword)}")
        driver.get(url)
        time.sleep(random.uniform(1.5, 3.0))
        blocked, reason = policy_check_captcha(driver)
        if blocked:
            # 일시적인 화면일 수 있어 잠시 뒤 한 번만 다시 열어 확인한다.
            time.sleep(random.uniform(4.0, 6.0))
            driver.get(url)
            time.sleep(random.uniform(2.0, 3.5))
            blocked, reason = policy_check_captcha(driver)
        if blocked:
            if info is not None:
                info["reason"] = reason
                try:
                    info["url"] = driver.current_url
                    info["title"] = driver.title
                    info["visible"] = (driver.execute_script(
                        "return document.body ? document.body.innerText : ''") or "").strip()[:150]
                except Exception:
                    pass
            return [], "captcha"
        if "에 대한 검색결과가 없습니다" in (driver.page_source or ""):
            if info is not None:
                info["stop"] = "red"
            return [], "red"

        cumulative, seen = [], set()

        def _collect():
            new = 0
            for it in policy_extract_result_items(driver.page_source):
                key = it.get("link") or ("raw:" + it.get("raw", "")[:120]) or it.get("title")
                if not key or key in seen:
                    continue
                seen.add(key)
                cumulative.append(it)
                new += 1
            return new

        def _progress():
            if progress_fn:
                try:
                    progress_fn(min(len(cumulative), max_results))
                except Exception:
                    pass

        _collect()
        _progress()
        no_change = 0
        stop = "rounds"
        for _ in range(rounds):
            if len(cumulative) >= max_results:
                stop = "cap"
                break
            driver.execute_script("window.scrollTo(0, document.body.scrollHeight);")
            time.sleep(random.uniform(1.2, 2.2))
            if _collect() == 0:
                no_change += 1
                if no_change >= 2:
                    stop = "end"
                    break
            else:
                no_change = 0
                _progress()
        else:
            if len(cumulative) >= max_results:
                stop = "cap"
        result = cumulative[:max_results]
        if info is not None:
            info["stop"] = stop
            info["parse_failed"] = sum(1 for it in result if it.get("parse_failed"))
        return result, "ok"
    except Exception as e:
        print(f"❌ [제목정밀검색] '{keyword}' 검색 오류: {e}")
        return [], "error"


_PRECHECK_JOSA = ["에서", "으로", "에게", "까지", "부터", "보다", "처럼",
                  "는", "은", "이", "가", "을", "를", "도", "에", "의", "과", "와", "로"]


def policy_relevance_tokens(phrase: str) -> list:
    """[Ver9.19 신규] 관련 글 판정용 핵심 토큰. 공백·구두점으로 나눈 뒤 조사를
    떼고(2글자 이상 남을 때만), 일반어(PRECHECK_STOP_WORDS)와 1글자 토큰은 뺀다.
    "신고가"는 "신고"로 줄어들어 "신고"가 들어간 글과 매칭된다(주식 글이
    섞이는 문제는 다른 토큰 일치 수 기준으로 걸러진다)."""
    out = []
    phrase = re.sub(r"(?<=\d)[,，](?=\d)", "", phrase or "")   # [Ver10.02] "1,200만" → "1200만"
    for tok in re.split(r"[\s,，、·/()\[\]?？!！~\-–—…\"'“”‘’]+", phrase):
        tok = tok.strip()
        if not tok:
            continue
        for j in _PRECHECK_JOSA:
            if tok.endswith(j) and len(tok) - len(j) >= 2:
                tok = tok[:-len(j)]
                break
        if len(tok) < 2 or tok in PRECHECK_STOP_WORDS or tok in PRECHECK_GENERIC_WORDS:
            continue
        if tok not in out:
            out.append(tok)
    return out


def policy_count_relevant(items: list, phrase: str, min_hits=None):
    """[Ver9.19 신규, Ver9.20 수정] items(제목) 중 phrase의 핵심 토큰이 40% 이상(최소 2개, 토큰이
    2개 미만이면 전부) 제목에 들어 있는 것을 "관련 글"로 센다.
    min_hits를 주면 그 값을 쓴다(전체 제목 검색용). 반환: (관련 글 수, 토큰, 기준)"""
    toks = policy_relevance_tokens(phrase)
    if not toks:
        return 0, toks, 0
    need = min_hits if min_hits else max(2, int(len(toks) * 0.4 + 0.5))
    need = min(need, len(toks))
    rel = 0
    for it in items:
        hay = it.get("text", "")
        if sum(1 for t in toks if t in hay) >= need:
            rel += 1
    return rel, toks, need


def policy_count_partial(items: list, phrase: str, head: int = None) -> int:
    """[Ver9.26 신규] "부분일치" 글 수 — 검색어의 앞쪽 핵심어(head개) 중 하나라도 제목에 들어 있는
    글. policy_count_relevant()(핵심어 2개 이상)보다 넓게 세므로 "얼마나 몰려 있는가"(밀도)를 볼 때
    쓴다. 실제 검색결과 8건으로 검증: 정밀도 약 0.87, 재현율 약 0.95(기존 기준은 재현율 약 0.5)."""
    head = head or PRECHECK_PARTIAL_HEAD
    toks = policy_relevance_tokens(phrase)[:head]
    if not toks:
        return 0
    return sum(1 for it in items if any(t in it.get("text", "") for t in toks))


def policy_clean_tokens(phrase: str) -> list:
    """[Ver9.28 신규] 키워드로 쓸 토큰. 조사를 뗀 토큰에서 동사·의문형 어미("발견되면", "정해졌을까" 등)와
    변화·의문 표현(PRECHECK_CHANGE_WORDS)을 빼고, "수거하" 같은 동사 어간은 "수거"로 줄인다."""
    out = []
    for t in policy_relevance_tokens(phrase):
        if len(t) >= 3 and (t.endswith(PRECHECK_VERBISH) or t.endswith("까")):
            continue
        if len(t) >= 3 and t.endswith("하"):
            t = t[:-1]
        if t in PRECHECK_CHANGE_WORDS or t in PRECHECK_GENERIC_WORDS or len(t) < 2:
            continue
        if t not in out:
            out.append(t)
    return out


def policy_title_keywords(title: str) -> tuple:
    """[Ver9.28 신규, Ver9.29 수정] 제목에서 (핵심 키워드 목록, 서브 키워드 목록)을 뽑는다. 첫 쉼표 앞부분의
    토큰(프롬프트 A V17의 메인·서브)이 핵심 키워드, 뒷부분(롱테일) 토큰이 서브 키워드(앞부분에 이미 있는 것은 제외)다.
    "관리"·"지역" 같은 일반어(PRECHECK_GENERIC_WORDS)는 제외한다. 쉼표가 없으면 전체가 핵심
    키워드다. 앞부분이 변화 표현뿐이라 핵심 키워드가 비면 뒷부분 앞쪽 2개를 핵심으로 삼는다."""
    t = (title or "").strip().rstrip("?？!！. ").strip()
    m = _TITLE_COMMA_RE.search(t)
    front, back = (t[:m.start()], t[m.end():]) if m else (t, "")
    front = policy_strip_title_hook(front)   # [Ver10.06] 속마음 후킹 토큰은 핵심 키워드가 아니다
    core = policy_clean_tokens(front)
    # 서브 키워드 중 핵심 키워드와 같거나 포개지는 것(예: 핵심 "이물"과 서브 "이물질")은 이중 계산을
    # 막기 위해 뺀다.
    sub = [x for x in policy_clean_tokens(back)
           if x not in core and not any(c in x or x in c for c in core)]
    if not core:
        core, sub = sub[:2], sub[2:]
    return core, sub


def policy_score_text(text: str, core: list, sub: list) -> tuple:
    """[Ver9.28 신규] 결과 제목 하나의 점수. 핵심 키워드 개당 3점, 서브 키워드 개당 1점, 2개 이상 일치하면
    1개 추가할 때마다 +1(4개까지), 핵심·서브가 함께 일치하면 +2. 반환: (점수, 일치한 핵심, 일치한 서브)."""
    def _hit(tok):
        # [Ver9.29] "만성질환자"처럼 대상군을 뜻하는 "~자" 키워드는 "만성질환"으로 쓴 글도 일치로 본다.
        return tok in text or (len(tok) >= 4 and tok.endswith("자") and tok[:-1] in text)
    text = re.sub(r"(?<=\d)[,，](?=\d)", "", text or "")   # [Ver10.02] 결과 제목의 "1,200만"도 "1200만"으로 맞춤
    mc = [c for c in core if _hit(c)]
    ms = [x for x in sub if _hit(x)]
    m = len(mc) + len(ms)
    sc = PRECHECK_W_CORE * len(mc) + PRECHECK_W_SUB * len(ms)
    if m >= 2:
        sc += PRECHECK_BONUS_MORE * (min(m, PRECHECK_BONUS_MORE_CAP) - 1)
    if mc and ms:
        sc += PRECHECK_BONUS_CROSS
    return sc, mc, ms


def policy_classify_items(items: list, title: str) -> dict:
    """[Ver9.27 신규, Ver9.28 재작성] 각 결과 제목에 점수·등급·일치 키워드를 매긴다(items에 score/tier/
    matched 기록). 제목의 핵심 키워드(높게)·서브 키워드(낮게)·복수 일치 가산으로 강(6점 이상)·중(3~5)·
    약(1~2)·무관(0)을 나눈다. 목록에서 항목을 걸러내지 않고 표시만 붙인다.
    반환: {"core": [...], "sub": [...], "counts": {"strong","mid","weak","none"}}"""
    core, sub = policy_title_keywords(title)
    counts = {"strong": 0, "mid": 0, "weak": 0, "none": 0}
    for it in items:
        text = it.get("text") or it.get("title", "")
        sc, mc, ms = policy_score_text(text, core, sub)
        tier = ("strong" if sc >= PRECHECK_TIER_STRONG else "mid" if sc >= PRECHECK_TIER_MID
                else "weak" if sc >= 1 else "none")
        it["score"], it["tier"], it["matched"] = sc, tier, mc + ms
        counts[tier] += 1
    return {"core": core, "sub": sub, "counts": counts}


def policy_segment_result(prefix: str, title: str, items: list, status: str, meta: dict) -> dict:
    """[Ver9.27 신규, Ver9.28 수정] 한 번의 검색(전체 제목/앞구/뒷구) 결과를 결과 dict 키(prefix_...)로
    만든다. 세 검색 모두 같은 제목의 핵심·서브 키워드로 채점한다."""
    cls = policy_classify_items(items, title)
    c = cls["counts"]
    return {f"{prefix}_count": len(items), f"{prefix}_status": status, f"{prefix}_zero": status == "red",
            f"{prefix}_strong": c["strong"], f"{prefix}_mid": c["mid"], f"{prefix}_weak": c["weak"],
            f"{prefix}_none": c["none"],
            f"{prefix}_stop": (meta or {}).get("stop", ""), f"{prefix}_failed": (meta or {}).get("parse_failed", 0)}


def policy_group_exists(r: dict, prefix: str) -> bool:
    """[Ver9.27 신규] 관련 글 그룹이 있는가 — 강 1건 이상, 또는 강이 없어도 중이 PRECHECK_MID_MIN 이상."""
    return r.get(f"{prefix}_strong", 0) >= 1 or r.get(f"{prefix}_mid", 0) >= PRECHECK_MID_MIN


def policy_count_similar_titles(items: list, title: str, ratio: float = None) -> int:
    """[Ver9.19 신규] 카드의 링크 텍스트 중 후보 제목과 매우 비슷한(글자 유사도
    ratio 이상) 것이 있는 카드 수. 같은 제목·유사 제목이 이미 있으면 유사문서로
    묶이거나 그 글과 직접 경쟁하게 된다."""
    ratio = PRECHECK_SIMILAR_RATIO if ratio is None else ratio

    def _norm(x):
        return re.sub(r"[\s\W_]+", "", x or "")

    base = _norm(title)
    if not base:
        return 0
    n = 0
    for it in items:
        for a in it.get("anchors", []):
            b = _norm(a)
            if not b or not (0.5 <= len(b) / len(base) <= 2.0):
                continue
            if difflib.SequenceMatcher(None, base, b).ratio() >= ratio:
                n += 1
                break
    return n


def policy_precheck_verdict(r: dict):
    """[Ver9.19 신규, Ver9.27 재작성] 검색 결과 dict → (level, 표시 문구).
    level: 0=❌(자리 없음/미인식) 1=⚠️(확인 필요) 2=✅
    판단 원칙(프롬프트A V16 [검색 노출 폭 확인]) — 등급은 Ver9.28 역할 기반 점수 기준
    (policy_score_text: 핵심 키워드 개당 3점·서브 키워드 개당 1점·복수 일치 가산·핵심+서브 동시 일치 +2,
    강 6점 이상·중 3~5·약 1~2):
      - 전체 제목·앞 핵심구: 관련 글 그룹(강 1건 이상 또는 중 3건 이상)이 있어야 하고 없으면 ❌.
      - 전체 제목: 같은/유사 제목이 있으면 ⚠️.
      - 뒷구(검색했을 때): 실제 유입 자리라 그룹이 없으면 ⚠️.
    표시는 "강N·중N·약N/수집 건수". 판정은 참고이며 목록 전체는 복사로 확인한다."""
    if r.get("blocked"):
        why = f" (사유: {r['block_reason']})" if r.get("block_reason") else ""
        return 1, ("⛔ 네이버 차단/캡차 의심" + why +
                   " — 결과 신뢰 불가. 잠시 후 다시 시도하거나 🔍 버튼으로 직접 확인")
    stt = [r.get("full_status"), r.get("front_status")] + ([r.get("back_status")] if r.get("back") else [])
    if "error" in stt:
        return 1, "⚠️ 검색 오류 — 🔍 버튼으로 직접 확인"
    if r.get("full_zero") or r.get("front_zero"):
        return 0, "❌ 미인식(빨간 안내문) — 후보 제외 권장"

    def tiers(p):
        return (f"강{r.get(p + '_strong', 0)}·중{r.get(p + '_mid', 0)}·약{r.get(p + '_weak', 0)}"
                f"/{r.get(p + '_count', 0)}")

    if not policy_group_exists(r, "full"):
        return 0, f"❌ 전체 제목 관련 글 없음 ({tiers('full')}) — 들어갈 자리 없음"
    if not policy_group_exists(r, "front"):
        return 0, f"❌ 앞구 '{r.get('front', '')}' 관련 글 없음 ({tiers('front')}) — 들어갈 자리 없음"
    warns = []
    if r.get("similar", 0) >= 1:
        warns.append(f"유사 제목 {r['similar']}건")
    if r.get("ambiguous"):
        warns.append("'" + "·".join(r["ambiguous"]) + "' 오독 위험")
    base = f"전체 {tiers('full')} · 앞구 {tiers('front')}"
    front_all = r.get("front_strong", 0) + r.get("front_mid", 0) + r.get("front_weak", 0)
    if front_all > PRECHECK_FRONT_DENSE_MAX:
        base += "(관련 글 다수)"      # 참고 표시 — 경고 아님
    if r.get("back"):
        base += f" · 뒷구 {tiers('back')}"
        if r.get("back_zero"):
            warns.append("뒷구 검색결과 없음(빨간 안내문)")
        elif not policy_group_exists(r, "back"):
            warns.append("뒷구 관련 글 그룹 없음")
    if warns:
        return 1, "⚠️ " + base + " — " + ", ".join(warns)
    return 2, "✅ " + base


_PRECHECK_STATUS_TEXT = {"ok": "", "red": "빨간 안내문(검색결과 없음)", "captcha": "차단/캡차 감지",
                         "error": "검색 오류"}


_PRECHECK_STOP_TEXT = {"cap": "수집 상한 도달(더 있을 수 있음)", "end": "더 이상 안 나옴",
                       "rounds": "스크롤 한도 도달(더 있을 수 있음)", "red": "검색결과 없음"}
_PRECHECK_MARK = {"strong": "강", "mid": "중", "weak": "약", "none": "  "}


def policy_format_precheck_report(candidates: list, results: list, packs: list) -> str:
    """[Ver9.20 신규, Ver9.27 재작성] 제목별 전체 제목·앞 핵심구·뒷 구절 검색 결과를 Claude에
    붙여넣기 좋은 텍스트로 만든다. 프로그램은 항목을 걸러내지 않고 수집된 목록 전체를
    순서대로 담으며, 각 줄 앞의 [강/중/약]은 핵심어 가중치 점수로 매긴 참고 표시일 뿐이다."""
    lines = ["(블로그탭, 따옴표 없는 자연어 검색 결과입니다. 프로그램이 걸러낸 항목은 없고 수집된 목록 "
             "전체를 순서대로 담았습니다. 줄 앞의 [강/중/약]과 점수는 프로그램이 매긴 참고 표시입니다 — 내 "
             f"제목의 핵심 키워드(앞부분)가 결과 제목에 있으면 개당 {PRECHECK_W_CORE}점, 서브 키워드(뒷부분)는 "
             f"개당 {PRECHECK_W_SUB}점, 2개 이상 일치하면 1개 더할 때마다 +{PRECHECK_BONUS_MORE}, 핵심·서브가 "
             f"함께 일치하면 +{PRECHECK_BONUS_CROSS}점. 강 {PRECHECK_TIER_STRONG}점 이상, "
             f"중 {PRECHECK_TIER_MID}~{PRECHECK_TIER_STRONG - 1}점, 약 1~{PRECHECK_TIER_MID - 1}점, 공백 0점. "
             "추정치이니 목록을 직접 보고 판단해 주세요. \"관리\"·\"지역\" 같은 일반어는 키워드에서 뺐습니다.)", ""]
    for i, cand in enumerate(candidates or []):
        title = (cand or {}).get("title", "")
        if not title:
            continue
        pack = packs[i] if i < len(packs) else None
        r = results[i] if i < len(results) else None
        label = f"후보 {i + 1}" if i < 3 else "직접 입력 제목"
        lines.append(f"## {label}: {title} ({len(title)}자)")
        if not pack or not r:
            lines += ["(제목정밀검색 결과 없음)", ""]
            continue
        front, back = r.get("front", ""), r.get("back", "")
        keys = [("full", "전체 제목 검색", title)]
        if front and front != title.strip().rstrip("?？!！. ").strip():
            keys.append(("front", "앞 핵심구 검색", front))
        else:
            lines.append("(앞 핵심구가 전체 제목과 같아 전체 제목 검색 한 번만 했습니다)")
        if back:
            keys.append(("back", "뒷 구절 검색", back))
        for key, name, query in keys:
            items = pack.get(key, []) or []
            lines.append(f"### {name} — 검색어: {query}")
            lines.append(f"- 핵심 키워드({PRECHECK_W_CORE}점): {' · '.join(r.get('kw_core', [])) or '-'}"
                         f" / 서브 키워드({PRECHECK_W_SUB}점): {' · '.join(r.get('kw_sub', [])) or '-'}")
            info = (f"- 수집 {len(items)}건 · 강 {r.get(key + '_strong', 0)} · 중 {r.get(key + '_mid', 0)} · "
                    f"약 {r.get(key + '_weak', 0)} · 무관 {r.get(key + '_none', 0)}")
            if key == "full":
                info += f" · 유사 제목 {r.get('similar', 0)}"
            stop = _PRECHECK_STOP_TEXT.get(r.get(key + "_stop", ""), "")
            if stop:
                info += f" · 종료: {stop}"
            if r.get(key + "_failed"):
                info += f" · 제목 추출 실패 {r[key + '_failed']}건"
            st = _PRECHECK_STATUS_TEXT.get(r.get(key + "_status", "ok"), "")
            if st:
                info += f" · 상태: {st}"
            lines.append(info)
            for n, it in enumerate(items, 1):
                nm = f" [{it['source_name']}]" if it.get("source_name") else ""
                mark = f"[{_PRECHECK_MARK.get(it.get('tier', 'none'), '  ')}{it.get('score', 0) or ''}]"
                if it.get("matched"):
                    mark += "(" + "·".join(it["matched"]) + ")"
                body = it.get("title", "")
                if it.get("parse_failed"):
                    body += f" 원문: {it.get('raw', '')}"
                lines.append(f"{n}. {mark} {body}{nm}")
            lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def policy_build_raw_record(sl: int, title: str, result: dict, pack: dict) -> dict:
    """[Ver9.27 신규] 검색 1건의 원자료(전체 목록 + 점수·등급)를 저장용 dict로 만든다 —
    나중에 다시 검색하지 않고 재분석하기 위한 기록(title_precheck_raw.jsonl)."""
    segs = {}
    for key in ("full", "front", "back"):
        if key == "back" and not result.get("back"):
            continue
        items = pack.get(key) or []
        segs[key] = {
            "query": title if key == "full" else result.get(key, ""),
            "status": result.get(key + "_status", ""), "stop": result.get(key + "_stop", ""),
            "keywords": {"core": result.get("kw_core", []), "sub": result.get("kw_sub", [])},
            "counts": {t: result.get(f"{key}_{t}", 0) for t in ("strong", "mid", "weak", "none")},
            "items": [{"n": n, "title": it.get("title", ""), "blog": it.get("source_name", ""),
                       "link": it.get("link", ""), "score": it.get("score", 0), "tier": it.get("tier", ""),
                       "matched": it.get("matched", []),
                       "parse_failed": bool(it.get("parse_failed"))} for n, it in enumerate(items, 1)]}
    return {"slot": sl, "title": title, "similar": result.get("similar", 0),
            "level": result.get("level"), "segments": segs}


def parse_title_candidates(text: str) -> list:
    """프롬프트A [5단계] 결과(또는 [재추천 시 회피 목록 처리] 결과)의
    "## 제목 후보" 섹션에서 [후보 N] 블록 최대 3개를 파싱한다.

    프롬프트A V10 [5단계] 형식:
        ## 제목 후보

        [후보 1]
        제목: ...
        핵심키워드: ...
        선택 근거: ...
        도입부 구조: ...
        도입부 첫 문장 지시: ...

        [후보 2] ...
        [후보 3] ...

    반환: [{"title":..., "core_keyword":..., "reason":...,
            "intro_structure":..., "intro_first_sentence":...}, ...]
    최대 3개. 필드가 비어 있으면 빈 문자열로 채운다. 파싱 실패 시
    빈 리스트를 반환한다(호출부에서 방어적으로 처리)."""
    t = (text or "").strip()
    fence_m = re.search(r"```[a-zA-Z]*\r?\n(.*?)```", t, re.S)
    if fence_m and "##" in fence_m.group(1):
        t = fence_m.group(1).strip()

    sec_m = re.search(r"##\s*제목\s*후보\s*\r?\n(.*?)(?=\r?\n##\s|\Z)", t, re.S)
    if not sec_m:
        return []
    sec = sec_m.group(1)

    blocks = re.split(r"\[\s*후보\s*(\d)\s*\]", sec)
    # re.split with a capturing group returns
    # [머리말, '1', 블록1, '2', 블록2, '3', 블록3] 형태
    candidates = []
    for i in range(1, len(blocks), 2):
        idx_str = blocks[i]
        body = blocks[i + 1] if i + 1 < len(blocks) else ""
        try:
            idx = int(idx_str)
        except ValueError:
            continue
        if not (1 <= idx <= 3):
            continue

        def _field(name, body=body):
            m = re.search(rf"{re.escape(name)}\s*:\s*([^\r\n]+)", body)
            return m.group(1).strip() if m else ""

        cand = {
            "title":               _field("제목"),
            "core_keyword":        _field("핵심키워드"),
            "reason":              _field("선택 근거"),
            "intro_structure":     _field("도입부 구조"),
            "intro_first_sentence": _field("도입부 첫 문장 지시"),
        }
        candidates.append((idx, cand))

    candidates.sort(key=lambda x: x[0])
    return [c for _, c in candidates][:3]


def get_done_links() -> set:
    """TAB1(수집)에서 더 이상 볼 필요 없는(패스/발행준비완료/포스팅완료)
    링크 집합. "완료" 한 글자로 두 완료 단계(발행준비완료·포스팅완료)를
    한꺼번에 잡는다 — 다른 상태(신규/검토중/작성중/보류)에는 "완료"가
    들어가지 않으므로 오탐 없이 걸러진다."""
    records = load_history()
    done = set()
    for r in records:
        st = r.get("status", "")
        if any(x in st for x in ["완료", "패스"]):
            done.add(r.get("link", ""))
    return done


def add_history_record(record: dict):
    """이력에 신규 항목 추가 (중복 링크 방지)"""
    records = load_history()
    links = {r.get("link", "") for r in records}
    if record.get("link", "") not in links:
        record.setdefault("status", "🆕 신규")
        record.setdefault("created_at", datetime.now().strftime("%Y-%m-%d %H:%M"))
        records.insert(0, record)
        save_history(records)
    return records


def is_published(link: str) -> bool:
    """이 링크가 '포스팅완료'(TAB7 엑셀 추가로 확정된) 상태인지 확인한다.
    확정된 글은 패스·삭제·보류·신규 등으로 되돌릴 수 없게 막아야 하므로,
    그 판단을 위해 여러 곳에서 공통으로 쓰는 헬퍼다.
    [Ver7.13] '🟡 발행준비완료'는 이 확정 판단에서 제외한다 — MD·인포그래픽
    까지 만들었어도 실제로 포스팅 안 하고 지울 수 있어서, 그 단계까지는
    얼마든지 되돌릴 수 있어야 한다. 실제 확정은 TAB7에서 '엑셀에 추가'가
    실행돼 '📤 포스팅완료'가 됐을 때만이다."""
    for r in load_history():
        if r.get("link") == link:
            return "포스팅완료" in r.get("status", "")
    return False


def update_history_status(link: str, status: str):
    records = load_history()
    for r in records:
        if r.get("link") == link:
            r["status"] = status
            r["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
    save_history(records)
    return records


def update_history_fields(link: str, fields: dict):
    """[2026-09-29 2차] 이력 레코드에 임의 필드(게시판 값 등)를 덧붙인다."""
    records = load_history()
    for r in records:
        if r.get("link") == link:
            r.update(fields)
            r["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
    save_history(records)
    return records


def save_candidate_xlsx(candidates: list) -> str:
    """후보군을 엑셀로 저장.
    컬럼: 선택 | 상태 | 제목 | 부처 | 발행일 | 본문유형 | 비고 | 링크
    - 신규 항목은 발행일 내림차순 위치에 삽입
    - 기존 항목의 상태는 이력에서 자동 반영
    """
    if not OPENPYXL_OK:
        return ""

    HEADERS   = ["선택", "상태", "제목", "부처", "발행일", "본문유형", "비고", "링크"]
    COL_WIDTHS= [8, 14, 56, 14, 18, 14, 18, 60]
    # 링크는 컬럼 8번째(index 7)

    # 이력에서 링크→상태 맵 생성
    history   = load_history()
    link_status = {r.get("link",""): r.get("status","") for r in history}

    if os.path.exists(_get_xlsx_candidate_path()):
        wb = load_workbook(_get_xlsx_candidate_path())
        ws = wb.active
        # 기존 데이터 읽기 (링크 기준)
        existing = {}  # link → row_data
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or not row[7]:
                continue
            link = str(row[7]).strip()
            existing[link] = list(row)
        # 기존 항목 상태 업데이트
        for link, data in existing.items():
            st = link_status.get(link, "")
            if st:
                data[1] = st  # 상태 컬럼
        # 새 항목 추가
        for art in candidates:
            link = art.get("link","")
            if link in existing:
                continue
            pub_dt  = art.get("pub_dt")
            pub_str = pub_dt.strftime("%Y-%m-%d %H:%M") if pub_dt and pub_dt.year > 2000 else (
                      art.get("published","")[:16] if art.get("published") else "")
            st = link_status.get(link, "")
            remark = "⚠️ 변경금지" if art.get("license_warn") else ""
            existing[link] = [
                "", st, art.get("title",""), art.get("dept",""),
                pub_str, art.get("body_type",""), remark, link
            ]
        # 발행일 내림차순 정렬
        def sort_key(item):
            pub = item[4] if item[4] else ""
            try:
                return datetime.strptime(pub[:16], "%Y-%m-%d %H:%M")
            except Exception:
                return datetime.min
        rows_sorted = sorted(existing.values(), key=sort_key, reverse=True)
        # 시트 재작성
        ws.delete_rows(2, ws.max_row)
    else:
        wb = Workbook()
        ws = wb.active
        ws.title = "후보군"
        ws.append(HEADERS)
        hfill = PatternFill("solid", fgColor="1F4E78")
        hfont = Font(color="FFFFFF", bold=True)
        for c in range(1, len(HEADERS)+1):
            ws.cell(1, c).fill = hfill
            ws.cell(1, c).font = hfont
            ws.cell(1, c).alignment = Alignment(horizontal="center")
        for i, w in enumerate(COL_WIDTHS, 1):
            ws.column_dimensions[get_column_letter(i)].width = w
        ws.freeze_panes = "A2"

        # 신규 생성 시 후보 정렬
        def sort_key(art):
            pub_dt = art.get("pub_dt")
            return pub_dt if pub_dt and pub_dt.year > 2000 else datetime.min
        rows_sorted = []
        for art in sorted(candidates, key=sort_key, reverse=True):
            pub_dt  = art.get("pub_dt")
            pub_str = pub_dt.strftime("%Y-%m-%d %H:%M") if pub_dt and pub_dt.year > 2000 else (
                      art.get("published","")[:16] if art.get("published") else "")
            st = link_status.get(art.get("link",""), "")
            remark = "⚠️ 변경금지" if art.get("license_warn") else ""
            rows_sorted.append([
                "", st, art.get("title",""), art.get("dept",""),
                pub_str, art.get("body_type",""), remark, art.get("link","")
            ])

    # 행 쓰기
    for row_data in rows_sorted:
        ws.append(row_data)
        row_idx  = ws.max_row
        body_type = str(row_data[5]) if len(row_data) > 5 else ""
        status    = str(row_data[1]) if len(row_data) > 1 else ""
        remark    = str(row_data[6]) if len(row_data) > 6 else ""
        # 변경금지 경고 → 빨강 (다른 색보다 최우선으로 눈에 띄어야 함)
        if "변경금지" in remark:
            fill = PatternFill("solid", fgColor="F8CBAD")
            for c in range(1, len(HEADERS)+1):
                ws.cell(row_idx, c).fill = fill
        # 첨부파일만 → 주황
        elif body_type == "첨부파일만":
            fill = PatternFill("solid", fgColor="FCE4D6")
            for c in range(1, len(HEADERS)+1):
                ws.cell(row_idx, c).fill = fill
        # 패스·포스팅완료 → 회색 (실제로 확정된 것 + 안 할 것)
        elif any(x in status for x in ["패스", "포스팅완료"]):
            fill = PatternFill("solid", fgColor="D9D9D9")
            for c in range(1, len(HEADERS)+1):
                ws.cell(row_idx, c).fill = fill
        # 발행준비완료 → 노랑 (아직 확정 아님, 포스팅 안 하고 지울 수도 있음)
        elif "발행준비완료" in status:
            fill = PatternFill("solid", fgColor="FFF2CC")
            for c in range(1, len(HEADERS)+1):
                ws.cell(row_idx, c).fill = fill
        # 작성중 → 연파랑
        elif "작성중" in status:
            fill = PatternFill("solid", fgColor="DDEEFF")
            for c in range(1, len(HEADERS)+1):
                ws.cell(row_idx, c).fill = fill

    wb.save(_get_xlsx_candidate_path())
    return _get_xlsx_candidate_path()


def load_selected_from_xlsx() -> list:
    """후보군 엑셀에서 A열='O' 표시된 행만 반환
    컬럼: 선택(0) | 상태(1) | 제목(2) | 부처(3) | 발행일(4) | 본문유형(5) | 비고(6) | 링크(7)
    """
    if not os.path.exists(_get_xlsx_candidate_path()):
        return []
    if not OPENPYXL_OK:
        return []
    wb = load_workbook(_get_xlsx_candidate_path(), read_only=True)
    ws = wb.active
    selected = []
    for row in ws.iter_rows(min_row=2, values_only=True):
        if not row or not row[2]:
            continue
        sel = str(row[0]).strip().upper() if row[0] else ""
        if sel == "O":
            pub_raw = str(row[4]).strip() if row[4] else ""
            remark  = str(row[6]).strip() if row[6] else ""
            selected.append({
                "title":        str(row[2]).strip(),
                "dept":         str(row[3]).strip() if row[3] else "",
                "published":    pub_raw,
                "pub_dt":       parse_published(pub_raw),
                "body_type":    str(row[5]).strip() if row[5] else "",
                "link":         str(row[7]).strip() if row[7] else "",
                "is_new":       False,
                "license_warn": "변경금지" in remark,
            })
    wb.close()
    return selected


def open_xlsx(path: str):
    """엑셀 파일 열기 (OS 기본 앱)"""
    try:
        if sys.platform.startswith("win"):
            os.startfile(path)
        elif sys.platform == "darwin":
            subprocess.run(["open", path])
        else:
            subprocess.run(["xdg-open", path])
    except Exception as e:
        messagebox.showerror("오류", f"파일을 열 수 없습니다: {e}")



# ════════════════════════════════════════════════════════════
# [영역 X] 중복 체크
# ════════════════════════════════════════════════════════════

def _build_org_pattern():
    """기관명 추출 정규식을 MINISTRY_FEEDS(57개 공식 기관) 기준으로 만든다.
    부처 개편이 일어나도 MINISTRY_FEEDS만 고치면 여기도 자동으로 갱신된다.
    "환경부"가 "기후에너지환경부"보다 먼저 매칭되는 것 같은 부분 일치
    사고를 막기 위해 이름이 긴 것부터 정렬해서 패턴에 넣는다."""
    extra = ["청와대", "감사원", "국가교육위원회", "지방시대위원회"]  # RSS 목록 밖이지만 본문에 자주 등장
    names = sorted(set(MINISTRY_FEEDS.keys()) | set(extra), key=len, reverse=True)
    escaped = [re.escape(n) for n in names]
    return re.compile(r'(' + '|'.join(escaped) + r')')


_ORG_PAT = _build_org_pattern()
# [Ver7.04 수정] 그룹을 캡처(...)에서 비캡처(?:...)로 변경.
# 캡처그룹이 있으면 findall()이 매치 전체가 아니라 그룹 내용만 반환해서,
# "15회"·"24회"·"95%" 등 실제 값이 전부 '회'·'%' 같은 단위 문자 하나로
# 뭉개지는 버그가 있었다(예: 15회와 24회가 코드상 완전히 같은 값으로 취급됨).
# 이 때문에 "숫자" 매칭(20점)이 실제 수치 일치 여부를 전혀 못 보고,
# "%·년·월·회 같은 흔한 단위가 둘 다 쓰였는가"만 보는 잡음 항목이 되어
# 있었다. 비캡처그룹으로 바꾸면 findall()이 "15회", "95%" 같은 전체
# 문자열을 그대로 반환해 실제 값 비교가 가능해진다.
_NUM_PAT = re.compile(
    r'\d+[\.,]?\d*\s*(?:%|년|월|일|만원|억원|조원|개월|시간|분|세|명|건|회|배|%p)'
)


def extract_core(md_text: str, keyword: str = "", title: str = "",
                  sub_keywords: list = None, dup_action: str = "") -> dict:
    """MD 본문에서 핵심 요소 추출 → JSON DB 저장용.
    dup_action: '업데이트(추가정보) 작성'으로 의도적으로 작성한 경우
    그 의도를 같이 남겨, 이후 중복 체크 결과에서 구분할 수 있게 한다."""
    lines = md_text.split("\n")

    # 도입부: 첫 ## 소제목 이전 단락
    intro_lines = []
    for line in lines:
        if line.strip().startswith("## "):
            break
        if line.strip() and not line.strip().startswith("#"):
            intro_lines.append(line.strip())
    intro = " ".join(intro_lines[:5])

    # 마무리: 마지막 ## 섹션 이후 텍스트
    last_idx = 0
    for i, line in enumerate(lines):
        if line.strip().startswith("## "):
            last_idx = i
    summary_lines = []
    for line in lines[last_idx:]:
        if line.strip() and not line.strip().startswith("#"):
            summary_lines.append(line.strip())
    summary = " ".join(summary_lines[:5])

    # [Ver9.17 신규] 본문 중간부(첫 ## 섹션~두 번째 ## 섹션 내용) 샘플.
    # 기존에는 intro(첫 ## 이전)·summary(마지막 ## 이후)만 비교해서,
    # 실제로 겹치는 내용이 본문 중간 섹션들에 있으면(예: 제목은 서로
    # 다르게 지었지만 핵심 내용 문단이 그대로 재탕된 경우) 중복
    # 체크가 이를 전혀 못 잡는 사각지대가 있었다(복지로 서브프로그램
    # 코드 리뷰 과정에서 지적됨). 완전한 본문 전체 비교는 아니지만,
    # 실질적인 내용이 보통 앞쪽 1~2개 섹션에 담기는 경우가 많아
    # 이 구간을 별도 비교 대상으로 추가한다.
    body_mid_lines = []
    section_count = 0
    in_section = False
    for line in lines:
        if line.strip().startswith("## "):
            section_count += 1
            in_section = True
            if section_count > 2:
                break
            continue
        if in_section and line.strip() and not line.strip().startswith("#"):
            body_mid_lines.append(line.strip())
    body_mid = " ".join(body_mid_lines)[:300]

    numbers = list(set(_NUM_PAT.findall(md_text)))[:10]
    orgs    = list(set(_ORG_PAT.findall(md_text)))

    # 핵심 키워드(keyword)가 비어있으면 중복체크 가중치(30점)가 통째로
    # 죽어버린다 — TAB2 입력란에 키워드를 안 넣고 저장하는 실수가
    # 실제로 있었으므로, 빈 값일 때는 본문 제목(H1)으로 대체해서
    # 적어도 "완전히 빈 값"으로 핵심DB에 들어가지 않게 한다. 정확한
    # 키워드 추출은 아니지만, 제목 전체가 비교 대상이 되는 게 아예
    # 비교 자체가 안 되는 것보다는 훨씬 낫다.
    if not keyword.strip():
        h1 = extract_h1_title(md_text)
        keyword = h1 if h1 else title

    return {
        "title":        title,
        "keyword":      keyword,
        "sub_keywords": [s for s in (sub_keywords or []) if s],
        "numbers":      numbers,
        "orgs":         orgs,
        "intro":        intro[:200],
        "summary":      summary[:200],
        "body_mid":     body_mid,
        "dup_action":   dup_action,
    }


def _get_dup_db_path() -> str:
    """핵심DB(중복비교 DB) 경로 - 완성글 저장 폴더(output_dir) 루트, 날짜 폴더와 같은 레벨"""
    cfg = load_config()
    output_dir = cfg.get("output_dir", OUTPUT_DIR)
    return os.path.join(output_dir, "정책뉴스_핵심DB.json")


def _get_author_experience_path() -> str:
    """[Ver10.05 신규] 글쓴이 실제 경험 저장 파일 — 핵심DB와 같은 output_dir 루트. {기사 링크: 경험 글}"""
    cfg = load_config()
    return os.path.join(cfg.get("output_dir", OUTPUT_DIR), "정책뉴스_글쓴이경험.json")


def load_author_experience(link: str) -> str:
    if not link or not os.path.exists(_get_author_experience_path()):
        return ""
    try:
        with open(_get_author_experience_path(), "r", encoding="utf-8") as f:
            return (json.load(f) or {}).get(link, "")
    except Exception:
        return ""


def save_author_experience(link: str, text: str):
    """[Ver10.05 신규] 빈 글이면 그 기사의 항목을 지운다."""
    path = _get_author_experience_path()
    data = {}
    if os.path.exists(path):
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f) or {}
        except Exception:
            data = {}
    text = (text or "").strip()
    if text:
        data[link] = text
    else:
        data.pop(link, None)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def format_author_experience_block(text: str) -> str:
    """[Ver10.05 신규] 프롬프트에 붙일 "## 글쓴이 실제 경험" 블록(B V21 [입력값] 4가 읽는 이름)."""
    return (
        "## 글쓴이 실제 경험\n"
        "(사용자가 직접 적은 실제 경험입니다. 이 내용만 1인칭으로 쓰고, 적히지 않은 장면·수치·감정을 "
        "더하지 마세요. 정책 사실(대상·금액·조건)의 근거로 쓰지 말고, 원문과 다르면 원문 기준으로 쓰세요.)\n"
        f"{text.strip()}\n"
    )


def _get_title_index_path() -> str:
    """[Ver8.20 신규] 제목 충돌 감지용 색인 경로 — 완성글 저장 폴더
    (output_dir) 루트. 복지로 서브프로그램의 final_posts_index.json과
    동일한 목적으로 이식했다. save_md_file()의 저장 경로는
    output_dir/날짜/제목/제목.md 형태로 날짜별 폴더가 끼어 있어서,
    바로 아래 "동일 파일명 존재 시 팝업"(os.path.exists(fpath) 검사)은
    같은 날 저장한 경우만 잡아낸다 — 서로 다른 날 작성된 두 기사가
    우연히 같은 제목을 쓰면 폴더 자체가 달라 그 검사로는 걸러지지
    않는다. 날짜와 무관하게 "이 제목을 이미 어느 기사(link)가 썼는지"를
    별도로 기록해두고, 저장 시점마다 대조한다."""
    cfg = load_config()
    output_dir = cfg.get("output_dir", OUTPUT_DIR)
    return os.path.join(output_dir, "정책뉴스_제목색인.json")


def load_title_index() -> dict:
    """정규화된 제목 -> {"link": 기사링크, "title": 원문 제목,
    "date": 저장일} 매핑. 파일이 없으면 빈 dict."""
    path = _get_title_index_path()
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def save_title_index(index: dict):
    path = _get_title_index_path()
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(index, f, ensure_ascii=False, indent=2)


def check_title_conflict(title: str, link: str) -> tuple:
    """이 제목을 다른 기사(link가 다른 기사)가 이미 쓴 적이 있는지
    확인한다. 같은 기사(link가 같음)가 같은 제목으로 재저장하는 것은
    항상 허용한다(복지로 check_final_post_title_conflict()와 동일한
    원칙 — 재작성·재저장은 충돌이 아니다). link가 비어 있으면(art
    정보가 없는 경우 등) 비교 근거가 없으므로 충돌 없음으로 처리한다.
    반환값: (충돌여부, 기존 기록 dict 또는 None)."""
    if not link:
        return False, None
    norm = _normalize_title_for_match(title)
    existing = load_title_index().get(norm)
    if existing and existing.get("link", "") != link:
        return True, existing
    return False, None


def update_title_index(title: str, link: str):
    """저장 성공 후 색인을 갱신한다. link가 없으면(원본 기사 정보가
    없는 경우) 이후 대조가 무의미하므로 색인에 남기지 않는다."""
    if not link:
        return
    norm = _normalize_title_for_match(title)
    index = load_title_index()
    index[norm] = {
        "link": link,
        "title": title,
        "date": datetime.now().strftime("%Y-%m-%d"),
    }
    save_title_index(index)


def _get_xlsx_candidate_path() -> str:
    """후보군 엑셀 경로 - 완성글 저장 폴더(output_dir) 루트"""
