def load_dup_db() -> list:
    path = _get_dup_db_path()
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as f:
        try:
            return json.load(f)
        except Exception:
            return []


def save_dup_db(records: list):
    path = _get_dup_db_path()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(records, f, ensure_ascii=False, indent=2)


def remove_from_dup_db(link: str):
    """핵심DB(중복비교 DB)에서 특정 링크의 기록을 제거한다.
    저장(작성중)까지 갔다가 발행은 안 하고 패스로 되돌리는 경우,
    혹시 핵심DB에 남아있는 기록이 있다면 같이 지워야 한다.
    (정상 흐름에서는 TAB7 '엑셀에 추가' 시점(포스팅완료 확정)에만
    등록되므로 보통은 없겠지만, 과거 버전에서 저장 시점에 등록된
    기록이 남아있을 수도 있어 패스 처리 시 항상 한 번 더 정리한다.)"""
    records = load_dup_db()
    filtered = [r for r in records if r.get("link", "") != link]
    if len(filtered) != len(records):
        save_dup_db(filtered)


def add_to_dup_db(link: str, core: dict):
    """TAB7 '엑셀에 추가'(포스팅 확정) 시 핵심DB에 추가"""
    records   = load_dup_db()
    existing  = {r.get("link","") for r in records}
    if link not in existing:
        core["link"] = link
        core["date"] = datetime.now().strftime("%Y-%m-%d")
        records.append(core)
        save_dup_db(records)


TITLE_SIMILARITY_THRESHOLD = 0.4  # [Ver9.17 신규] 제목 전체 유사도가 이 이상이면
# matched 목록에 표시한다. 복지로 서브프로그램의 정책명 퍼지 매칭
# (difflib.SequenceMatcher, SIMILAR_SERV_NAME_THRESHOLD) 방식을 참고해,
# 기존처럼 "제목 첫 단어가 정확히 같은지"만 보던 것과 별도로 제목 문장
# 전체의 유사도도 점수화한다 — 첫 단어는 다르지만 전체적으로 표현만
# 바꾼 제목(예: "OO 지원 확대" vs "OO 지원, 이렇게 확대된다")을 잡기 위함.


# [Ver10.04] 중복 체크 가중치 합계(30+10+20+10+10+15+20+10+20). 예전에는 이 합(145점)을 그대로
# "%"로 표시해 중복률이 100%를 넘을 수 있었다. 이제 점수를 이 값으로 나눠 0~100%로 표시하고,
# 판정 기준도 같은 비율로 바꿔 예전 기준(합산 50점 주의 / 70점 위험)과 거의 같게 유지한다.
DUP_SCORE_MAX = 145
DUP_WARN_PCT = 34     # 예전 합산 50점 ≈ 34.5%
DUP_DANGER_PCT = 48   # 예전 합산 70점 ≈ 48.3%


def check_duplicate(new_core: dict,
                    warn: float = DUP_WARN_PCT, danger: float = DUP_DANGER_PCT) -> list:
    """
    중복 검사.
    가중치: 핵심키워드 30 / 분산키워드 10 / 숫자 20 / 기관명 10 /
            제목 주제어(첫 단어) 일치 10 / 제목 전체 유사도 15 [Ver9.17] /
            도입부 20 / 마무리 10 / 본문 중간부 20 [Ver9.17]
    [Ver10.04] rate는 합산 점수를 DUP_SCORE_MAX(145)로 나눈 0~100% 값이고, warn/danger도 같은 % 기준이다.
    반환: [{rate, title, link, date, matched, danger}, ...]
    """
    records = load_dup_db()
    results = []

    nk  = new_core.get("keyword","").strip()
    nsk = [s.strip() for s in new_core.get("sub_keywords",[]) if s.strip()]
    nn  = set(str(x) for x in new_core.get("numbers",[]))
    no  = set(new_core.get("orgs",[]))
    ni  = new_core.get("intro","")
    ns  = new_core.get("summary","")

    for r in records:
        score   = 0
        matched = []

        # 핵심 키워드 (30)
        rk = r.get("keyword","").strip()
        if nk and rk:
            kr = difflib.SequenceMatcher(None, nk, rk).ratio()
            score += kr * 30
            if kr > 0.5:
                matched.append(f"핵심키워드({round(kr*100)}%)")

        # 분산 키워드 (10) — 가장 유사한 한 쌍의 비율을 사용
        rsk = [s.strip() for s in r.get("sub_keywords",[]) if s.strip()]
        if nsk and rsk:
            best = 0.0
            best_pair = ("", "")
            for a in nsk:
                for b in rsk:
                    ratio = difflib.SequenceMatcher(None, a, b).ratio()
                    if ratio > best:
                        best = ratio
                        best_pair = (a, b)
            score += best * 10
            if best > 0.5:
                matched.append(f"분산키워드({round(best*100)}%:{best_pair[1]})")

        # 숫자 (20)
        rn = set(str(x) for x in r.get("numbers",[]))
        if nn and rn:
            overlap = len(nn & rn) / max(len(nn), len(rn))
            score  += overlap * 20
            if nn & rn:
                matched.append(f"숫자({'·'.join(list(nn&rn)[:2])})")

        # 기관명 (10)
        ro = set(r.get("orgs",[]))
        if no and ro:
            overlap = len(no & ro) / max(len(no), len(ro))
            score  += overlap * 10
            if no & ro:
                matched.append(f"기관({'·'.join(list(no&ro)[:2])})")

        # [Ver9.04 수정] 기존 강한 판정 규칙(제목 첫 어절+발표부처 일치 시
        # 점수와 무관하게 무조건 강제 판정)을 완화한다. 실사용 중 "2026년",
        # "정부"처럼 흔한 시작 단어가 전혀 무관한 정책 기사에서도 반복되고,
        # 발표 부처도 겹치는 경우가 많아(정책뉴스 특성상 같은 부처가 다른
        # 정책을 계속 발표) 조건 자체의 변별력이 낮았다(실측 사례: 22.6%
        # 점수의 무관한 두 기사가 강제로 "중복의심" 처리되어 격리됨).
        # 발표 부처 일치 조건은 제거하고(정부 부처 자체는 큰 의미가 없음),
        # 순수하게 제목 첫 어절(=대개 핵심 주제어) 일치 여부만 보되,
        # 더는 무조건 강제 포함시키지 않고 가중치에 소폭(10점)만 가점한다
        # — 최종 판정은 다른 항목들과 합산된 점수(warn/danger 기준)로만
        # 결정되며, 흔한 시점 표현(연도·"정부"·"올해"등)으로 시작하는
        # 경우는 애초에 가점 대상에서 제외한다.
        _GENERIC_FIRST_WORDS = {"정부", "올해", "내년", "이달부터", "오늘부터", "다음달부터"}
        nt_first = new_core.get("title", "").split()
        rt_first = r.get("title", "").split()
        title_first_match = bool(
            nt_first and rt_first
            and len(nt_first[0]) >= 2
            and nt_first[0] == rt_first[0]
            and nt_first[0] not in _GENERIC_FIRST_WORDS
            and not _NUM_PAT.match(nt_first[0])  # "2026년" 같은 연도/숫자 시작 제외
        )
        if title_first_match:
            score += 10
            matched.append(f"제목 주제어 일치({nt_first[0]})")

        # [Ver9.17 신규] 제목 전체 유사도 (15) — 위 "첫 단어 일치"와 별개로
        # 문장 전체의 표현 유사도를 본다. 실사용 중 "제목은 50% 비슷한데
        # 본문은 거의 같은" 케이스가 어느 항목에도 안 걸려 팝업이 안 뜨는
        # 문제가 발견되어 추가함(정책뉴스 특성상 제목 첫 단어만으로는
        # 변별력이 낮은 경우가 많아 10점 항목 하나로는 부족했음).
        nt_full = new_core.get("title", "").strip()
        rt_full = r.get("title", "").strip()
        if nt_full and rt_full:
            tr = difflib.SequenceMatcher(None, nt_full, rt_full).ratio()
            score += tr * 15
            if tr >= TITLE_SIMILARITY_THRESHOLD:
                matched.append(f"제목 전체 유사({round(tr*100)}%)")

        # 도입부 (20)
        ri = r.get("intro","")
        if ni and ri:
            ir = difflib.SequenceMatcher(None, ni, ri).ratio()
            score += ir * 20
            if ir > 0.4:
                matched.append(f"도입부({round(ir*100)}%)")

        # 마무리 (10)
        rs = r.get("summary","")
        if ns and rs:
            sr = difflib.SequenceMatcher(None, ns, rs).ratio()
            score += sr * 10
            if sr > 0.4:
                matched.append(f"마무리({round(sr*100)}%)")

        # [Ver9.17 신규] 본문 중간부 (20) — intro/summary는 글 맨 앞·맨 뒤
        # 5줄만 보므로, 실질적으로 같은 내용이 본문 중간 섹션들에 있으면
        # 기존 로직으로는 전혀 잡히지 않았다. extract_core()가 새로 뽑아둔
        # body_mid(첫~두 번째 ## 섹션 내용 일부)를 별도 항목으로 비교한다.
        nb_mid = new_core.get("body_mid","")
        rb_mid = r.get("body_mid","")
        if nb_mid and rb_mid:
            br = difflib.SequenceMatcher(None, nb_mid, rb_mid).ratio()
            score += br * 20
            if br > 0.4:
                matched.append(f"본문중간({round(br*100)}%)")

        pct = round(score / DUP_SCORE_MAX * 100, 1)
        # [Ver9.04 수정] 더 이상 무조건 강제 포함하지 않는다 — 다른
        # 항목들과 합산된 점수(warn 기준)로만 결과 포함 여부를 결정한다.
        if pct >= warn:
            results.append({
                "rate":    pct,
                "title":   r.get("title",""),
                "link":    r.get("link",""),
                "date":    r.get("date",""),
                "matched": ", ".join(matched),
                "danger":  pct >= danger,
                # [Ver9.04 수정] 강제판정 폐지로 항상 False — 필드 자체는
                # 팝업 쪽 코드(_show_dup_result 등) 호환을 위해 유지한다.
                "hard_match": False,
                # 기존 글이 '업데이트(추가정보) 작성'으로 의도적으로 발행됐던
                # 글이라면 표시해, 단순 재탕이 아니라 후속 발행 계보임을 알 수 있게 한다.
                "was_update": r.get("dup_action","") == "업데이트(추가정보) 작성",
                # [Ver7.04 추가] '업데이트(추가정보) 작성으로 진행' 선택 시
                # TAB3 하단 참고 박스에 그대로 정리해서 보여주기 위한 원본
                # 핵심DB 필드. 여기서 안 담아두면 팝업을 닫은 뒤 이 기존
                # 글의 keyword/intro/summary 등을 다시 조회할 방법이 없다.
                "keyword":      r.get("keyword",""),
                "sub_keywords": r.get("sub_keywords",[]),
                "numbers":      r.get("numbers",[]),
                "orgs":         r.get("orgs",[]),
                "intro":        r.get("intro",""),
                "summary":      r.get("summary",""),
                "body_mid":     r.get("body_mid",""),
            })

    # [Ver10.04] 중복률 높은 순으로 정렬한다. Ver7.24에서 (hard_match, rate)로 정렬했지만
    # Ver9.04에서 강제판정이 폐지돼 hard_match가 항상 False라 정렬에 의미가 없어 뺐다.
    results.sort(key=lambda x: x["rate"], reverse=True)
    return results

def export_history_xlsx():
    """이력을 엑셀로 내보내기"""
    if not OPENPYXL_OK:
        return False, "openpyxl 미설치"
    records = load_history()
    wb = Workbook()
    ws = wb.active
    ws.title = "포스팅이력"
    headers = ["상태", "제목", "핵심키워드", "참고키워드1", "참고키워드2", "참고키워드3",
               "확정제목", "발표유형", "경쟁강도", "처리방향", "발행일", "수집일", "수정일",
               "링크", "MD파일"]
    ws.append(headers)
    hfill = PatternFill("solid", fgColor="1F4E78")
    hfont = Font(color="FFFFFF", bold=True)
    for c in range(1, len(headers)+1):
        ws.cell(1, c).fill = hfill
        ws.cell(1, c).font = hfont
        ws.cell(1, c).alignment = Alignment(horizontal="center")
    widths = [12, 55, 22, 22, 22, 22, 50, 12, 12, 18, 20, 16, 16, 50, 35]
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    for r in records:
        sub_kws = r.get("sub_keywords", ["", "", ""])
        sub_kws = sub_kws + [""] * (3 - len(sub_kws))  # 길이 보정
        ws.append([
            r.get("status",""), r.get("title",""),
            r.get("core_keyword", r.get("keyword","")),
            sub_kws[0], sub_kws[1], sub_kws[2],
            r.get("final_title",""),
            r.get("announce_type",""), r.get("competition",""), r.get("dup_action",""),
            r.get("published",""), r.get("created_at",""), r.get("updated_at",""),
            r.get("link",""), r.get("md_file",""),
        ])
    try:
        wb.save(_get_xlsx_history_path())
    except Exception as e:
        return False, f"저장 실패(엑셀 파일이 열려있을 수 있습니다): {e}"
    return True, _get_xlsx_history_path()


# ════════════════════════════════════════════════════════════
# [영역 4] 파일 유틸
# ════════════════════════════════════════════════════════════

PROMPT_MEMO_MARKER = "[참고 메모"   # [Ver10.02] 프롬프트 파일 맨 앞 검토용 메모 블록의 표시


def strip_prompt_memo(text: str) -> str:
    """[Ver10.02 신규] 프롬프트 파일 맨 앞의 검토용 참고 메모를 뺀다.
    프롬프트 A·B는 "# 제목" 줄 → "> [참고 메모 — 실행 규칙 아님] …" 인용 블록 → "---" 줄 → 본문
    순서로 되어 있다. 메모는 사람이 프롬프트를 검토·변경할 때만 보는 것이라 Claude에 보낼 필요가
    없으므로, 첫 "---" 줄 앞에 메모 표시가 있을 때만 그 앞부분을 "# 제목" 줄만 남기고 덜어낸다.
    메모가 없는 파일(프롬프트 0·C·D 등)은 그대로 돌려준다."""
    m = re.search(r"^---[ \t]*$", text, re.M)
    if not m:
        return text
    head = text[:m.start()]
    if PROMPT_MEMO_MARKER not in head:
        return text
    title = next((ln for ln in head.splitlines() if ln.startswith("# ")), "")
    body = text[m.end():].lstrip("\n")
    return (title + "\n\n" + body) if title else body


def load_prompt_file(filename: str, prompt_dir: str) -> str:
    path = os.path.join(prompt_dir, filename)
    if not os.path.exists(path):
        return ""
    with open(path, "r", encoding="utf-8") as f:
        return strip_prompt_memo(f.read().strip())   # [Ver10.02] 검토용 메모는 빼고 보낸다


def safe_filename(title: str) -> str:
    """제목 → 안전한 파일명 (공백 유지, 파일명 금지문자만 제거)"""
    s = re.sub(r'[\\/:*?"<>|]', "", title)
    s = s.strip()
    return s[:80]


def extract_h1_title(md_text: str) -> str:
    """마크다운에서 # 제목 추출"""
    for line in md_text.split("\n"):
        line = line.strip()
        if line.startswith("# ") and not line.startswith("## "):
            return line[2:].strip()
    return ""


# [Ver7.09 추가] 인포그래픽 제목 복사 시 끝의 특수문자 제거
def _strip_trailing_punct_for_filename(text: str) -> str:
    """이미지 파일명으로 바로 쓰기 위해 복사하는 제목에서, 끝에 붙은
    물음표·느낌표·말줄임표 등 특수문자를 제거한다. "~할까요?"처럼 문장이
    물음표로 끝나는 소제목이 많은데, 그대로 복사하면 이미지 파일 저장 시
    매번 지워야 해서 불편하다는 요청으로 추가."""
    return re.sub(r'[?!.…~"\'“”‘’]+\s*$', '', text).strip()


def count_korean_chars(text: str) -> tuple:
    """한글 글자수 (공백제외, 공백포함)"""
    kor   = len(re.findall(r'[\uAC00-\uD7A3]', text))
    eng   = len(re.findall(r'[a-zA-Z0-9]', text))
    punct = len(re.findall(r'[^\uAC00-\uD7A3a-zA-Z0-9\s]', text))
    sp    = len(re.findall(r'[ \t]', text))
    excl  = int(kor + eng * 0.5 + punct)
    incl  = int(kor + eng * 0.5 + punct + sp)
    return excl, incl


# [Ver10.05/Ver9.33] 제목 숫자 개수 — "2026년 11월 3일"처럼 연·월·일이 붙은 날짜 하나는 숫자 1개로 센다.
_TITLE_DATE_RE = re.compile(r"\d{4}\s*년\s*\d{1,2}\s*월(?:\s*\d{1,2}\s*일)?|\d{1,2}\s*월\s*\d{1,2}\s*일")


def title_number_groups(title: str) -> list:
    dates = _TITLE_DATE_RE.findall(title or "")
    rest = _TITLE_DATE_RE.sub(" ", title or "")
    return [d.replace(" ", "") for d in dates] + re.findall(r'\d+(?:[.,]\d+)?', rest)


def validate_title(title: str) -> dict:
    """프롬프트A v2 기준 제목 검증.
    반환: {length, ok_length, hook_words(발견된 호객형 수식어 목록),
           ends_verb(동사형 종결 여부 추정), warnings(경고 메시지 목록)}
    완벽한 문법 분석은 아니고, 명백한 실수만 잡아내는 가벼운 점검이다.
    """
    title = (title or "").strip()
    length = len(title)
    warnings = []

    # [Ver9.15 재도입] 프롬프트A V10 [제목 형식 규칙]이 60자(복합 소재형은
    # 75자)를 절대 상한으로 명문화한 데 맞춰 경고를 다시 넣는다. Ver9.04에서
    # 옛 기준(30~50자)으로 오작동하던 문제로 뺐던 것을, 이번엔 새 기준
    # (50~60자, 75자 예외)에 맞춰 다시 켠다. "소재 개수"는 코드가 알 수
    # 없으므로 60~75자는 예외 대상인지 직접 확인하라는 경고로, 75자
    # 초과는 예외 없이 줄이라는 경고로 나눈다.
    # [Ver10.06] 프롬프트A V20: 40~60자(세트 구분 삭제).
    min_len, max_len = title_len_limits()
    ok_length = min_len <= length <= max_len
    # [Ver9.26] 75자 예외는 프롬프트A V15에서 폐지됐다 — 60자가 절대 상한이다.
    if length > max_len:
        warnings.append(
            f"제목이 {length}자로 {max_len}자 절대 상한을 넘었습니다 — 줄여야 합니다.")
    elif length and length < min_len:
        warnings.append(
            f"제목이 {length}자로 {min_len}자 미만입니다 — 핵심 키워드나 롱테일 "
            f"표현을 더 녹일 수 있는지 확인하세요.")

    # [Ver9.26 신규] 프롬프트A V16 구조 점검: "앞부분, 뒷부분" 쉼표 1개, 앞부분 30자 이내.
    commas = len(_TITLE_COMMA_RE.findall(title))   # [Ver10.02] 숫자 속 천 단위 쉼표 제외
    if title and commas == 0:
        warnings.append("쉼표가 없습니다 — 프롬프트A V16 제목은 '앞부분, 뒷부분' 쉼표 1개 구조입니다 "
                        "(제목정밀검색의 앞구는 앞 30자로 대체됩니다).")
    elif commas >= 2:
        warnings.append(f"쉼표가 {commas}개입니다 — 첫 쉼표 앞만 앞구로, 첫 쉼표 뒤 전체가 뒷구로 "
                        f"검색됩니다(쉼표 1개 권장).")
    if commas >= 1:
        # [Ver10.06] 앞부분 길이는 속마음 후킹을 포함한 그대로 센다(검색용 앞 핵심구와 다름).
        _front_len = _TITLE_COMMA_RE.search(title).start()
        if _front_len > 30:
            warnings.append(f"앞부분(첫 쉼표 앞)이 {_front_len}자입니다 — 30자 이내를 권장합니다.")

    # [Ver10.06] 프롬프트A V20 속마음 후킹: 앞부분 메인 바로 뒤 작은따옴표 한 쌍, 앞 25자 안에서 끝남.
    hook, hook_end = policy_title_hook(title)
    if title and not hook:
        warnings.append("앞부분(첫 쉼표 앞)에 작은따옴표 속마음 후킹이 없습니다 — 프롬프트A V20 제목은 "
                        "[메인 + '속마음 후킹'], [롱테일] 구조입니다(피드에서 멈추게 하는 자리).")
    elif hook and hook_end > TITLE_HOOK_VISIBLE_LEN:
        warnings.append(f"속마음 후킹이 {hook_end}자에서 끝납니다 — 피드 카드에는 앞 약 "
                        f"{TITLE_HOOK_VISIBLE_LEN}자만 보이므로 메인과 후킹을 앞으로 당기세요.")

    # [Ver9.15 신규] 핵심 숫자 개수 점검. 프롬프트A V10 [제목 형식 규칙]이
    # "핵심 숫자는 원칙적으로 1개만"을 명문화한 데 맞춘 가벼운 점검이다.
    number_groups = title_number_groups(title)
    if len(number_groups) >= 2:
        warnings.append(
            f"숫자가 {len(number_groups)}개({', '.join(number_groups)}) 들어있습니다 — "
            f"핵심 숫자는 원칙적으로 1개만 남기세요(나이·기간 범위처럼 "
            f"하나의 조건을 이루는 숫자 2개라면 예외로 볼 수 있으니 직접 확인하세요).")

    found_hooks = [w for w in HOOK_WORDS if w in title]
    if found_hooks:
        warnings.append(f"호객형 수식어 발견: {', '.join(found_hooks)} — "
                        "낚시성 제목으로 보일 수 있습니다.")

    # [Ver9.26] "동사형 종결/명사형 종결 의심" 점검 삭제 — 프롬프트A V16은 물음표 종결이 선택이고
    # 명사형·서술형 마무리도 허용하는데, 옛 점검은 "됩니다/합니다"류가 아니면 모두 명사형 의심으로
    # 걸어 "언제까지?" 같은 정상 제목에도 경고가 떴다. 호환을 위해 키만 남긴다.
    ends_verb = True

    return {
        "length":      length,
        "ok_length":   ok_length,
        "hook_words":  found_hooks,
        "ends_verb":   ends_verb,
        "warnings":    warnings,
    }


# [Ver10.06 신규] 저장 전 모바일 문단 정리 — 지식인 관리 프로그램 Ver10.05(kin_manager.py)와 같은 코드.
# ══════════════════════════════════════════════════════════
# 저장 전 모바일 문단 정리 (정책뉴스: 4)최종각색 탭 "💾 MD 파일 저장", 기본 꺼짐)
# ──────────────────────────────────────────────────────────
# 각색 결과는 이미 빈 줄로 문단이 나뉘어 있으므로(대부분 1~3문장, 중간값 약
# 100자) 기존 문단 구분은 그대로 두고, 기준 글자 수(기본 150자, 4)탭에서 조정)를
# 넘는 문단만 나눈다. 문단을 합치지는 않는다. 넘는 문단이 없으면 GPT를 부르지
# 않는다. 나누는 자리는 한 문단에 한 곳, "첫 문장 뒤(앞)" 또는 "마지막 문장 앞(뒤)"
# 둘 중 하나이고, GPT가 문단을 읽고 앞/뒤/없음(문맥이 어색하면 그대로) 중 하나만
# JSON으로 답한다. 코드가 원래 문장 그대로 다시 이어 붙이며 나눈 자리에만 빈 줄
# (포스팅 프로그램의 문단 구분)을 넣는다. 마지막에 공백·줄바꿈을 모두 뺀 전후
# 본문을 대조해 한 글자라도 다르면 원본을 그대로 쓴다.
# 제목·소제목·해시태그(#), 표(|), 리스트(- * + 1.), 인용(>), 이미지,
# 코드펜스, 구분선, 굵은 글씨만 있는 줄, [[강조]] 줄은 건드리지 않는다.
# ══════════════════════════════════════════════════════════
PARA_REFLOW_MODEL = "gpt-4.1-mini-2025-04-14"
PARA_REFLOW_DEFAULT_LIMIT = 150

_PARA_LOCK_PAT = re.compile(
    r'^\s*(?:#|\||>|!\[|[-*+]\s|\d+[.)]\s|`{3,}|-{3,}\s*$|\*\*[^*].*\*\*\s*$|\[\[)')
# 문장 끝: . ! ? … 뒤에 닫는 따옴표·괄호가 붙을 수 있고, 그 뒤가 공백이어야 한다
# ("1.5", "2026.10.5" 같은 숫자 안의 점은 뒤에 공백이 없어 나뉘지 않는다).
_PARA_SENT_END_PAT = re.compile(r'[.!?…][)"\'”’」』\]]*(?=\s)')

PARA_REFLOW_RULES = (
    "당신은 네이버 블로그 글의 긴 문단을 모바일에서 읽기 좋게 나누는 편집자입니다.\n"
    "아래 [문단]은 기준 길이({limit}자)를 넘어 둘로 나누려는 문단이며, 문장에 번호가 붙어 있습니다.\n"
    "문단 전체를 읽고 문단마다 아래 셋 중 하나를 고르세요.\n"
    "- 앞: 첫 문장 뒤에서 나눔 (1번 | 2번~끝)\n"
    "- 뒤: 마지막 문장 앞에서 나눔 (1번~끝 앞 | 마지막 문장)\n"
    "- 없음: 나누지 않음\n\n"
    "떼어 낸 문장과 남은 문장이 각각 앞뒤 없이도 뜻이 자연스럽게 통하고 흐름이 끊기지 않는 쪽을\n"
    "고릅니다. 앞뒤 문장과 이어져야 뜻이 통해서 어느 쪽으로 나눠도 어색하면 \"없음\"을 고릅니다.\n"
    "문장은 고치지 않습니다. 문장이 2개인 문단은 앞과 뒤가 같습니다.\n\n"
    "[출력]\n"
    '아래 JSON만 출력합니다: {{"paragraphs": {{"3": "앞", "7": "뒤", "9": "없음"}}}} (키는 [문단] 번호)'
)


def para_split_sentences(line):
    """한 줄을 문장 단위로 나눈다(앞뒤 공백만 떼므로 이어 붙이면 원문과 글자가 같다)."""
    out, start = [], 0
    for m in _PARA_SENT_END_PAT.finditer(line):
        out.append(line[start:m.end()].strip())
        start = m.end()
    rest = line[start:].strip()
    if rest:
        out.append(rest)
    return [s for s in out if s]


def para_find_paragraphs(md_text):
    """빈 줄·잠금 줄로 구분되는 일반 문단을 찾는다.
    반환 (lines, paras) - paras는 [(시작줄, 끝줄, [문장, ...], 글자수), ...](끝줄 포함).
    글자수는 문장을 공백 하나로 이어 붙인 길이(공백 포함)."""
    lines = md_text.split('\n')
    paras, i, n = [], 0, len(lines)
    while i < n:
        ln = lines[i]
        if not ln.strip() or _PARA_LOCK_PAT.match(ln):
            i += 1
            continue
        j = i
        while j + 1 < n and lines[j + 1].strip() and not _PARA_LOCK_PAT.match(lines[j + 1]):
            j += 1
        sents = []
        for x in lines[i:j + 1]:
            sents.extend(para_split_sentences(x))
        paras.append((i, j, sents, len(" ".join(sents))))
        i = j + 1
    return lines, paras


def para_long_targets(md_text, limit):
    """나눌 문단만 [(문단순번, 문장들, 글자수)]로 돌려준다. 대상: 기준 글자 수를 넘고
    문장이 2개 이상인 문단. 아래는 대상에서 뺀다(그대로 둔다).
    - 여러 줄로 된 문단(한 줄 바꿈으로 이어진 블록 - B·Claude 도입부의 시적 줄바꿈 등):
      줄바꿈 자체가 형식이라 건드리지 않는다.
    - [[강조]]·[[주의]]가 문단 안에 섞인 문단: 프롬프트상 태그는 독립 문단이라 정상
      글에는 없고, 섞여 있으면 어디서 나눠도 태그나 문장이 잘릴 수 있다.
    - 해시태그 줄 바로 앞 문단: 면책 문장("해시태그 앞 별도 한 줄").
    - 도입부(첫 ## 소제목 앞 문단)."""
    lines, paras = para_find_paragraphs(md_text)
    # 도입부(첫 "## " 소제목 앞)는 나누지 않는다.
    first_h2 = next((i for i, x in enumerate(lines) if re.match(r'\s*##\s', x)), len(lines))
    last_prose = None
    for k, (s, e, _, _) in enumerate(paras):
        nxt = next((x for x in lines[e + 1:] if x.strip()), "")
        if nxt.lstrip().startswith('#') and not re.match(r'\s*#{1,6}\s', nxt):
            last_prose = k
    out = []
    for k, (s, e, sents, total) in enumerate(paras):
        if s < first_h2 or total <= limit or len(sents) < 2 or e > s or k == last_prose:
            continue
        if '[[' in lines[s]:
            continue
        out.append((k + 1, sents, total))
    return out


def para_valid_groups(groups, n):
    """GPT가 준 묶음이 1..n을 순서대로 한 번씩만 덮는지 확인."""
    if not isinstance(groups, list) or not groups:
        return False
    flat = []
    for g in groups:
        if not isinstance(g, list) or not g:
            return False
        flat.extend(g)
    return flat == list(range(1, n + 1))


def para_apply_splits(md_text, splits):
    """splits({문단순번: [[1,2],[3]]})대로 해당 문단만 나눈다. 나머지 문단·줄은 그대로.
    묶음이 잘못됐거나 하나로 둔 문단은 손대지 않는다. 반환 (새 본문, 나눈 문단 수, 잘못된 응답 수)."""
    lines, paras = para_find_paragraphs(md_text)
    changed = invalid = 0
    for idx in range(len(paras), 0, -1):
        if idx not in splits:
            continue
        s, e, sents, _ = paras[idx - 1]
        groups = splits[idx]
        if groups is None or not para_valid_groups(groups, len(sents)):
            invalid += 1
            continue
        if len(groups) < 2:
            continue
        new_lines = []
        for g_i, g in enumerate(groups):
            if g_i:
                new_lines.append("")
            new_lines.append(" ".join(sents[k - 1] for k in g))
        lines[s:e + 1] = new_lines
        changed += 1
    return "\n".join(lines), changed, invalid


def para_same_text(a, b):
    """공백·줄바꿈을 모두 뺀 글자가 같은지(문단 정리 안전장치)."""
    return re.sub(r'\s', '', a) == re.sub(r'\s', '', b)


def para_reflow_with_gpt(openai_client, md_text, limit=PARA_REFLOW_DEFAULT_LIMIT, model=PARA_REFLOW_MODEL):
    """기준 글자 수를 넘는 문단만 GPT에게 나눌 자리를 받아 나눈다.
    반환 (새 본문 또는 None, 안내 문구). None이면 원본을 그대로 쓴다."""
    targets = para_long_targets(md_text, limit)
    if not targets:
        return None, f"{limit}자 넘는 문단 없음 - GPT 호출 안 함(원본 유지)"
    parts = []
    for pid, sents, total in targets:
        parts.append(f"[문단 {pid}] (전체 {total}자)")
        parts.extend(f"{k}. ({len(x)}자) {x}" for k, x in enumerate(sents, 1))
        parts.append("")
    resp = openai_client.chat.completions.create(
        model=model,
        messages=[{"role": "user",
                   "content": PARA_REFLOW_RULES.format(limit=limit) + "\n\n" + "\n".join(parts)}],
        temperature=0,
        max_tokens=300,
        response_format={"type": "json_object"},
    )
    raw = (resp.choices[0].message.content or "").strip()
    try:
        data = json.loads(raw)
    except Exception:
        m = re.search(r'\{.*\}', raw, re.S)
        data = json.loads(m.group(0)) if m else {}
    # "앞" = 첫 문장 뒤, "뒤" = 마지막 문장 앞, "없음" = 그대로. 그 밖의 답은 잘못된 응답.
    counts = {pid: len(sents) for pid, sents, _ in targets}
    splits = {}
    for k, v in (data.get("paragraphs") or {}).items():
        try:
            k = int(k)
        except (TypeError, ValueError):
            continue
        if k not in counts:
            continue
        n = counts[k]
        v = str(v).strip()
        if v == "앞":
            splits[k] = [[1], list(range(2, n + 1))]
        elif v == "뒤":
            splits[k] = [list(range(1, n)), [n]]
        elif v == "없음":
            splits[k] = [list(range(1, n + 1))]
        else:
            splits[k] = None  # para_apply_splits에서 잘못된 응답으로 센다
    new_text, changed, invalid = para_apply_splits(md_text, splits)
    if not para_same_text(md_text, new_text):
        return None, "대조 실패 - 원본 유지"
    note = f"{limit}자 넘는 문단 {len(targets)}개 중 {changed}개 나눔"
    if invalid:
        note += f"(잘못된 응답 {invalid}개는 그대로)"
    if new_text == md_text:
        return None, note + " - 바뀐 것 없음(원본 유지)"
    return new_text, note


def save_md_file(title: str, content: str, domain: str, output_dir: str) -> str:
    """완성 글을 MD 파일로 저장.
    제목과 같은 이름의 하위 폴더를 만들고 그 안에 저장한다
    (예: output_dir/2026-06-26/제목/제목.md).
    이렇게 글마다 폴더를 분리해두면, 나중에 GPT에서 만든 인포그래픽
    이미지(썸네일·소제목별 이미지)를 같은 폴더에 같이 넣어서 — 어떤
    이미지가 어떤 글에 속하는지 파일 탐색기에서 바로 구분할 수 있다.
    동일 폴더 존재 시 None 반환하지 않고 그대로 경로를 반환한다
    (호출부에서 기존 .md 파일 존재 여부로 덮어쓰기를 판단한다).
    설정 탭에서 지정한 output_dir을 프롬프트 폴더처럼 그대로 사용한다
    (예전에는 output_dir 밑에 domain 고정 폴더가 한 번 더 끼어들었으나 제거함).
    """
    date_str    = datetime.now().strftime("%Y-%m-%d")
    safe_title  = safe_filename(title)
    folder      = os.path.join(output_dir, date_str, safe_title)
    os.makedirs(folder, exist_ok=True)
    fname = f"{safe_title}.md"
    fpath = os.path.join(folder, fname)
    return fpath  # 존재 여부 판단은 호출부에서


def open_folder(path: str):
    try:
        if sys.platform.startswith("win"):
            os.startfile(path)
        elif sys.platform == "darwin":
            subprocess.run(["open", path])
        else:
            subprocess.run(["xdg-open", path])
    except Exception as e:
        messagebox.showerror("오류", f"폴더를 열 수 없습니다: {e}")


# ════════════════════════════════════════════════════════════
# [영역 4.5] 이미지 워터마크 가리기 (앵커 이미지 합성)
# ════════════════════════════════════════════════════════════
# 재미나이(Gemini) 등 AI 이미지 생성 서비스가 우측 하단에 붙이는 워터마크
# 심볼은 직접 지우기 어렵다(주변 배경까지 같이 뭉개짐). 대신 그 자리를
# 별도 이미지(앵커 이미지 — 예: 인물 캐릭터)로 덮어 가리는 방식은 배경
# 손상 없이 간단하게 처리된다. PIL(Pillow)이 없으면 TAB9 자체를 안내
# 문구로 대체하고, 이 영역의 함수들은 호출되지 않는다.

SUPPORTED_IMAGE_EXTS = {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
WM_OUTPUT_SUBFOLDER = "_워터마크가림"


def _wm_find_images(folder: str, recursive: bool) -> list:
    """대상 폴더에서 처리할 이미지 파일 경로 목록을 모은다.
    recursive=False면 folder 바로 안(1단계)만, True면 모든 하위 폴더까지 포함한다.
    합성 결과가 저장되는 WM_OUTPUT_SUBFOLDER는 재귀 스캔에서 항상 제외한다 —
    재실행 시 이미 처리된 결과물을 원본으로 오인해 또 처리하는 것을 막기 위함."""
    results = []
    if not os.path.isdir(folder):
        return results
    if recursive:
        for root, dirs, files in os.walk(folder):
            # WM_OUTPUT_SUBFOLDER("_워터마크가림")와 미리보기 폴더("_워터마크가림_미리보기")를
            # 모두 재귀 스캔에서 제외한다 — 결과물/미리보기를 원본으로 오인해 또 처리하는 것을 막기 위함.
            dirs[:] = [d for d in dirs if not d.startswith(WM_OUTPUT_SUBFOLDER)]
            for fn in sorted(files):
                if os.path.splitext(fn)[1].lower() in SUPPORTED_IMAGE_EXTS:
                    results.append(os.path.join(root, fn))
    else:
        for fn in sorted(os.listdir(folder)):
            fp = os.path.join(folder, fn)
            if os.path.isfile(fp) and os.path.splitext(fn)[1].lower() in SUPPORTED_IMAGE_EXTS:
                results.append(fp)
    return results


def composite_anchor_on_image(image_path: str, anchor_img, width_ratio: float = 0.22,
                               margin_x_ratio: float = 0.02, margin_y_ratio: float = 0.0):
    """base 이미지 우측 하단에 anchor_img(미리 로드된 RGBA PIL Image)를
    비율에 맞게 리사이즈해 합성한 새 PIL Image를 반환한다(원본 객체는 안 건드림).
    - width_ratio   : 앵커 이미지 폭 = base 폭 * width_ratio (워터마크를 확실히
                       덮을 만큼 충분히 크게, 기본 22%)
    - margin_x_ratio: 오른쪽 여백 = base 폭 * margin_x_ratio
    - margin_y_ratio: 아래쪽 여백 = base 높이 * margin_y_ratio (기본 0 = 바닥에
                       딱 붙임 — 인물 캐릭터가 이미지 하단 모서리에 서 있는 듯한
                       자연스러운 배치가 되면서, 워터마크가 보통 찍히는 가장 낮은
                       위치까지 확실히 덮는다)
    JPG처럼 알파 채널이 없는 포맷은 최종적으로 RGB로 되돌려 저장 호환성을 유지한다."""
    base = Image.open(image_path)
    orig_mode = base.mode
    base = base.convert("RGBA")
    bw, bh = base.size

    aw = max(1, int(bw * width_ratio))
    ah = max(1, int(anchor_img.height * (aw / anchor_img.width)))
    anchor_resized = anchor_img.resize((aw, ah), Image.LANCZOS)

    margin_x = int(bw * margin_x_ratio)
    margin_y = int(bh * margin_y_ratio)
    x = max(0, bw - aw - margin_x)
    y = max(0, bh - ah - margin_y)

    base.paste(anchor_resized, (x, y), anchor_resized)

    if orig_mode != "RGBA":
        base = base.convert("RGB")
    return base


def _wm_output_path(src_path: str, target_folder: str, keep_original: bool) -> str:
    """'원본 유지' 옵션이면 target_folder 아래 WM_OUTPUT_SUBFOLDER 안에
    원본과 같은 상대경로 구조를 그대로 살려 저장 경로를 만든다(재귀 처리 시
    하위 폴더별로 결과물이 섞이지 않게 하기 위함). 원본 덮어쓰기 옵션이면
    같은 폴더·같은 파일명(확장자만 교체)으로 저장 경로를 만든다.

    [수정] 합성 결과는 원본 확장자와 무관하게 항상 PNG로 저장한다 — 앵커
    이미지(워터마크를 가리는 그림)가 투명 배경(RGBA)을 쓰는 경우가 많아
    무손실 포맷이 안전하고, JPG로 저장할 때 생기는 재압축 열화나 앵커
    경계 뭉개짐도 피할 수 있다. 그래서 확장자를 항상 .png로 바꾼다."""
    if keep_original:
        rel = os.path.relpath(src_path, target_folder)
        rel_png = os.path.splitext(rel)[0] + ".png"
        return os.path.join(target_folder, WM_OUTPUT_SUBFOLDER, rel_png)
    return os.path.splitext(src_path)[0] + ".png"


# ════════════════════════════════════════════════════════════
# [영역 5] GUI
# ════════════════════════════════════════════════════════════

class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self._update_window_title()

        # 창 크기·중앙 배치
        # 화면 해상도에 비례해서 키우되(화면이 작으면 같이 작아짐),
        # 너무 커지지 않도록 상한을 둔다. 리스트·로그 영역은 row weight로
        # 자동 확장되므로, 창 자체를 키우는 것만으로 보이는 줄 수가 늘어난다.
        sw = self.winfo_screenwidth()
        sh = self.winfo_screenheight()
        w = min(int(sw * 0.78), 1400)
        h = min(int(sh * 0.92), 1100)
        x = (sw - w) // 2
        y = (sh - h) // 2 -39
        self.geometry(f"{w}x{h}+{x}+{y}")
        self.minsize(1000, 700)
        self.resizable(True, True)

        # 공유 상태
        self.collected: list = []          # 수집된 기사 목록
        self.selected_article: dict = {}   # 현재 선택된 기사
        self.history: list = load_history()
        self.infographic_vars: list = []   # TAB4 이미지 매칭 체크박스 변수들
        self.last_saved_folder: str = ""   # 방금 MD 파일을 저장한 폴더 (제목별 하위폴더)
        self._shared_chrome_driver = None  # 네이버 검색용 크롬 인스턴스(비로그인 임시 프로필, 같은 실행 안에서만 재사용)
        self._precheck_driver = None       # [Ver9.12 신규] 제목 후보 자동 제목정밀검색 전용 헤드리스 크롬(화면에 안 뜸, 공유 크롬과 별개)
        self._precheck_run_id = 0          # [Ver9.21] 제목정밀검색 실행 번호(바뀌면 이전 스레드는 중단)
        self._manual_precheck_run_id = 0   # [Ver9.23] 직접 입력 제목 검색용 실행 번호(후보용과 별도)
        self._precheck_lock = threading.Lock()   # [Ver9.21] 제목정밀검색 스레드 동시 실행 방지

        # 스타일
        style = ttk.Style()
        style.configure("TNotebook.Tab", font=("맑은 고딕", 11, "bold"), padding=[10, 4])
        # 선택된 탭이 눈에 잘 띄도록 배경색+글자색을 같이 바꾼다.
        # ttk 테마에 따라 배경색 변경이 일부 플랫폼에서 잘 안 먹는
        # 경우가 있어서, 글자색(진한 파란색)과 굵기를 같이 줘서
        # 어떤 환경에서도 선택된 탭이 확실히 구분되게 한다.
        style.map("TNotebook.Tab",
                  foreground=[("selected", "#0000FF"), ("!selected", "black")])
        style.configure("Header.TLabel", font=("맑은 고딕", 11, "bold"))
        style.configure("Info.TLabel",   font=("맑은 고딕", 9),  foreground="gray")
        style.configure("Copy.TButton",  font=("맑은 고딕", 10, "bold"))

        # 탭 노트북
        self.nb = ttk.Notebook(self)
        self.nb.pack(fill="both", expand=True, padx=8, pady=8)

        self._build_tab1_collect()
        self._build_tab_bulk_review()
        self._build_tab2_analyze()
        self._build_tab3_write()
        self._build_tab4_infographic()
        self._build_tab9_watermark()   # [탭 순서 변경] 인포그래픽 ↔ 이력관리 사이로 이동
        self._build_tab5_history()
        self._build_tab_main_register()
        self._build_tab6_settings()

        # 로딩 후 IP 자동 조회 (팝업 없이 라벨만 갱신)
        self.after(1500, self._refresh_ip_label_sub)

        # 초기 폴더 생성 (경로 문제가 있어도 프로그램은 계속 뜨도록 예외 처리)
        cfg = load_config()
        try:
            os.makedirs(cfg.get("prompt_dir", PROMPT_DIR), exist_ok=True)
        except Exception as e:
            print(f"[경고] 프롬프트 폴더 생성 실패, 기본 경로로 대체: {e}")
            cfg["prompt_dir"] = PROMPT_DIR
            os.makedirs(PROMPT_DIR, exist_ok=True)
        try:
            os.makedirs(cfg.get("output_dir", OUTPUT_DIR), exist_ok=True)
        except Exception as e:
            print(f"[경고] 출력 폴더 생성 실패, 기본 경로로 대체: {e}")
            cfg["output_dir"] = OUTPUT_DIR
            os.makedirs(OUTPUT_DIR, exist_ok=True)
        try:
            kw_dir = os.path.dirname(_get_keyword_excel_path()) or "."
            os.makedirs(kw_dir, exist_ok=True)
        except Exception as e:
            print(f"[경고] 키워드 엑셀 폴더 생성 실패, 기본 경로로 대체: {e}")
            cfg["keyword_excel_path"] = ""
            os.makedirs(os.path.dirname(DEFAULT_KEYWORD_EXCEL_PATH) or ".", exist_ok=True)
        save_config(cfg)

        # 시작 시 미완료 이력 자동 로드 (300ms 후 실행)
        self.after(300, self._auto_load_pending)

        # 창을 닫을 때 자동 수집 타이머를 정리한다
        self.protocol("WM_DELETE_WINDOW", self._on_app_close)

    def _on_app_close(self):
        if getattr(self, "_auto_collect_running", False):
            self._stop_auto_collect()
        if getattr(self, "_shared_chrome_driver", None):
            try:
                self._shared_chrome_driver.quit()
            except Exception:
                pass
        if getattr(self, "_precheck_driver", None):
            try:
                self._precheck_driver.quit()
            except Exception:
                pass
        self.destroy()

    # ──────────────────────────────────────────────────────
    # 네이버 접속용 크롬 (비로그인 임시 프로필) - IP 체크 후 열기
    # ──────────────────────────────────────────────────────
    def _check_ip_before_naver_open(self):
        """네이버 접속 전 IP 체크. 차단해야 하면 True 반환 (조회 실패시에도 차단)"""
        base_ip = get_env_value('base_ip', '').strip()
        if not base_ip:
            return False  # base_ip 미설정이면 체크 안 함

        current_ip = get_current_public_ip()
        if current_ip is None:
            messagebox.showerror(
                "IP 조회 실패 - 접속 중지",
                "⛔ 공인 IP 조회에 실패했습니다.\n\n"
                "인터넷 연결 상태를 확인하거나 잠시 후 다시 시도해주세요.\n"
                "(동일 네트워크 환경 확인이 불가능하여 안전을 위해 접속을 중지합니다)"
            )
            return True

        mode = get_env_value('network_mode', 'public')
        if mode == 'public':
            if current_ip != base_ip:
                messagebox.showerror(
                    "IP 불일치 - 접속 중지",
                    f"⛔ 공인IP 모드: 등록된 네트워크가 아닙니다!\n\n"
                    f"설정 Base IP: {base_ip}\n현재 공인IP: {current_ip}"
                )
                return True
        else:
            if current_ip == base_ip:
                messagebox.showerror(
                    "IP 불일치 - 접속 중지",
                    f"⛔ 테더링 모드: 테더링이 되어 있지 않습니다!\n\n"
                    f"설정 Base IP: {base_ip}\n현재 공인IP: {current_ip}"
                )
                return True
        return False

    def _get_or_create_shared_chrome(self):
        """단순 눈으로 확인하는 용도의 크롬을 하나만 유지한다(같은 실행 안에서는
        재사용 — 클릭할 때마다 새 창이 여러 개 뜨지 않도록). --user-data-dir을
        지정하지 않으므로 Selenium이 매번 이 창을 새로 만들 때 자동으로 깨끗한
        임시 프로필(비로그인)을 생성한다 — 메인 포스팅 프로그램의 로그인 계정
        (chrome_profile1)과는 완전히 무관하다. 단순 조회에 로그인 계정을 쓰면
        검색 결과가 개인화되어 정확도가 떨어지고, 계정 활동이력에도 불필요한
        흔적이 남는다는 판단으로 분리했다."""
        if self._shared_chrome_driver is not None:
            try:
                _ = self._shared_chrome_driver.window_handles
                return self._shared_chrome_driver
            except Exception:
                self._shared_chrome_driver = None

        options = ChromeOptions()
        options.add_argument("--start-maximized")
        options.add_argument("--disable-blink-features=AutomationControlled")
        options.add_experimental_option("excludeSwitches", ["enable-automation"])
        options.add_experimental_option("useAutomationExtension", False)
        _default_ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36"
        options.add_argument(f"user-agent={get_env_value('chrome_user_agent', _default_ua)}")
        driver = webdriver.Chrome(options=options)

        # navigator.webdriver 숨기기 (자동화 탐지 회피용 지문 위장 — 프로필 공유와는 무관)
        driver.execute_cdp_cmd("Page.addScriptToEvaluateOnNewDocument", {
            "source": """
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                Object.defineProperty(navigator, 'plugins', { get: () => [1, 2, 3, 4, 5] });
                Object.defineProperty(navigator, 'languages', { get: () => ['ko-KR', 'ko', 'en-US', 'en'] });
                window.chrome = { runtime: {} };
                const getImageData = CanvasRenderingContext2D.prototype.getImageData;
                CanvasRenderingContext2D.prototype.getImageData = function(...args) {
                    const imageData = getImageData.apply(this, args);
                    for (let i = 0; i < imageData.data.length; i += 4) {
                        imageData.data[i] = imageData.data[i] ^ (Math.floor(Math.random() * 2));
                    }
                    return imageData;
                };
                const toDataURL = HTMLCanvasElement.prototype.toDataURL;
                HTMLCanvasElement.prototype.toDataURL = function(...args) {
                    const ctx = this.getContext('2d');
                    if (ctx) { ctx.getImageData(0, 0, 1, 1); }
                    return toDataURL.apply(this, args);
                };
                const getParameter = WebGLRenderingContext.prototype.getParameter;
                WebGLRenderingContext.prototype.getParameter = function(parameter) {
                    if (parameter === 37445) return 'Intel Inc.';
                    if (parameter === 37446) return 'Intel Iris OpenGL Engine';
                    return getParameter.apply(this, [parameter]);
                };
            """
        })

        self._shared_chrome_driver = driver
        return driver

    # ──────────────────────────────────────────────────────
    # [Ver9.12 신규] 제목 후보 자동 제목정밀검색 (셀레니움, 헤드리스)
    # Naver_blog_rank_module_20260905.py의 비-API 셀레니움 로직을
    # 이식. 판단 기준 — [Ver9.19 개정] 프롬프트A V16 [검색 노출 폭 확인] 2단계:
    #   - 따옴표 없는 자연어 검색만 쓴다(블로그tab). 통합검색은 판정에서 뺐다.
    #   - "'...'에 대한 검색결과가 없습니다"(빨간 안내문) → ❌ 미인식
    #   - (1) 전체 제목: 관련 글 그룹이 있어야 하고(0건이면 건수가 적어도 ❌),
    #     같거나 비슷한 제목이 있으면 ⚠️. 전체 제목 검색은 실제 검색이 아니라
    #     "포지션 잡기" 확인이다.
    #   - (2) 앞 핵심구(첫 콤마 앞): 관련 글이 반드시 있어야 하고(0건 ❌),
    #     PRECHECK_FRONT_DENSE_MAX 초과면 ⚠️ 밀집. 실제 유입은 이 짧은 키워드에서 걸린다.
    #   - 조사 결합 오독어(예: 신고가) 포함 시 ⚠️
    #   - 관련 글 수는 카드 텍스트에 핵심 토큰이 들어 있는지로 센 추정치다.
    #   (이전 기준: 블로그·통합 건수 2건 이하 '완전일치형', 50/30건 초과 '경쟁 과다')
    # 이 자동체크는 사람의 최종 판단(🔍 버튼으로 직접 열어 눈으로
    # 무관한 글인지 확인)을 대신하지 않는다 — 세 후보 중 어느 것부터
    # 확인할지 우선순위를 잡아주는 1차 필터 역할까지만 한다.
    # ──────────────────────────────────────────────────────

    def _get_or_create_precheck_driver(self):
        """제목정밀검색 전용 헤드리스 크롬. 공유 크롬(_get_or_create_shared_chrome,
        사람이 직접 보는 비-헤드리스 창)과는 완전히 분리한다 — 자동
        제목정밀검색이 후보 3개 × 2종(블로그/통합) = 최대 6번 백그라운드로
        검색하는데, 이걸 사람이 보는 창에서 하면 갑자기 탭이 여러 개
        열리며 화면을 가로채 혼란을 준다."""
        if self._precheck_driver is not None:
            try:
                _ = self._precheck_driver.window_handles
                return self._precheck_driver
            except Exception:
                self._precheck_driver = None

        options = ChromeOptions()
        # [Ver9.24] 순위 모듈(rank_create_chrome_driver)과 같은 옵션 — 그 모듈의 검색 화면
        # 구조로 파싱이 검증돼 있으므로 창 크기 등도 맞춘다.
        options.add_argument("--headless=new")
        options.add_argument("--window-size=1920,1080")
        options.add_argument("--disable-gpu")
        options.add_argument("--no-sandbox")
        options.add_argument("--disable-dev-shm-usage")
        # [Ver9.20] 이미지 로딩 차단 — 순위 조회 모듈(rank_create_chrome_driver)과 같은
        # 설정. 파싱은 제목 텍스트만 쓰고 스크롤 수집이 늘어 데이터 소모가 커졌기 때문.
        options.add_experimental_option("prefs", {"profile.managed_default_content_settings.images": 2})
        options.add_argument("--blink-settings=imagesEnabled=false")
        _default_ua = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36"
        options.add_argument(f"user-agent={get_env_value('chrome_user_agent', _default_ua)}")
        driver = webdriver.Chrome(options=options)
        self._precheck_driver = driver
        return driver

    def _precheck_ready(self, slots):
        """selenium이 없으면 해당 칸에 안내를 표시하고 False를 돌려준다."""
        if SELENIUM_OK:
            return True
        for sl in slots:
            self.title_precheck_vars[sl].set(
                "❌ selenium 미설치 — 제목정밀검색 불가(🔍 버튼은 사용 가능). pip install selenium")
        self._log_collect("[제목정밀검색] selenium이 설치돼 있지 않아 제목정밀검색을 건너뜁니다.")
        return False

    def _start_title_precheck(self):
        """"▶ 후보 제목정밀검색 실행" 버튼(_restart_title_precheck)에서 호출한다(Ver9.22부터
        후보를 불러올 때 자동으로 호출하지 않는다). 후보 3개(칸 0~2)만 대상이다.
        [Ver9.21] 예전에는 후보를 list()로 복사해 스레드에 넘긴 뒤 스레드가 원본과 같은
        객체인지 비교해서(항상 달라짐) 검색 없이 즉시 종료했다 — 이제 실행 번호로
        "이 실행이 아직 최신인가"만 확인한다."""
        targets = [(i, c["title"]) for i, c in enumerate(self.title_candidates[:3]) if c.get("title")]
        if not targets:
            return
        if not self._precheck_ready([sl for sl, _t in targets]):
            return
        self._precheck_run_id += 1
        run_id = self._precheck_run_id
        for sl, _t in targets:
            self.title_precheck_results[sl] = None
            self.title_precheck_items[sl] = None
            # 이전 실행이 붙인 "⭐ 1차 추천" 표시를 걷어낸다
            cur = self.title_cand_label_vars[sl].get()
            if cur.startswith("⭐ 1차 추천 "):
                self.title_cand_label_vars[sl].set(cur[len("⭐ 1차 추천 "):])
            self.title_precheck_vars[sl].set("⏳ 제목정밀검색 대기 중...")
        self._log_collect(f"[제목정밀검색] 후보 {len(targets)}개 제목정밀검색 시작 "
                          f"(전체 제목 + 앞 핵심구 검색, 후보당 1~2분 안팎)")
        include_back = bool(self.title_include_back_var.get())
        caps = PRECHECK_COLLECT_LEVELS.get(self.title_collect_var.get(), PRECHECK_COLLECT_LEVELS["많이"])
        threading.Thread(target=self._run_title_precheck,
                         args=(targets, run_id, "_precheck_run_id", include_back, caps), daemon=True).start()

    def _restart_title_precheck(self):
        """[Ver9.21 신규, Ver9.22 개칭] "▶ 후보 제목정밀검색 실행" 버튼 — 후보를 불러온 뒤 필요할
        때만 눌러 전체 제목·앞 핵심구 검색을 실행한다. 다시 누르면 처음부터 다시 실행한다."""
        if not any(c.get("title") for c in self.title_candidates):
            messagebox.showwarning("후보 없음",
                "제목정밀검색할 후보가 없습니다.\n위 [자동 채우기]로 프롬프트A 결과를 먼저 불러오세요.")
            return
        self._start_title_precheck()

    def _start_manual_precheck(self):
        """[Ver9.23 신규] "직접 입력으로 확정" 칸의 제목만 검색하는 "▶ 제목정밀검색" 버튼.
        후보와 같은 방식(전체 제목 + 앞 핵심구)이고 결과 칸은 4번째(직접 입력)다."""
        title = self.title_manual_var.get().strip()
        if not title:
            messagebox.showwarning("알림", "직접 입력 칸에 제목을 먼저 입력하세요.")
            return
        if not self._precheck_ready([3]):
            return
        self._manual_precheck_run_id += 1
        run_id = self._manual_precheck_run_id
        self.title_precheck_results[3] = None
        self.title_precheck_items[3] = None
        self.title_precheck_vars[3].set("⏳ 제목정밀검색 대기 중...")
        self._log_collect("[제목정밀검색] 직접 입력 제목 제목정밀검색 시작 (전체 제목 + 앞 핵심구 검색)")
        include_back = bool(self.title_include_back_var.get())
        caps = PRECHECK_COLLECT_LEVELS.get(self.title_collect_var.get(), PRECHECK_COLLECT_LEVELS["많이"])
        threading.Thread(target=self._run_title_precheck,
                         args=([(3, title)], run_id, "_manual_precheck_run_id", include_back, caps), daemon=True).start()

    def _run_title_precheck(self, targets, run_id, run_attr="_precheck_run_id", include_back=True, caps=None):
        """백그라운드 스레드. targets=[(칸 번호, 제목), ...] — 칸 0~2는 후보, 3은 직접 입력.
        제목마다 (1) 전체 제목 (2) 콤마 앞 핵심구를 블로그tab에서 따옴표 없이 검색하고,
        결과를 self.after(0, ...)로 메인 스레드에서만 UI에 반영한다(Tkinter는 스레드-세이프
        하지 않으므로 위젯 값은 반드시 메인 스레드에서 바꿔야 함). run_attr의 실행 번호가
        run_id와 다르면(새 후보를 불러왔거나 새 글을 시작함) 조용히 중단한다."""
        def alive():
            return run_id == getattr(self, run_attr)

        def name_of(sl):
            return f"후보 {sl + 1}" if sl < 3 else "직접 입력 제목"

        def setv(sl, text):
            def _do():
                if alive() and sl < len(self.title_precheck_vars):
                    self.title_precheck_vars[sl].set(text)
            self.after(0, _do)

        slots = [sl for sl, _t in targets]
        try:
            with self._precheck_lock:
                if not alive():
                    return
                for sl in slots:
                    setv(sl, "⏳ 크롬 시작 중... (처음 한 번은 수 초~수십 초 걸립니다)")
                try:
                    driver = self._get_or_create_precheck_driver()
                except Exception as e:
                    for sl in slots:
                        setv(sl, f"❌ 헤드리스 크롬 생성 실패: {str(e).splitlines()[0][:90] if str(e) else e}")
                    self._log_collect(f"[제목정밀검색] 헤드리스 크롬 생성 실패: {e}")
                    print(f"❌ [제목정밀검색] 헤드리스 크롬 생성 실패: {e}")
                    return

                for sl, title in targets:
                    if not alive():
                        return
                    nm = name_of(sl)
                    try:
                        front = policy_split_title_front(title)
                        norm_title = title.strip().rstrip("?？!！. ").strip()
                        same = (not front) or front == norm_title

                        finfo, rinfo, binfo = {}, {}, {}
                        back = policy_split_title_back(title) if include_back else ""
                        c_full, c_front, c_back, c_rounds = caps or PRECHECK_COLLECT_LEVELS["표준"]

                        setv(sl, f"⏳ {nm}: 전체 제목 검색 중...")
                        full_items, full_status = policy_collect_blog_results(
                            driver, title, c_full,
                            progress_fn=lambda n, sl=sl, nm=nm: setv(sl, f"⏳ {nm}: 전체 제목 검색 중... ({n}건 수집)"),
                            info=finfo, rounds=c_rounds)
                        if not alive():
                            return
                        if same:
                            front_items, front_status, rinfo = full_items, full_status, finfo
                        else:
                            time.sleep(random.uniform(1.5, 3.0))
                            setv(sl, f"⏳ {nm}: 앞 핵심구 '{front}' 검색 중...")
                            front_items, front_status = policy_collect_blog_results(
                                driver, front, c_front,
                                progress_fn=lambda n, sl=sl, nm=nm: setv(sl, f"⏳ {nm}: 앞 핵심구 검색 중... ({n}건 수집)"),
                                info=rinfo, rounds=c_rounds)
                            if not alive():
                                return

                        back_items, back_status = [], "ok"
                        if back:
                            time.sleep(random.uniform(1.5, 3.0))
                            setv(sl, f"⏳ {nm}: 뒷 구절 '{back}' 검색 중...")
                            back_items, back_status = policy_collect_blog_results(
                                driver, back, c_back,
                                progress_fn=lambda n, sl=sl, nm=nm: setv(sl, f"⏳ {nm}: 뒷 구절 검색 중... ({n}건 수집)"),
                                info=binfo, rounds=c_rounds)
                            if not alive():
                                return

                        result = {"title": title, "front": front, "back": back,
                                  "similar": policy_count_similar_titles(full_items, title),
                                  "blocked": "captcha" in (full_status, front_status, back_status),
                                  "block_reason": finfo.get("reason") or rinfo.get("reason") or binfo.get("reason", ""),
                                  "ambiguous": [t for t in PRECHECK_AMBIGUOUS_TERMS if t in title]}
                        result.update(policy_segment_result("full", title, full_items, full_status, finfo))
                        result.update(policy_segment_result("front", title, front_items, front_status, rinfo))
                        if back:
                            result.update(policy_segment_result("back", title, back_items, back_status, binfo))
                        result["kw_core"], result["kw_sub"] = policy_title_keywords(title)
                        level, text = policy_precheck_verdict(result)
                        result["level"] = level
                        pack = {"full": full_items, "front": front_items, "back": back_items}
                        self._append_precheck_log(dict(result, event="precheck", cand=sl + 1, manual=(sl >= 3)))
                        self._append_precheck_raw(policy_build_raw_record(sl, title, result, pack))
                        self._log_collect(f"[제목정밀검색] {nm}: {text}")

                        def _apply(sl=sl, result=result, text=text, pack=pack):
                            if not alive():
                                return
                            if sl < len(self.title_precheck_results):
                                self.title_precheck_results[sl] = result
                            if sl < len(self.title_precheck_items):
                                self.title_precheck_items[sl] = pack
                            self.title_precheck_vars[sl].set(text)
                        self.after(0, _apply)

                        if result["blocked"]:
                            bi = finfo if finfo.get("reason") else (rinfo if rinfo.get("reason") else binfo)
                            self._log_collect(
                                f"[제목정밀검색] 차단 의심 상세 — 사유: {bi.get('reason', '')} / "
                                f"주소: {bi.get('url', '')} / 페이지 제목: {bi.get('title', '')} / "
                                f"화면 문구: {bi.get('visible', '')}")
                            # 차단 상태에서 계속 검색하면 더 막히므로 남은 제목은 검색하지 않는다.
                            for other in slots:
                                if other > sl:
                                    setv(other, "⛔ 차단 감지로 제목정밀검색 중단")
                            break
                    except Exception as e:
                        traceback.print_exc()
                        setv(sl, f"❌ 확인 실패: {str(e)[:90]}")
                        self._log_collect(f"[제목정밀검색] {nm} 확인 실패: {e}")

                    # 캡차/차단 방지 — 제목 사이 대기
                    time.sleep(random.uniform(2.0, 4.0))

                if alive():
                    if run_attr == "_precheck_run_id":
                        self.after(0, lambda: alive() and self._recommend_best_title_candidate())
                    self._log_collect("[제목정밀검색] 완료 — 아래 ✅/⚠️/❌ 표시와 📋 검색결과 복사를 확인하세요.")
        except Exception as e:
            traceback.print_exc()
            for sl in slots:
                setv(sl, f"❌ 제목정밀검색 오류: {str(e)[:90]}")
            self._log_collect(f"[제목정밀검색] 오류: {e}")

    def _append_precheck_log(self, rec: dict):
        """[Ver9.19 신규] 제목정밀검색·제목 확정 기록을 title_precheck_log.jsonl에
        한 줄씩 누적한다. 발행 1~2주 뒤 같은 검색을 다시 돌려 순위와 비교하기
        위한 기록이며, 실패해도 본 흐름에는 영향이 없다."""
        try:
            rec = dict(rec)
            rec["at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
            with open(BASE_DIR / "title_precheck_log.jsonl", "a", encoding="utf-8") as fp:
                fp.write(json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception as e:
            print(f"[제목정밀검색 로그] 기록 실패(무시): {e}")

    def _append_precheck_raw(self, rec: dict):
        """[Ver9.27 신규] 검색 1건의 전체 목록(원자료)을 title_precheck_raw.jsonl에 누적한다.
        나중에 다시 검색하지 않고 Claude에게 주어 재분석할 수 있다. 실패해도 본 흐름에는 영향 없다."""
        try:
            rec = dict(rec)
            rec["at"] = datetime.now().strftime("%Y-%m-%d %H:%M")
            with open(BASE_DIR / "title_precheck_raw.jsonl", "a", encoding="utf-8") as fp:
                fp.write(json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception as e:
            print(f"[제목정밀검색 원자료] 기록 실패(무시): {e}")

    def _recommend_best_title_candidate(self):
        """제목정밀검색이 끝난 뒤 1차 추천 후보 하나를 표시한다. 최종 선택은 사람이
        라디오버튼으로 한다.
        [Ver9.19 수정] 전체 제목·앞 핵심구 모두 관련 글이 있고 과밀/유사 제목
        경고가 없는(✅) 후보 중 앞 핵심구 관련 글이 적은 쪽을 1차 추천한다.
        프롬프트A V16 원칙상 후보 선택은 본문 적합도가 먼저이고 검색 위치는
        그다음이므로, 이 추천은 참고일 뿐이다."""
        best_idx, best_key = None, None
        any_checked = False
        for i, r in enumerate(self.title_precheck_results[:3]):   # [Ver9.23] 직접 입력 칸(3)은 제외
            if not r:
                continue
            any_checked = True
            if r.get("level", 0) < 2:
                continue
            key = (r.get("front_strong", 0) + r.get("front_mid", 0),
                   r.get("full_strong", 0) + r.get("full_mid", 0))
            if best_key is None or key < best_key:
                best_idx, best_key = i, key

        if not any_checked:
            return
        if best_idx is None:
            self.title_confirm_status.set(
                "⚠️ 제목정밀검색 결과 ✅(전체 제목·앞 핵심구 모두 관련 글이 있고 과밀하지 않음)인 후보가 "
                "없습니다. ⚠️ 후보는 🔍 버튼으로 직접 열어 눈으로 확인하고, ❌뿐이면 회피 목록 "
                "복사로 재추천을 요청하세요.")
            return
        current = self.title_cand_label_vars[best_idx].get()
        if not current.startswith("⭐ 1차 추천 "):
            self.title_cand_label_vars[best_idx].set("⭐ 1차 추천 " + current)
        self.title_confirm_status.set(
            f"제목정밀검색 결과 [{best_idx+1}]번 후보를 1차 추천합니다(참고용). "
            "본문 적합도를 먼저 보고, 🔍 버튼으로 직접 확인한 뒤 라디오버튼으로 최종 확정하세요.")

    def _open_naver_shared_chrome(self, url):
        """IP 체크 통과 시 비로그인 임시 프로필 크롬으로 URL을 새 탭으로 연다 (이미 열려있으면 재사용)"""
        if not SELENIUM_OK:
            messagebox.showerror(
                "selenium 미설치",
                "selenium이 설치되어 있지 않습니다.\n\n명령 프롬프트에서 아래 명령을 실행 후 다시 시도하세요.\npip install selenium"
            )
            return
        if self._check_ip_before_naver_open():
            return
        try:
            driver = self._get_or_create_shared_chrome()
            driver.execute_script("window.open(arguments[0], '_blank');", url)
            driver.switch_to.window(driver.window_handles[-1])
        except Exception:
            # 기존 드라이버가 이미 죽어있었을 가능성 - 한 번 더 새로 만들어서 재시도
            self._shared_chrome_driver = None
            try:
                driver = self._get_or_create_shared_chrome()
                driver.execute_script("window.open(arguments[0], '_blank');", url)
                driver.switch_to.window(driver.window_handles[-1])
            except Exception as e2:
                messagebox.showerror("크롬 열기 실패", str(e2))

    # ──────────────────────────────────────────────────────
    # TAB 1 : 수집
    # ──────────────────────────────────────────────────────
    def _build_tab1_collect(self):
        f = ttk.Frame(self.nb, padding=10)
        self.nb.add(f, text="📡 1)뉴스 수집")
        f.columnconfigure(0, weight=1)
        f.rowconfigure(5, weight=1)

        # [Ver7.14 추가] 이 프로그램이 하는 일(수집·정리·초안 준비)과
        # 사람이 클로드 웹에서 직접 해야 하는 일(자료 검토·각색, 인포그래픽
        # 이미지 설계)을 처음 보는 사람도 바로 구분할 수 있도록, 탭 맨
        # 위에 크고 눈에 띄는 파란색 안내 문구를 둔다.
        banner_f = tk.Frame(f, bg="#E3F2FD", padx=8, pady=6)
        banner_f.grid(row=0, column=0, sticky="ew", pady=(0,8))
        tk.Label(banner_f,
                 text="📌 자료 검토 및 각색, 인포그래픽 이미지 설계는 클로드 웹(claude.ai)에서 진행합니다.",
                 bg="#E3F2FD", fg="DarK red", # fg="#0D47A1",
                 font=("맑은 고딕", 13, "bold")).pack(anchor="w")

        # 상단 버튼
        btn_f = ttk.Frame(f)
        btn_f.grid(row=1, column=0, sticky="ew", pady=(0,6))

        self.collect_btn = ttk.Button(btn_f, text="▶ 지금 수집하기", command=self._on_collect, style="Copy.TButton")
        self.collect_btn.pack(side="left", padx=(0,8))

        self.collect_status = ttk.Label(btn_f, text="대기 중", foreground="gray")
        self.collect_status.pack(side="left", padx=(0,12))

        ttk.Button(btn_f, text="🔄 목록 새로고침",
                   command=self._refresh_tab1).pack(side="left", padx=(0,8))

        ttk.Button(btn_f, text="➕ 수동 등록",
                   command=self._open_manual_add_dialog).pack(side="left", padx=(0,8))

        ttk.Button(btn_f, text="결과 폴더 열기", command=lambda: open_folder(BASE_DIR)).pack(side="right")

        # 자동 수집 (지정 시간 단위로 반복 수집 + 신규 발견 시 팝업 알림)
        auto_f = ttk.LabelFrame(f, text="⏱ 자동 수집 — 정보는 속도전, 지정한 주기마다 자동으로 수집합니다", padding=8)
        auto_f.grid(row=2, column=0, sticky="ew", pady=(0,6))

        # [위치 변경] 부처/발행일 필터 — 자동수집 줄 맨 앞쪽에 배치해
        # 가장 먼저 눈에 띄게 한다.
        ttk.Label(auto_f, text="부처:").pack(side="left", padx=(0,2))
        self.dept_filter_var = tk.StringVar(value="전체")
        self.dept_filter_combo = ttk.Combobox(auto_f, textvariable=self.dept_filter_var,
                                               values=["전체"], width=14, state="readonly")
        self.dept_filter_combo.pack(side="left")
        self.dept_filter_combo.bind("<<ComboboxSelected>>", lambda e: self._refresh_collect_tree())

        ttk.Label(auto_f, text="  발행일:").pack(side="left", padx=(8,2))
        self.date_filter_var = tk.StringVar(value="전체")
        date_filter_combo = ttk.Combobox(auto_f, textvariable=self.date_filter_var,
                                          values=["전체", "오늘", "최근 3일", "최근 7일", "최근 30일"],
                                          width=10, state="readonly")
        date_filter_combo.pack(side="left")
        date_filter_combo.bind("<<ComboboxSelected>>", lambda e: self._refresh_collect_tree())

        ttk.Separator(auto_f, orient="vertical").pack(side="left", fill="y", padx=12)

        ttk.Label(auto_f, text="수집 주기:").pack(side="left", padx=(0,4))
        self.auto_interval_var = tk.StringVar(value="60")
        ttk.Entry(auto_f, textvariable=self.auto_interval_var, width=5).pack(side="left")
        ttk.Label(auto_f, text="분마다").pack(side="left", padx=(2,12))

        self.auto_collect_btn = ttk.Button(auto_f, text="▶ 자동 수집 시작",
                                            command=self._toggle_auto_collect,
                                            style="Copy.TButton")
        self.auto_collect_btn.pack(side="left", padx=(0,8))

        self.auto_collect_status_var = tk.StringVar(value="자동 수집 꺼짐")
        ttk.Label(auto_f, textvariable=self.auto_collect_status_var,
                  foreground="gray").pack(side="left")

        self._auto_collect_running = False
        self._auto_collect_job = None
        # [Ver9.06 추가] 자동수집 타이머와 수동 "▶ 지금 수집하기"가 동시에
        # 실행되면 둘 다 run_collect() 안에서 load_seen()/save_seen()으로
        # seen.json 전체를 읽고 통째로 다시 쓰는 구조라, 나중에 저장을 끝내는
        # 쪽이 먼저 저장된 신규 링크를 덮어써 유실시킬 수 있다(레이스 컨디션).
        # 이 플래그로 두 경로가 서로 배타적으로만 실행되게 막는다 — 자세한
        # 사용처는 _on_collect/_run_auto_collect_once/_on_collect_done 참고.
        self._collecting = False

        ttk.Label(f, text="💡 대량 후보 검토(프롬프트0 결과 반영)는 [🗂 2.뉴스대량검토] 탭에서 합니다.",
                  style="Info.TLabel").grid(row=3, column=0, sticky="w", pady=(0,2))

        # 안내 — 부처/발행일 필터는 위쪽 자동수집 줄 앞쪽으로 이동했다.
        # (패스·완료는 검토 목적상 항상 숨김. 완료 항목은 이력관리 탭에서 본다)
        filter_f = ttk.Frame(f)
        filter_f.grid(row=4, column=0, sticky="ew", pady=(0,4))

        ttk.Label(filter_f, text="발행일 최신순 | 🟢 신규  🟠 첨부파일만",
                  style="Info.TLabel").pack(side="left")

        self.collect_count_var = tk.StringVar(value="")
        ttk.Label(filter_f, textvariable=self.collect_count_var,
                  foreground="darkblue", font=("맑은 고딕", 9, "bold")).pack(side="right")

        # 리스트 영역
        list_f = ttk.LabelFrame(f, text="수집 결과 (콘텐츠 후보)", padding=5)
        list_f.grid(row=5, column=0, sticky="nsew")
        list_f.columnconfigure(0, weight=1)
        list_f.rowconfigure(0, weight=1)

        cols = ("발행일", "제목", "부처", "본문유형", "라이선스", "처리상태")
        # [Ver7.17] selectmode="extended"를 명시한다 — ttk 기본값도
        # extended라 지금까지도 Ctrl/Shift-클릭으로 다중선택 자체는 됐지만,
        # 명시하지 않으면 다른 위젯 스타일 설정에 의해 조용히 바뀔 수 있어
        # 확실히 고정해둔다. 진짜 문제는 선택이 아니라 "선택한 것만 복사"가
        # 안 됐던 것 — 아래 _copy_collect_list_for_prompt0에서 함께 고친다.
        self.collect_tree = ttk.Treeview(list_f, columns=cols, show="headings",
                                          height=20, selectmode="extended")
        widths = [60, 460, 60, 50, 55, 40]
        for col, w in zip(cols, widths):
            self.collect_tree.heading(col, text=col)
            self.collect_tree.column(col, width=w, anchor="w")

        vsb = ttk.Scrollbar(list_f, orient="vertical", command=self.collect_tree.yview)
        self.collect_tree.configure(yscrollcommand=vsb.set)
        self.collect_tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")

        ttk.Label(list_f,
                  text="Ctrl-클릭: 하나씩 추가/해제  |  Shift-클릭: 범위 선택  |  "
                       "선택 후 Ctrl+C 또는 대량검토 탭의 [TAB1 목록 복사]로 선택한 것만 복사됩니다"
                       "  (선택 없이 누르면 화면에 보이는 전체가 복사됩니다)",
                  style="Info.TLabel").grid(row=1, column=0, columnspan=2, sticky="w", pady=(2,0))

        self.collect_tree.bind("<<TreeviewSelect>>", self._on_article_select)
        # [Ver7.17 추가] Treeview에 포커스가 있는 상태에서 Ctrl+C를 누르면
        # 선택된 행들을 바로 클립보드에 복사한다(선택이 없으면 화면에
        # 보이는 전체를 복사) — _copy_collect_list_for_prompt0와 동일한
        # 로직을 재사용한다.
        self.collect_tree.bind("<Control-c>", lambda e: self._copy_collect_list_for_prompt0())
        self.collect_tree.tag_configure("new",  background="#E8F5E9")
        self.collect_tree.tag_configure("pdf",  background="#FFF3E0")
        self.collect_tree.tag_configure("screening", background="#FFF9C4")
        # 공공누리 "변경금지" 기사는 각색하면 안 되므로 다른 색보다 눈에 띄는
        # 붉은 계열로 표시한다 (검토중 상태보다는 덜 우선이지만 신규·PDF보다 우선)
        self.collect_tree.tag_configure("license_warn", background="#FFCDD2")

        # 미리보기 + 보내기 버튼
        preview_f = ttk.LabelFrame(f, text="선택 기사 미리보기", padding=5)
        preview_f.grid(row=6, column=0, sticky="ew", pady=(6,0))
        preview_f.columnconfigure(0, weight=1)

        self.preview_text = tk.Text(preview_f, height=5, wrap="word", state="disabled",
                                    font=("맑은 고딕", 9))
        self.preview_text.grid(row=0, column=0, sticky="ew")

        btn_f2 = ttk.Frame(preview_f)
        btn_f2.grid(row=1, column=0, sticky="e", pady=(4,0))
        ttk.Button(btn_f2, text="🔗 원문 열기", command=self._open_article_link).pack(side="left", padx=(0,6))
        ttk.Button(btn_f2, text="⏭ 패스", command=self._mark_pass).pack(side="left", padx=(0,6))
        ttk.Button(btn_f2, text="🔎 검토중", command=self._mark_review).pack(side="left", padx=(0,6))
        ttk.Button(btn_f2, text="⏭ 신규 전체 패스 (검토중·보류 제외)",
                   command=self._mark_all_pass).pack(side="left", padx=(0,6))
        ttk.Button(btn_f2, text="→ 분석 준비로 보내기", command=self._send_to_analyze,
                   style="Copy.TButton").pack(side="left")

        # 로그
        log_f = ttk.LabelFrame(f, text="수집 로그", padding=5)
        log_f.grid(row=7, column=0, sticky="ew", pady=(6,0))
        self.collect_log = scrolledtext.ScrolledText(log_f, height=8, state="disabled",
                                                     font=("맑은 고딕", 8), wrap="word")
        self.collect_log.pack(fill="both")

        f.rowconfigure(4, weight=3)

    def _auto_load_pending(self):
        """시작 시 후보군 엑셀에서 미완료 항목을 자동으로 TAB1에 로드
        패스·발행준비완료·포스팅완료 제외하고 전부 표시 (신규·작성중·보류·
        상태없음 포함). 완료된 건 TAB5 이력관리에서 보면 되므로 여기서는
        아예 제외한다."""
        if not os.path.exists(_get_xlsx_candidate_path()) or not OPENPYXL_OK:
            return

        EXCLUDE_STATUS = ["패스", "완료"]  # 발행준비완료·포스팅완료 모두 포함
        history   = load_history()
        link_status = {r.get("link",""): r.get("status","") for r in history}

        try:
            wb = load_workbook(_get_xlsx_candidate_path(), read_only=True)
            ws = wb.active
            pending = []
            seen    = set()
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[2]:  # 제목 없으면 스킵
                    continue
                link = str(row[7]).strip() if row[7] else ""
                if not link or link in seen:
                    continue
                # 이력에서 상태 확인
                st = link_status.get(link, "")
                # 패스·발행준비완료·포스팅완료는 제외
                if any(x in st for x in EXCLUDE_STATUS):
                    continue
                pub_raw = str(row[4]).strip() if row[4] else ""
                remark  = str(row[6]).strip() if row[6] else ""
                pending.append({
                    "title":        str(row[2]).strip(),
                    "dept":         str(row[3]).strip() if row[3] else "",
                    "published":    pub_raw,
                    "pub_dt":       parse_published(pub_raw),
                    "body_type":    str(row[5]).strip() if row[5] else "",
                    "link":         link,
                    "is_new":       not bool(st),  # 상태 없으면 신규
                    "license_warn": "변경금지" in remark,
                })
                seen.add(link)
            wb.close()
        except Exception as e:
            self._log_collect(f"[자동 로드 오류] {e}")
            return

        if not pending:
            self._log_collect("[시작] 후보군 엑셀에 미완료 항목 없음")
            return

        pending.sort(key=lambda x: x["pub_dt"], reverse=True)
        self.collected = pending
        self._refresh_collect_tree()
        self.collect_status.config(
            text=f"엑셀에서 {len(pending)}건 자동 로드 (패스·완료 제외)",
            foreground="darkblue")
        self._log_collect(
            f"[시작] 후보군 엑셀에서 {len(pending)}건 자동 로드\n"
            f"  (패스·발행준비완료·포스팅완료 제외 / 수집 버튼으로 새 기사 추가 가능)")

    def _refresh_tab1(self):
        """TAB1 목록을 이력 상태 기준으로 새로고침 (엑셀 재로드)"""
        self.history = load_history()
        self._refresh_collect_tree()
        # 엑셀에서도 최신 상태 반영
        if os.path.exists(_get_xlsx_candidate_path()):
            self._auto_load_pending()
        self._log_collect("[새로고침] TAB1 목록 업데이트 완료")

    def _on_collect(self):
        # [Ver9.06 추가] 자동수집이 이미 진행 중이면 중복 실행을 막는다 —
        # seen.json 레이스 컨디션 방지 (self._collecting 설명 참고).
        if getattr(self, "_collecting", False):
            messagebox.showinfo("알림", "이미 수집이 진행 중입니다. 끝날 때까지 잠시 기다려주세요.")
            return
        self._collecting = True
        self.collect_btn.config(state="disabled")
        self.collect_status.config(text="수집 중...", foreground="orange")
        self._log_collect("── 수집 시작 ──")

        def worker():
            results = run_collect(log=self._log_collect)
            self.after(0, lambda: self._on_collect_done(results))

        threading.Thread(target=worker, daemon=True).start()

    # [추가] 엑셀 저장 실패 시 재시도 루프 — 공통 헬퍼
    # 예전에는 "엑셀이 열려있어 저장 실패 → 팝업 한 번 띄우고 그냥 진행"
    # 방식이었다. 문제는 화면(메모리)엔 반영됐는데 엑셀엔 기록이 안 된
    # 채로 다음 작업이 계속 이어진다는 점 — 특히 수집의 경우 seen.json에는
    # 이미 "처리됨"으로 기록되기 때문에(run_collect 참고), 저장이 안 된
    # 채 넘어가면 그 기사는 다음 수집에서도 다시 안 잡히고 영구 유실된다.
    # 그래서 저장이 "성공" 하거나 사용자가 "포기(취소)"를 명시적으로
    # 선택할 때까지 같은 저장을 반복 시도한다 — 작업을 끝까지 마무리해야
    # 데이터 무결성이 보장된다는 원칙.
    def _save_xlsx_with_retry(self, save_fn, file_label: str, extra_note: str = "",
                               from_bg_thread: bool = False) -> tuple:
        """save_fn을 실행해 성공하면 (True, 반환값)을 준다.
        엑셀이 열려있는 등의 이유로 실패하면 [다시 시도/취소] 팝업을 띄우고,
        [다시 시도]를 누르면 곧바로 다시 save_fn을 실행한다(사용자가 그 사이
        엑셀을 닫았는지 재확인하는 셈). [취소]를 누르면 (False, None)을 반환한다
        — 이 경우 호출부에서 반드시 "저장 안 됨"을 명확히 알려야 한다.
        from_bg_thread=True면 백그라운드 스레드에서 안전하게 호출할 수 있도록
        팝업을 메인 스레드로 넘기고 threading.Event로 결과를 기다린다."""
        while True:
            try:
                return True, save_fn()
            except Exception as e:
                msg = (f"{file_label} 저장에 실패했습니다.\n"
                       f"(엑셀 프로그램에서 이 파일을 열어두면 저장할 수 없습니다)\n\n"
                       f"오류: {e}\n\n"
                       f"엑셀에서 파일을 완전히 닫은 뒤 [다시 시도]를 눌러주세요.\n"
                       f"{extra_note}")
                if from_bg_thread:
                    done = threading.Event()
                    answer = {}
                    def ask():
                        answer["retry"] = messagebox.askretrycancel("엑셀 저장 실패", msg)
                        done.set()
                    self.after(0, ask)
                    done.wait()
                    retry = answer.get("retry", False)
                else:
                    retry = messagebox.askretrycancel("엑셀 저장 실패", msg)
                if not retry:
                    return False, None

    def _on_collect_done(self, results, is_auto: bool = False):
        # [Ver9.06 추가] 수동·자동 두 경로 모두 최종적으로 여기를 거치므로
        # (_on_auto_collect_done도 이 함수를 호출), 진행 중 플래그를 해제하는
        # 지점을 한 곳으로 통일한다.
        self._collecting = False
        self.collect_btn.config(state="normal")

        # 기존 작업중 항목과 병합 (중복 링크 제거)
        existing_links = {a["link"] for a in self.collected}
        new_items = [r for r in results if r["link"] not in existing_links]
        merged = self.collected + new_items
        merged.sort(key=lambda x: x["pub_dt"], reverse=True)
        self.collected = merged

        self.collect_status.config(
            text=f"수집완료 (신규 {len(new_items)}건 추가 / 전체 {len(merged)}건)",
            foreground="green")

        # 후보군 엑셀 저장 (신규가 있을 때만 — 0건이면 저장할 것도 없음)
        # 엑셀이 열려있으면 wb.save()가 실패한다. run_collect()가 이미
        # seen.json에 "처리됨"으로 기록해버린 뒤라서(중복 방지 목적),
        # 여기서 저장을 포기하면 이 기사들은 다음 수집에서도 다시 안
        # 잡히고 영구 유실된다 — 그래서 저장이 성공하거나 사용자가
        # 명시적으로 포기할 때까지 재시도한다.
        fpath = ""
        if results:
            ok, fpath = self._save_xlsx_with_retry(
                lambda: save_candidate_xlsx(results) or "",
                file_label="후보군 엑셀",
                extra_note=f"(이번 수집 결과 {len(results)}건은 이미 화면에 추가된 상태이며,\n"
                           f"저장에 성공해야 다음에 프로그램을 다시 켜도 유지됩니다.)"
            )
            if ok:
                if fpath:
                    self._log_collect(f"[엑셀 저장] {os.path.basename(fpath)}")
            else:
                # 저장을 끝내 포기한 경우, seen.json에 이미 "처리됨"으로
                # 등록된 이 링크들을 다시 빼준다 — 그래야 다음 수집 때
                # 재수집이라도 시도할 수 있다(안 빼면 영구 유실).
                try:
                    seen = load_seen()
                    seen -= {a.get("link", "") for a in results}
                    save_seen(seen)
                    self._log_collect(f"[엑셀 저장 포기] {len(results)}건 — seen.json에서도 제거해 다음 수집 때 재시도 가능하게 함")
                except Exception as e:
                    self._log_collect(f"[엑셀 저장 포기] seen.json 되돌리기 실패: {e}")
                messagebox.showwarning(
                    "⚠️ 엑셀 저장 안 됨 — 데이터 유실 주의",
                    f"이번 수집 결과 {len(results)}건이 엑셀에 저장되지 않았습니다.\n\n"
                    f"다음 수집을 다시 실행하면 이 기사들은 재수집을 시도합니다.\n"
                    f"(지금 화면에는 이미 반영돼 있지만, '🔄 목록 새로고침'을 누르거나\n"
                    f"프로그램을 끄면 화면에서는 사라집니다.)"
                )
        self._refresh_collect_tree()

        # 결과가 있든 없든, 수집이 끝났다는 사실과 결과를 항상 팝업으로 정리해 보여준다.
        self._show_collect_summary(new_items, fpath, is_auto=is_auto)
        return new_items

    def _show_collect_summary(self, new_items: list, fpath: str, is_auto: bool = False):
        """수집 1회가 끝날 때마다 결과를 정리해서 팝업으로 보여준다.
        신규가 0건이어도 띄운다 — "수집은 됐는데 결과를 못 봤다"는
        불확실함을 없애기 위해서다."""
        now_str = datetime.now().strftime("%H:%M")
        title = f"📡 수집 완료 ({now_str})"

        if not new_items:
            messagebox.showinfo(title, "이번 수집에서 새로 발견된 기사가 없습니다.\n(이미 본 기사이거나, 조건에 맞는 기사가 없었습니다)")
            return

        titles = "\n".join(f"· {a['title'][:45]}" for a in new_items[:10])
        more = f"\n…외 {len(new_items)-10}건" if len(new_items) > 10 else ""
        msg = f"신규 기사 {len(new_items)}건이 수집됐습니다.\n\n{titles}{more}\n\nTAB1 목록에서 확인하세요."

        if fpath and not is_auto:
            messagebox.showinfo(title,
                    msg + f"\n\n엑셀 파일도 저장됐습니다: {os.path.basename(fpath)}")
        else:
            messagebox.showinfo(title, msg)

    # ── [Ver7.15 추가] 수동 등록 — 프로그램이 놓쳤거나 걸러낸 기사를
    # 사람이 사이트에서 직접 찾아서 TAB1 목록에 끼워넣는 기능 ──
    def _open_manual_add_dialog(self):
        """정책브리핑(korea.kr) 링크를 사람이 직접 붙여넣어 TAB1 목록에
        등록하는 창. 자동 수집·필터링 로직이 놓쳤거나 걸러낸 기사를
        수동으로 보완하기 위한 것 — "🔍 자동 채우기"로 제목·부처·발행일을
        링크에서 가져올 수 있지만, 실패하거나 마음에 안 들면 직접
        수정해서 등록해도 된다."""
        dlg = tk.Toplevel(self)
        dlg.title("➕ 기사 수동 등록")
        dlg.resizable(False, False)
        dlg.transient(self)
        dlg.grab_set()

        frm = ttk.Frame(dlg, padding=14)
        frm.pack(fill="both", expand=True)
        frm.columnconfigure(1, weight=1)

        ttk.Label(frm, text="사이트에서 직접 찾은 기사를 링크로 등록합니다.",
                  style="Info.TLabel").grid(row=0, column=0, columnspan=3, sticky="w", pady=(0,8))

        ttk.Label(frm, text="링크 *").grid(row=1, column=0, sticky="w", pady=4)
        link_var = tk.StringVar()
        ttk.Entry(frm, textvariable=link_var, width=52).grid(row=1, column=1, sticky="ew", padx=(6,6))

        title_var = tk.StringVar()
        dept_var  = tk.StringVar()
        pub_var   = tk.StringVar(value=datetime.now().strftime("%Y-%m-%d %H:%M"))
        body_var  = tk.StringVar(value="확인필요")

        def do_autofill():
            link = link_var.get().strip()
            if not link:
                messagebox.showwarning("알림", "링크를 먼저 입력하세요.")
                return
            body_var.set(get_body_type(link))
            info = fetch_article_detail_info(link, log=self._log_collect)
            if info.get("title"):
                title_var.set(info["title"])
                m = _ORG_PAT.search(info["title"])
                if m:
                    dept_var.set(m.group(0))
            if info.get("published_time"):
                pub_var.set(info["published_time"])
            if not info.get("title") and not info.get("published_time"):
                messagebox.showwarning("자동 채우기 실패",
                    "페이지에서 제목·발행일을 읽지 못했습니다.\n"
                    "직접 입력해 주세요. (본문유형은 링크 형식으로 채워졌습니다)")

        ttk.Button(frm, text="🔍 자동 채우기", command=do_autofill).grid(row=1, column=2, sticky="w")

        ttk.Label(frm, text="제목 *").grid(row=2, column=0, sticky="w", pady=4)
        ttk.Entry(frm, textvariable=title_var, width=52).grid(row=2, column=1, columnspan=2, sticky="ew", padx=(6,0))

        ttk.Label(frm, text="부처").grid(row=3, column=0, sticky="w", pady=4)
        ttk.Entry(frm, textvariable=dept_var, width=30).grid(row=3, column=1, sticky="w", padx=(6,0))

        ttk.Label(frm, text="발행일").grid(row=4, column=0, sticky="w", pady=4)
        ttk.Entry(frm, textvariable=pub_var, width=30).grid(row=4, column=1, sticky="w", padx=(6,0))
        ttk.Label(frm, text="(YYYY-MM-DD HH:MM)", style="Info.TLabel").grid(row=4, column=2, sticky="w")

        ttk.Label(frm, text="본문유형").grid(row=5, column=0, sticky="w", pady=4)
        ttk.Combobox(frm, textvariable=body_var, state="readonly", width=15,
                     values=["본문있음", "첨부파일만", "확인필요"]).grid(row=5, column=1, sticky="w", padx=(6,0))

        btn_f = ttk.Frame(frm)
        btn_f.grid(row=6, column=0, columnspan=3, sticky="e", pady=(14,0))
        ttk.Button(btn_f, text="취소", command=dlg.destroy).pack(side="right", padx=(8,0))
        ttk.Button(btn_f, text="등록", style="Copy.TButton",
                   command=lambda: self._manual_add_article(
                       dlg, link_var.get().strip(), title_var.get().strip(),
                       dept_var.get().strip(), pub_var.get().strip(), body_var.get())
                   ).pack(side="right")

        dlg.update_idletasks()
        x = self.winfo_rootx() + (self.winfo_width() - dlg.winfo_width()) // 2
        y = self.winfo_rooty() + (self.winfo_height() - dlg.winfo_height()) // 2
        dlg.geometry(f"+{max(x,0)}+{max(y,0)}")

    def _manual_add_article(self, dlg, link, title, dept, pub_str, body_type):
        """수동 등록 창의 '등록' 버튼 처리. self.collected(TAB1 메모리
        목록)에 추가하고, 후보군 엑셀에도 같이 저장해서 자동 수집으로
        들어온 기사와 완전히 동일하게 취급되게 한다(TAB7 등록, 중복
        체크 등 뒤이은 모든 과정에서 자동수집분과 구분할 필요가 없다)."""
        if not link or not title:
            messagebox.showwarning("입력 필요", "링크와 제목은 필수입니다.")
            return
        if not (link.startswith("http://") or link.startswith("https://")):
            messagebox.showwarning("링크 확인", "올바른 URL 형식이 아닙니다(http/https로 시작해야 함).")
            return

        existing_links = {a["link"] for a in self.collected}
        if link in existing_links:
            if not messagebox.askyesno("중복 확인",
                    "이미 TAB1 목록에 있는 링크입니다.\n그래도 등록하시겠습니까?(내용을 덮어씁니다)"):
                return
            self.collected = [a for a in self.collected if a["link"] != link]
        if link in get_done_links():
            if not messagebox.askyesno("확인",
                    "이미 처리(패스·발행준비완료·포스팅완료)된 링크입니다.\n"
                    "그래도 TAB1 목록에 다시 등록하시겠습니까?"):
                return

        pub_dt = parse_published(pub_str)
        article = {
            "title":        title,
            "link":         link,
            "dept":         dept,
            "published":    pub_str,
            "pub_dt":       pub_dt,
            "body_type":    body_type,
            "is_new":       True,
            "license_warn": False,
        }
        self.collected = self.collected + [article]
        self.collected.sort(key=lambda x: x["pub_dt"], reverse=True)

        ok, fpath = self._save_xlsx_with_retry(
            lambda: save_candidate_xlsx([article]) or "",
            file_label="후보군 엑셀",
            extra_note="(지금 취소하면 이 기사는 엑셀에 저장되지 않고, 화면 새로고침 시 사라질 수 있습니다.)"
        )
        if ok:
            if fpath:
                self._log_collect(f"[수동 등록] 엑셀에도 저장됨: {os.path.basename(fpath)}")
        else:
            self._log_collect(f"[수동 등록] 엑셀 저장 포기(화면에는 반영됨): {title[:40]}")
            messagebox.showwarning("⚠️ 엑셀 저장 안 됨",
                f"화면에는 등록됐지만 후보군 엑셀 저장에는 실패했습니다.\n"
                f"프로그램을 끄거나 '🔄 목록 새로고침'을 누르면 이 기사는 사라집니다.")

        self._refresh_collect_tree()
        self._log_collect(f"[수동 등록] {title[:40]}")
        dlg.destroy()
        messagebox.showinfo("등록 완료", f"TAB1 목록에 등록되었습니다.\n\n{title}")

    # ── 자동 수집 (지정 시간 단위로 반복) ──
    def _toggle_auto_collect(self):
        if self._auto_collect_running:
            self._stop_auto_collect()
        else:
            self._start_auto_collect()

    def _start_auto_collect(self):
        try:
            minutes = float(self.auto_interval_var.get().strip())
            if minutes <= 0:
                raise ValueError
        except (ValueError, AttributeError):
            messagebox.showwarning("알림", "수집 주기는 0보다 큰 숫자(분)로 입력하세요.")
            return

        self._auto_collect_running = True
        self.auto_collect_btn.config(text="⏸ 자동 수집 정지")
        self.auto_collect_status_var.set(f"자동 수집 중 ({minutes:.0f}분마다)")
        self._log_collect(f"[자동 수집] 시작 — {minutes:.0f}분마다 반복")
        self._schedule_auto_collect(minutes)

    def _stop_auto_collect(self):
        self._auto_collect_running = False
        if self._auto_collect_job is not None:
            self.after_cancel(self._auto_collect_job)
            self._auto_collect_job = None
        self.auto_collect_btn.config(text="▶ 자동 수집 시작")
        self.auto_collect_status_var.set("자동 수집 꺼짐")
        self._log_collect("[자동 수집] 정지")

    def _schedule_auto_collect(self, minutes: float):
        if not self._auto_collect_running:
            return
        self._run_auto_collect_once()
        self._auto_collect_job = self.after(
            int(minutes * 60 * 1000),
            lambda: self._schedule_auto_collect(minutes))

    def _run_auto_collect_once(self):
        """타이머가 호출하는 1회 수집. 완료되면 신규 건수를 팝업으로 알린다.
        [Ver9.06 추가] 수동 "▶ 지금 수집하기"가 이미 진행 중이면 이번 회차는
        건너뛴다 — seen.json 레이스 컨디션 방지 (self._collecting 설명 참고).
        건너뛰어도 자동수집 자체는 꺼지지 않고 다음 주기에 다시 시도한다."""
        if getattr(self, "_collecting", False):
            self._log_collect("[자동 수집] 건너뜀 — 다른 수집이 이미 진행 중입니다.")
            return
        self._collecting = True
        self.collect_status.config(text="자동 수집 중...", foreground="orange")
        self._log_collect("── 자동 수집 실행 ──")

        def worker():
            results = run_collect(log=self._log_collect)
            self.after(0, lambda: self._on_auto_collect_done(results))

        threading.Thread(target=worker, daemon=True).start()

    def _on_auto_collect_done(self, results):
        # 결과 팝업은 _on_collect_done → _show_collect_summary에서 이미 처리한다
        # (0건이어도 항상 띄움). 여기서는 자동수집 상태 표시줄만 갱신한다.
        new_items = self._on_collect_done(results, is_auto=True) or []
        now_str = datetime.now().strftime("%H:%M")
        if not new_items:
            self._log_collect(f"[자동 수집] {now_str} 완료 — 신규 없음")
        if self._auto_collect_running:
            self.auto_collect_status_var.set(
                f"자동 수집 중 (방금 확인: {now_str}, 신규 {len(new_items)}건)")


    def _load_selected_from_xlsx(self):
        """후보군 엑셀에서 A열=O 항목 불러와서 GUI 리스트에 표시"""
        if not os.path.exists(_get_xlsx_candidate_path()):
            messagebox.showwarning("알림",
                f"후보군 엑셀 파일이 없습니다.\n먼저 수집을 실행하세요.\n({_get_xlsx_candidate_path()})")
            return
        selected = load_selected_from_xlsx()
        if not selected:
            messagebox.showinfo("알림",
                "A열에 O 표시된 항목이 없습니다.\n"
                "엑셀을 열어서 포스팅할 기사의 A열에 O를 입력하고 저장 후 다시 시도하세요.")
            return
        self.collected = selected
        self._refresh_collect_tree()
        self.collect_status.config(
            text=f"엑셀에서 {len(selected)}건 로드 완료", foreground="darkblue")
        self._log_collect(f"[엑셀 불러오기] O 표시 {len(selected)}건 로드")

    def _get_visible_articles(self) -> list:
        """TAB1 필터(부처 + 발행일 범위)를 적용한 목록을 반환한다.
        패스·발행준비완료·포스팅완료는 항상 숨긴다 — 이 탭은 "검토 대기
        중인 기사"만 보는 화면이고, 완료(또는 완료 예정)된 건 TAB5
        이력관리에서 보면 된다.
        트리뷰 표시, 선택 항목 찾기, 전체 패스 처리 등 여러 곳에서
        "지금 화면에 보이는 게 뭔가"를 동일하게 계산해야 해서 한 곳에
        모아둔다 — 따로따로 계산하면 필터를 하나 추가할 때마다 여러
        곳을 고쳐야 하는 실수가 생기기 쉽다."""
        done_links = get_done_links()  # 패스 + 발행준비완료 + 포스팅완료

        dept_filter = self.dept_filter_var.get() if hasattr(self, "dept_filter_var") else "전체"
        date_filter = self.date_filter_var.get() if hasattr(self, "date_filter_var") else "전체"

        date_limit_days = {"오늘": 1, "최근 3일": 3, "최근 7일": 7, "최근 30일": 30}.get(date_filter)
        cutoff = None
        if date_limit_days is not None:
            cutoff = datetime.now() - timedelta(days=date_limit_days)

        visible = []
        for art in self.collected:
            if art["link"] in done_links:
                continue
            if dept_filter != "전체" and art.get("dept", "") != dept_filter:
                continue
            if cutoff is not None:
                pub_dt = art.get("pub_dt")
                if not pub_dt or pub_dt == datetime.min or pub_dt < cutoff:
                    continue
            visible.append(art)
        return visible

    def _update_dept_filter_options(self):
        """수집된 기사들의 부처 목록을 모아 콤보박스 선택지를 갱신한다.
        매번 수집할 때마다 새로운 부처가 나올 수 있어서 동적으로 채운다."""
        if not hasattr(self, "dept_filter_combo"):
            return
        depts = sorted({a.get("dept", "") for a in self.collected if a.get("dept")})
        current = self.dept_filter_var.get()
        self.dept_filter_combo["values"] = ["전체"] + depts
        # 이전에 선택했던 부처가 더 이상 목록에 없으면 "전체"로 되돌린다
        if current not in (["전체"] + depts):
            self.dept_filter_var.set("전체")

    def _refresh_collect_tree(self):
        self._update_dept_filter_options()
        self.collect_tree.delete(*self.collect_tree.get_children())
        visible = self._get_visible_articles()
        link_status = {r.get("link", ""): r.get("status", "") for r in load_history()}
        for art in visible:
            status = link_status.get(art["link"], "")
            is_screening = "검토중" in status
            tag = "new" if art["is_new"] else ""
            if art["body_type"] == "첨부파일만":
                tag = "pdf"
            if art.get("license_warn"):
                tag = "license_warn"  # 변경금지 경고 — PDF·신규 표시보다 우선
            if is_screening:
                tag = "screening"  # 검토중이 최우선 — 다른 색보다 눈에 띄게
            pub_str = art["published"][:16] if art["published"] else ""
            license_text = "⚠️ 변경금지" if art.get("license_warn") else ""
            # 처리상태는 아이콘만 보여주던 것에서 실제 텍스트로 바꿨다 —
            # 한눈에 무슨 상태인지 바로 읽히는 게 아이콘보다 직관적이다.
            # 이력에 상태가 없으면(완전 신규) "신규"로 표시한다.
            status_text = status.split(" ", 1)[-1] if status else "신규"
            # [버그 수정] iid를 link로 고정한다 — 예전에는 트리의 '행 순번
            # (index)'을 다시 _get_visible_articles()의 순번과 맞춰서 기사를
            # 찾았는데, 그 사이(자동수집 백그라운드 갱신 등)에 self.collected가
            # 재정렬되면 순번이 어긋나 완전히 다른 기사가 선택되는 사고가
            # 실제로 있었다(예: "연말정산" 기사를 선택했는데 저장은 "지하철
            # 재승차" 기사 자리에 들어가는 식). link는 고유하므로 이 문제가
            # 구조적으로 발생할 수 없다.
            self.collect_tree.insert("", "end", iid=art["link"],
                values=(pub_str, art["title"], art["dept"],
                        art["body_type"], license_text, status_text),
                tags=(tag,))
        total  = len(self.collected)
        shown  = len(visible)
        hidden = total - shown
        if hasattr(self, "collect_count_var"):
            self.collect_count_var.set(
                f"전체 {total}건  |  표시 {shown}건" +
                (f"  |  숨김 {hidden}건" if hidden else ""))

    # [Ver7.04 추가, Ver7.13 수정] 발행준비완료 누락 감지 헬퍼
    def _has_unfinished_draft(self, link: str) -> tuple:
        """MD 저장까지 갔지만(작성중) 발행준비완료·패스로 마무리되지
        않은 기사인지 확인한다. [Ver7.13] 예전에는 이 상태로 방치되면
        핵심DB에 영원히 등록 안 된다는 경고였지만, 이제 핵심DB 등록은
        TAB7 확정 시점으로 옮겨갔다 — 여기서는 단순히 "작성중으로만
        남아 이력관리에서 진행 상황을 헷갈릴 수 있다"는 안내로 바뀐다."""
        if not link:
            return False, ""
        for r in load_history():
            if r.get("link") == link and "작성중" in r.get("status", ""):
                return True, r.get("title", "")
        return False, ""

    def _reselect_article_by_link(self, link: str):
        """발행준비완료 누락 경고 팝업에서 '아니오'를 눌렀을 때,
        TAB1 트리 선택을 원래 작업 중이던 기사로 되돌린다.
        iid == link이므로 순번 계산 없이 바로 선택할 수 있다."""
        if link and self.collect_tree.exists(link):
            self.collect_tree.selection_set(link)
            self.collect_tree.see(link)

    def _on_article_select(self, event):
        sel = self.collect_tree.selection()
        if not sel:
            return
        # [버그 수정] 트리 행 순번(index)으로 self.collected를 다시 뒤져
        # 기사를 찾는 대신, iid(=link)로 직접 찾는다. 자동수집이 백그라운드
        # 에서 목록을 재정렬하는 사이 사용자가 클릭해도, 클릭된 행의 iid
        # 자체가 그 기사의 link이므로 엉뚱한 기사가 선택될 수 없다.
        link    = sel[0]
        visible = self._get_visible_articles()
        art = next((a for a in visible if a.get("link") == link), None)
        if art is None:
            return

        # 이전에 선택했던 기사와 다른 기사로 바뀌는 경우, TAB2~4에 남아있는
        # 입력값(PDF 첨부 목록·키워드·본문 등)을 자동으로 비운다.
        # 이게 없으면 A 기사 작업 중 PDF를 첨부했다가 TAB1에서 B 기사를
        # 클릭했을 때 A의 PDF가 그대로 남아 있어서 매번 수동으로 지워야
        # 하는 불편함이 있었다. 같은 기사를 다시 클릭한 경우(재선택)는
        # 초기화하지 않는다 — 작업 중 실수로 같은 행을 다시 누르면
        # 입력하던 내용이 날아가는 사고를 막기 위해서다.
        prev_link = self.selected_article.get("link", "") if self.selected_article else ""
        if prev_link and prev_link != art["link"]:
            # [Ver7.04 추가, Ver7.13 수정] 이전 기사가 MD 저장까지 됐지만
            # (작성중) 발행준비완료 처리가 안 된 상태라면, 조용히 넘어가지
            # 않고 먼저 경고한다.
            unfinished, prev_title = self._has_unfinished_draft(prev_link)
            if unfinished:
                if not messagebox.askyesno("⚠️ 발행준비완료 처리 확인",
                        f"이전 기사\n\"{prev_title[:40]}\"\n"
                        f"는 MD 파일까지 저장됐지만 발행준비완료 처리가 되지 않았습니다.\n\n"
                        f"이 상태로 다른 기사로 넘어가면 이력관리에서 '작성중'으로만\n"
                        f"남아 있어, 나중에 진행 상황을 헷갈릴 수 있습니다.\n\n"
                        f"그래도 다른 기사로 넘어가시겠습니까?\n"
                        f"(아니오 → 이전 기사를 계속 작업할 수 있습니다)"):
                    self._reselect_article_by_link(prev_link)
                    return
            self._start_new_post_silent(keep_selected_article=True)

        self.selected_article = art
        self._refresh_author_exp_status()   # [Ver10.05]

        self.preview_text.config(state="normal")
        self.preview_text.delete("1.0", "end")
        pub = art['published'][:16] if art['published'] else ""
        license_line = ""
        if art.get("license_warn"):
            license_line = ("\n⚠️ 이 기사는 공공누리 '변경금지' 조건이 확인됩니다 — "
                             "각색하지 말고 원문 그대로만 인용하세요.")
        self.preview_text.insert("end",
            f"제목: {art['title']}\n"
            f"부처: {art['dept']}  |  본문: {art['body_type']}  |  발행: {pub}\n"
            f"링크: {art['link']}{license_line}")
        self.preview_text.config(state="disabled")

    def _open_article_link(self):
        if self.selected_article.get("link"):
            webbrowser.open(self.selected_article["link"])

    def _mark_pass_core(self, art: dict) -> bool:
        """기사 1건을 '⏭ 패스' 상태로 기록하는 핵심 로직(팝업 없음).
        _mark_pass() 버튼 핸들러와 '새 글 시작'(_start_new_post) 양쪽에서
        공통으로 쓴다 — 후자는 TAB2(분석준비)에서 호출되므로 "기사를
        먼저 선택하세요" 같은 TAB1 전용 경고를 띄우면 맥락에 안 맞고,
        호출부가 이미 상황을 판단해 부르므로 여기서는 조건만 조용히
        확인하고 결과(True/False)만 돌려준다. 이미 포스팅완료된
        기사는 발행 이력 보호를 위해 그대로 두고 False를 반환한다.

        혹시 저장(작성중)까지 갔다가 패스로 되돌리는 경우를 위해,
        핵심DB(중복비교 DB)에 남은 기록이 있으면 같이 제거한다 —
        패스된 글은 "실제 포스팅 완료"가 아니므로 다른 글과 중복
        비교 대상이 되면 안 된다."""
        if not art or not art.get("link"):
            return False
        if is_published(art["link"]):
            return False
        record = {
            "title":     art.get("title", ""),  "link":      art["link"],
            "dept":      art.get("dept", ""),   "published": art.get("published", ""),
            "body_type": art.get("body_type", ""), "status": "⏭ 패스",
        }
        self.history = add_history_record(record)
        self.history = update_history_status(art["link"], "⏭ 패스")
        remove_from_dup_db(art["link"])
        return True

    def _mark_pass(self):
        """선택된 기사 1건 패스 처리 + 엑셀 상태 갱신 (TAB1 버튼 핸들러).
        실제 기록 로직은 _mark_pass_core에 있고, 여기서는 TAB1 화면
        맥락에 맞는 경고 팝업과 새로고침만 담당한다."""
        art = self.selected_article
        if not art:
            messagebox.showwarning("알림", "기사를 먼저 선택하세요.")
            return
        if is_published(art.get("link", "")):
            messagebox.showwarning("처리 불가",
                "이미 포스팅완료된 기사는 패스로 되돌릴 수 없습니다.\n"
                "(발행 이력 보호를 위한 제한입니다)")
            return
        self._mark_pass_core(art)
        self._refresh_history_tree()
        self._refresh_collect_tree()
        self._update_xlsx_status()
        self._log_collect(f"[패스] {art['title'][:40]}")

    def _mark_review(self):
        """선택된 기사 1건을 수동으로 '🔎 검토중' 상태로 표시 + 엑셀 상태 갱신.
        기존에는 스크리닝 결과(표)를 붙여넣어야만 검토중으로 바뀌었는데,
        하나씩 눈으로 보고 수동으로 체크하려는 경우를 위해 버튼으로 즉시
        전환할 수 있게 한 것. 패스와 달리 핵심DB 정리는 하지 않는다
        (검토중은 아직 작업 중인 상태이지 취소 상태가 아니므로)."""
        art = self.selected_article
        if not art:
            messagebox.showwarning("알림", "기사를 먼저 선택하세요.")
            return
        if is_published(art["link"]):
            messagebox.showwarning("처리 불가",
                "이미 포스팅완료된 기사는 검토중으로 되돌릴 수 없습니다.\n"
                "(발행 이력 보호를 위한 제한입니다)")
            return
        record = {
            "title":     art["title"],  "link":      art["link"],
            "dept":      art["dept"],   "published": art["published"],
            "body_type": art["body_type"], "status": "🔎 검토중",
        }
        self.history = add_history_record(record)
        self.history = update_history_status(art["link"], "🔎 검토중")
        self._refresh_history_tree()
        self._refresh_collect_tree()
        self._update_xlsx_status()
        self._log_collect(f"[검토중] {art['title'][:40]}")

    def _load_candidate_xlsx_map(self) -> dict:
        """후보군 엑셀(XLSX_CANDIDATE) 전체를 newsId → 기사정보 딕셔너리로
        읽어온다. TAB1 화면(self.collected)에는 필터나 재시작 등의
        이유로 없을 수 있는 기사도, 엑셀에는 한 번 수집된 기록이
        남아있으므로 1차 검토 결과 매칭의 2차 소스로 쓴다.
        키는 전체 URL이 아니라 newsId — 부가 파라미터 차이를 피한다."""
        result = {}
        if not os.path.exists(_get_xlsx_candidate_path()) or not OPENPYXL_OK:
            return result
        try:
            wb = load_workbook(_get_xlsx_candidate_path(), read_only=True)
            ws = wb.active
            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[2]:
                    continue
                link = str(row[7]).strip() if row[7] else ""
                nid = extract_news_id(link)
                if not nid or nid in result:
                    continue
                result[nid] = {
                    "title":        str(row[2]).strip(),
                    "dept":         str(row[3]).strip() if row[3] else "",
                    "published":    str(row[4]).strip() if row[4] else "",
                    "body_type":    str(row[5]).strip() if row[5] else "",
                    "link":         link,
                    "license_warn": "변경금지" in (str(row[6]).strip() if row[6] else ""),
                }
            wb.close()
        except Exception as e:
            self._log_collect(f"[1차 검토 매칭] 후보군 엑셀 읽기 오류: {e}")
        return result

    def _apply_screening_result(self):
        """프롬프트0(후보 1차 선별)의 표 출력을 붙여넣은 텍스트박스에서
        읽어와 파싱하고, 링크가 일치하는 기사들을 이력에 "검토중" 상태로
        추가/갱신한다. 본문을 읽고 가치를 판단하는 건 여전히 Claude가
        하는 일이고, 여기서는 그 판단 결과를 엑셀에 반영하는 손품만
        줄여준다 — 그 다음 사람이 "검토중"만 모아서 세부 검토(프롬프트A)
        를 진행하면 된다."""
        text = self.screening_text.get("1.0", "end").strip()
        if not text:
            messagebox.showwarning("알림", "1차 선별 결과를 먼저 붙여넣으세요.")
            return

        parsed = parse_screening_result(text)
        if not parsed:
            messagebox.showwarning("알림",
                "표에서 링크를 찾을 수 없습니다.\n"
                "탭으로 구분된 표 형식(링크/제목/우선순위/한줄사유)인지 확인하세요.")
            return

        # 매칭은 두 단계로 한다.
        # 1) 현재 TAB1에 떠 있는 기사(self.collected) — 가장 정확하고 최신
        # 2) 후보군 엑셀(XLSX_CANDIDATE) — 화면에는 안 보여도(필터·재시작 등으로
        #    self.collected가 비어있는 경우) 엑셀에는 남아있을 수 있어서 보강한다.
        # 매칭 키는 전체 URL이 아니라 newsId다. "&call_from=rsslink"처럼
        # 부가 파라미터가 붙거나 빠지면 URL 문자열은 달라지지만 같은 기사이므로,
        # newsId 숫자만 비교해야 정확히 매칭된다.
        collected_map = {extract_news_id(a["link"]): a for a in self.collected if extract_news_id(a["link"])}
        xlsx_map = self._load_candidate_xlsx_map()

        matched = 0
        not_found = []
        for item in parsed:
            nid = extract_news_id(item["link"])
            art = collected_map.get(nid) or xlsx_map.get(nid) if nid else None
            if not art:
                not_found.append(item.get("title", item["link"])[:30])
                continue
            note = item.get("priority", "")
            reason = item.get("reason", "")
            record = {
                "title":     art["title"],  "link":      art["link"],
                "dept":      art["dept"],   "published": art["published"],
                "body_type": art["body_type"], "status": "🔎 검토중",
                "screening_priority": note,
                "screening_reason":   reason,
            }
            add_history_record(record)
            update_history_status(art["link"], "🔎 검토중")
            matched += 1

        self.history = load_history()
        # 우선순위·사유 필드를 기존 레코드에도 확실히 반영 (add_history_record는
        # 중복 링크일 때 새 값을 덮어쓰지 않으므로 별도로 갱신)
        for item in parsed:
            for r in self.history:
                if r.get("link") == item["link"]:
                    r["screening_priority"] = item.get("priority", "")
                    r["screening_reason"]   = item.get("reason", "")
        save_history(self.history)

        self._refresh_history_tree()
        self._refresh_collect_tree()
        self._update_xlsx_status()

        msg = f"검토중 반영: {matched}건"
        if not_found:
            msg += f" / 미매칭: {len(not_found)}건"
        self.screening_result_var.set(msg)
        self._log_collect(
            f"[뉴스 대량검토 반영] {matched}건을 검토중으로 표시" +
            (f" (미매칭 {len(not_found)}건: {', '.join(not_found[:5])}{'...' if len(not_found)>5 else ''})" if not_found else ""))

        # [Ver7.14 추가] 상단 라벨(screening_result_var)만으로는 작업이
        # 끝났는지 놓치기 쉬워서, 완료 시 팝업으로 명확히 알려준다.
        popup_msg = f"뉴스 대량검토 결과 반영이 끝났습니다.\n\n검토중으로 반영: {matched}건"
        if not_found:
            popup_msg += (f"\n미매칭(수집 목록에서 못 찾음): {len(not_found)}건\n"
                          f" - {', '.join(not_found[:5])}{' ...' if len(not_found) > 5 else ''}")
        messagebox.showinfo("✅뉴스 대량검토 완료", popup_msg)


    def _mark_all_pass(self):
        """현재 화면에 표시된 목록 중 "신규"만 패스 처리한다.
        검토중·보류는 이미 사람이나 1차 선별이 따로 분류해둔 의미 있는
        상태이므로, 전체 패스에 휩쓸려 날아가지 않도록 항상 보호한다.
        (패스·발행준비완료·포스팅완료는 이미 _get_visible_articles에서 화면에 안 보임)"""
        visible = self._get_visible_articles()
        link_status = {r.get("link", ""): r.get("status", "") for r in load_history()}
        # "신규"는 이력에 상태가 아예 없거나 "🆕 신규"인 경우다.
        targets = [art for art in visible
                   if not link_status.get(art["link"]) or link_status.get(art["link"]) == "🆕 신규"]
        skipped = len(visible) - len(targets)

        if not targets:
            messagebox.showinfo("알림",
                "패스 처리할 신규 항목이 없습니다.\n"
                "(검토중·보류 항목은 전체 패스에서 항상 제외됩니다)")
            return
        dept_f = self.dept_filter_var.get() if hasattr(self, "dept_filter_var") else "전체"
        date_f = self.date_filter_var.get() if hasattr(self, "date_filter_var") else "전체"
        filter_note = f"(부처: {dept_f} / 발행일: {date_f} 필터 적용 중)\n" if (dept_f != "전체" or date_f != "전체") else ""
        skip_note = f"(검토중·보류 {skipped}건은 제외하고 신규만 처리합니다)\n" if skipped else ""
        if not messagebox.askyesno("전체 패스 확인",
                f"화면에 표시된 신규 {len(targets)}건을 패스 처리하시겠습니까?\n"
                f"{filter_note}{skip_note}"
                f"(이력에 추가되고 다음 수집 시 숨김 처리됩니다)"):
            return
        for art in targets:
            record = {
                "title":     art["title"],  "link":      art["link"],
                "dept":      art["dept"],   "published": art["published"],
                "body_type": art["body_type"], "status": "⏭ 패스",
            }
            add_history_record(record)
            update_history_status(art["link"], "⏭ 패스")
            remove_from_dup_db(art["link"])
        self.history = load_history()
        self._refresh_history_tree()
        self._refresh_collect_tree()
        self._update_xlsx_status()
        self._log_collect(f"[전체 패스] 신규 {len(targets)}건 처리 완료" +
                           (f" (검토중·보류 {skipped}건 보호됨)" if skipped else ""))

    def _update_xlsx_status(self):
        """이력 상태를 후보군 엑셀에 반영 (백그라운드)"""
        if not os.path.exists(_get_xlsx_candidate_path()) or not OPENPYXL_OK:
            return
        def do_save():
            wb = load_workbook(_get_xlsx_candidate_path())
            ws = wb.active
            history     = load_history()
            link_status = {r.get("link",""): r.get("status","") for r in history}
            for row_idx in range(2, ws.max_row + 1):
                link = ws.cell(row_idx, 8).value
                if not link:
                    continue
                link = str(link).strip()
                st   = link_status.get(link, "")
                ws.cell(row_idx, 2).value = st
                body_type = str(ws.cell(row_idx, 6).value or "")
                if any(x in st for x in ["패스", "포스팅완료"]):
                    fill = PatternFill("solid", fgColor="D9D9D9")
                elif "발행준비완료" in st:
                    fill = PatternFill("solid", fgColor="FFF2CC")
                elif "작성중" in st:
                    fill = PatternFill("solid", fgColor="DDEEFF")
                elif body_type == "첨부파일만":
                    fill = PatternFill("solid", fgColor="FCE4D6")
                else:
                    fill = PatternFill(fill_type=None)
                for c in range(1, 9):
                    ws.cell(row_idx, c).fill = fill
            wb.save(_get_xlsx_candidate_path())

        def worker():
            # from_bg_thread=True — 팝업은 메인 스레드로 넘기고, 저장이
            # 성공하거나 사용자가 명시적으로 포기할 때까지 반복 시도한다.
            ok, _ = self._save_xlsx_with_retry(
                do_save, file_label="후보군 엑셀(상태 갱신)",
                extra_note="(취소하면 이력은 정상 반영됐지만 엑셀의 '상태' 컬럼만 최신 내용과 어긋난 채로 남습니다.)",
                from_bg_thread=True
            )
            if ok:
                self.after(0, lambda: self._log_collect("[엑셀 상태 갱신 완료]"))
            else:
                self.after(0, lambda: self._log_collect("[엑셀 상태 갱신 포기] 다음 상태 변경 시 다시 시도됩니다."))
        threading.Thread(target=worker, daemon=True).start()

    def _send_to_analyze(self):
        if not self.selected_article:
            messagebox.showwarning("알림", "기사를 먼저 선택하세요.")
            return
        art = self.selected_article
        # TAB2 에 기사 정보 채우기
        self.tab2_title_var.set(art["title"])
        self.tab2_dept_var.set(art["dept"])
        self.tab2_link_var.set(art["link"])
        self.tab2_body_type_var.set(art["body_type"])
        self.tab2_info_text.config(state="normal")
        self.tab2_info_text.delete("1.0", "end")
        self.tab2_info_text.insert("end",
            f"제목: {art['title']}\n부처: {art['dept']}\n"
            f"본문유형: {art['body_type']}\n링크: {art['link']}")
        self.tab2_info_text.config(state="disabled")

        # 본문유형에 따라 PDF 1개 안내 갱신
        # - 본문있음: 뉴스 페이지 캡처 PDF 1개 (드래그 복사보다 깔끔)
        # - 첨부파일만: 첨부파일 PDF 1개 (캡처해도 제목만 나와 의미 없음)
        # - 확인필요: 링크를 직접 열어 위 둘 중 해당하는 쪽으로 1개 준비
        if hasattr(self, "pdf_guide_var"):
            bt = art.get("body_type", "")
            if bt == "본문있음":
                self.pdf_guide_var.set(
                    "📄 이 기사는 '본문있음' → 뉴스 페이지를 캡처한 PDF 1개만 첨부하세요.\n"
                    "(드래그로 텍스트 복사하는 것보다 캡처가 더 정확합니다)")
            elif bt == "첨부파일만":
                self.pdf_guide_var.set(
                    "📎 이 기사는 '첨부파일만' → 보도자료 첨부파일 PDF 1개만 첨부하세요.\n"
                    "(페이지를 캡처해도 제목만 나오고 첨부파일과 제목이 같아 의미가 없습니다)")
            else:
                self.pdf_guide_var.set(
                    "❓ 본문유형 확인 필요 → 링크를 열어 본문이 있으면 캡처 PDF,\n"
                    "첨부파일만 있으면 첨부 PDF를 1개만 준비하세요.")

        self.nb.select(2)  # 분석준비 탭 이동 (뉴스 대량검토 탭이 끼어들어 인덱스 +1)
        self._log_collect(f"[→ 분석준비] 선택: {art['title'][:40]}...")

    def _log_collect(self, msg: str):
        def _do():
            self.collect_log.config(state="normal")
            self.collect_log.insert("end", msg + "\n")
            self.collect_log.see("end")
            self.collect_log.config(state="disabled")
        self.after(0, _do)

    # ──────────────────────────────────────────────────────
    # TAB 2 : 분석 준비
    # ──────────────────────────────────────────────────────
    # ──────────────────────────────────────────────────────
    # TAB 1-2 : 뉴스 대량검토 (프롬프트0 후보 1차 선별 결과 반영)
    # ──────────────────────────────────────────────────────
    def _build_tab_bulk_review(self):
        """1.수집 탭에서 분리한 "뉴스 대량검토" 전용 탭.
        자동수집/낱개 단위 상세검토(1.수집)와 대량 후보 선별 작업의
        성격이 달라서 한 탭에 다 있으면 헷갈리기 쉬웠다 — 여기서는
        Claude가 정리해준 후보 목록(프롬프트0 출력)을 한 번에 붙여넣고
        반영하는 일만 한다."""
        f = ttk.Frame(self.nb, padding=10)
        self.nb.add(f, text="🗂 2)다중뉴스 사전검토")
        f.columnconfigure(0, weight=1)
        f.rowconfigure(1, weight=1)

        ttk.Label(f,
            text="아래 두 버튼(프롬프트0 복사 → TAB1 목록 복사)을 순서대로 눌러 Claude에 붙여넣고 1차 선별을 받은 뒤,\n"
                 "그 결과(표 형식)를 아래에 붙여넣으면 해당 기사들이 한 번에 '검토중' 상태로 바뀝니다. (엑셀을 직접 열 필요 없음)\n"
                 "※ TAB1 그리드에서 Ctrl/Shift-클릭으로 여러 건을 미리 선택해두면 [TAB1 목록 복사]가 선택한 것만 복사합니다.\n"
                 "  선택 없이 누르면 화면에 보이는 전체가 복사됩니다.",
            style="Info.TLabel", justify="left").grid(row=0, column=0, sticky="w", pady=(0,8))

        # 1차 검토 결과 반영 — 프롬프트0(후보 1차 선별)의 표 출력을 그대로
        # 붙여넣으면, 링크가 일치하는 기사들의 상태를 "검토중"으로 한 번에
        # 바꿔준다. 본문을 읽고 직접 판단하는 건 여전히 Claude가 하고,
        # 여기서는 그 판단 결과를 엑셀/이력에 반영하는 손품만 줄여준다.
        screen_f = ttk.LabelFrame(f,
            text="🔎 1차 검토 결과 반영 — Claude가 정리해준 후보 목록(프롬프트0 출력)을 붙여넣으세요", padding=8)
        screen_f.grid(row=1, column=0, sticky="nsew")
        screen_f.columnconfigure(0, weight=1)
        screen_f.rowconfigure(0, weight=1)

        text_wrap_f = ttk.Frame(screen_f)
        text_wrap_f.grid(row=0, column=0, sticky="nsew")
        text_wrap_f.columnconfigure(0, weight=1)
        text_wrap_f.rowconfigure(0, weight=1)

        self.screening_text = tk.Text(text_wrap_f, height=20, wrap="none", font=("맑은 고딕", 9))
        screen_vscroll = ttk.Scrollbar(text_wrap_f, orient="vertical", command=self.screening_text.yview)
        screen_hscroll = ttk.Scrollbar(text_wrap_f, orient="horizontal", command=self.screening_text.xview)
        self.screening_text.configure(yscrollcommand=screen_vscroll.set,
                                       xscrollcommand=screen_hscroll.set)
        self.screening_text.grid(row=0, column=0, sticky="nsew")
        screen_vscroll.grid(row=0, column=1, sticky="ns")
        screen_hscroll.grid(row=1, column=0, sticky="ew")

        screen_btn_f = ttk.Frame(screen_f)
        screen_btn_f.grid(row=1, column=0, sticky="ew", pady=(6,0))
        ttk.Button(screen_btn_f, text="📋 프롬프트0 복사",
                   command=self._copy_prompt_0,
                   style="Copy.TButton").pack(side="left", padx=(0,8))
        ttk.Button(screen_btn_f, text="📋 TAB1 목록 복사",
                   command=self._copy_collect_list_for_prompt0,
                   style="Copy.TButton").pack(side="left", padx=(0,8))
        ttk.Button(screen_btn_f, text="✅ 1차 검토 결과 반영",
                   command=self._apply_screening_result,
                   style="Copy.TButton").pack(side="left", padx=(0,8))
        ttk.Button(screen_btn_f, text="지우기",
                   command=lambda: self.screening_text.delete("1.0", "end")).pack(side="left")
        self.screening_result_var = tk.StringVar(value="")
        ttk.Label(screen_btn_f, textvariable=self.screening_result_var,
                  foreground="darkgreen", font=("맑은 고딕", 9, "bold")).pack(side="left", padx=(12,0))

    # ──────────────────────────────────────────────────────
    # TAB 2 : 분석준비
    # ──────────────────────────────────────────────────────
    def _build_tab2_analyze(self):
        # 콘텐츠가 창 높이보다 길어져도 하단 버튼이 가려지지 않도록
        # 스크롤 가능한 캔버스로 감싼다.
        outer = ttk.Frame(self.nb)
        self.nb.add(outer, text="🔍 3)분석 및 초안작성")
        outer.rowconfigure(0, weight=1)
        outer.columnconfigure(0, weight=1)

        canvas = tk.Canvas(outer, highlightthickness=0)
        vscroll = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vscroll.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        vscroll.grid(row=0, column=1, sticky="ns")

        f = ttk.Frame(canvas, padding=10)
        f_id = canvas.create_window((0, 0), window=f, anchor="nw")

        def _on_f_configure(event):
            canvas.configure(scrollregion=canvas.bbox("all"))
        f.bind("<Configure>", _on_f_configure)

        def _on_canvas_configure(event):
            canvas.itemconfig(f_id, width=event.width)
        canvas.bind("<Configure>", _on_canvas_configure)

        def _on_mousewheel(event):
            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")

        def _bind_wheel(event):
            canvas.bind_all("<MouseWheel>", _on_mousewheel)

        def _unbind_wheel(event):
            canvas.unbind_all("<MouseWheel>")

        canvas.bind("<Enter>", _bind_wheel)
        canvas.bind("<Leave>", _unbind_wheel)

        f.columnconfigure(0, weight=1)
        f.columnconfigure(1, weight=1)

        # 기사 정보 표시
        self.tab2_title_var    = tk.StringVar()
        self.tab2_dept_var     = tk.StringVar()
        self.tab2_link_var     = tk.StringVar()
        self.tab2_body_type_var= tk.StringVar()

        # [Ver9.08 신규] 제목 후보 확정(A [5단계] 후보 3개 → 네이버
        # 실측 → 사람이 최종 1개 선택) 관련 상태. title_candidates는
        # parse_title_candidates()가 반환하는 dict 리스트(최대 3개).
        # title_final_choice는 라디오버튼 값("0"/"1"/"2"/"manual").
        self.title_candidates     = []
        self.title_final_choice   = tk.StringVar(value="")
        self.title_reject_vars    = [tk.BooleanVar(value=False) for _ in range(3)]
        self.title_cand_label_vars= [tk.StringVar(value=f"[{i+1}] (미추출)") for i in range(3)]
        self.title_manual_var     = tk.StringVar(value="")
        self.title_confirm_status = tk.StringVar(value="")
        # [Ver9.12 신규] 셀레니움 자동 제목정밀검색(따옴표 없는 자연어 검색
        # 기준 — 프롬프트A V10 [검색결과 없음(미인식) 판정]/[검색 노출
        # 폭 확인] 로직을 코드로도 1차 적용) 결과 표시용.
        # [Ver9.19] title_precheck_results[i]는 None(미확인) 또는 policy_precheck_verdict()
        # 입력 dict(full_count/full_rel/front/front_count/front_rel/similar/level 등).
        # 아래는 Ver9.12 당시 설명(참고):
        # title_precheck_results[i]는 None(미확인) 또는
        # {"blog_count":int,"blog_zero":bool,"int_count":int,"int_zero":bool}.
        self.title_precheck_results = [None, None, None, None]
        self.title_precheck_items = [None, None, None, None]   # [Ver9.20] 후보별 수집 결과(복사용)
        self.title_precheck_vars  = [tk.StringVar(value="") for _ in range(4)]   # [Ver9.23] 후보 3 + 직접 입력 1
        self.title_include_back_var = tk.BooleanVar(value=True)   # [Ver9.26] 뒷구도 검색
        self.title_collect_var = tk.StringVar(value="많이")        # [Ver9.27] 수집량(표준/많이/최대)
        # 확정 결과(문자열) — 비어있으면 아직 미확정
        self.confirmed_title            = ""
        self.confirmed_core_keyword     = ""
        self._core_kw_auto              = ""   # [Ver9.19] 코드가 마지막으로 자동 입력한 핵심 키워드(사람이 고친 값 보호용)
        self.confirmed_intro_structure  = ""
        self.confirmed_intro_first_sentence = ""

        art_f = ttk.LabelFrame(f, text="선택된 기사", padding=8)
        art_f.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0,8))
        art_f.columnconfigure(1, weight=1)

        self.tab2_info_text = tk.Text(art_f, height=4, state="disabled",
                                      wrap="word", font=("맑은 고딕", 9))
        self.tab2_info_text.pack(fill="both")

        btn_art = ttk.Frame(art_f)
        btn_art.pack(fill="x", pady=(4,0))
        ttk.Button(btn_art, text="🔗 원문 열기",
                   command=lambda: webbrowser.open(self.tab2_link_var.get())).pack(side="left")
        ttk.Button(btn_art, text="🆕 새 글 시작 (입력값 전체 초기화)",
                   command=self._start_new_post,
                   style="Copy.TButton").pack(side="left", padx=(8,0))
        # [신규] 프롬프트A 판정이 '보류'로 나오는 등 이 기사를 더 진행하지
        # 않기로 한 경우 전용 — TAB4 "🟡 발행준비완료로 이력 업데이트"와
        # 같은 흐름으로, 패스 처리 + 입력값 초기화 + TAB1 이동을 한 번에 한다.
        ttk.Button(btn_art, text="⏭ 이 글 패스하고 새 글 시작",
                   command=self._mark_pass_and_new_post).pack(side="left", padx=(8,0))

        # [Ver9.09 수정] V5 프롬프트A부터는 A가 사전 리서치 데이터를 아예
        # 받지 않는다 — A가 [2단계]에서 본문을 직접 분석해 키워드 후보
        # 2~5개를 스스로 고르고, 그 실측을 사용자에게 요청한다(예외 없이
        # 항상 실행). 그래서 이 STEP은 더 이상 "프롬프트A 실행 전 사전
        # 준비"가 아니라 "STEP 1로 A를 먼저 실행해 [2단계] 요청을 받은
        # 뒤, 그 키워드를 여기 붙여넣어 조회하고 결과를 A에게 돌려주는"
        # 용도로 바뀌었다. 제목만 보고 미리 후보를 뽑던 "📋 제목에서
        # 후보 추출" 버튼(Ver9.07)은 삭제했다 — 본문을 못 보고 제목만
        # 보던 정제라 관형절·서술어가 안 걸러진 검색 불가능한 키워드가
        # 나오는 사례(예: "행안부가 지원하는 섬 여행" → 검색량 0)가
        # 확인됐고, A가 본문 분석으로 직접 뽑는 지금 방식이 더 정확함이
        # 실측으로 확인됨.
        research_f = ttk.LabelFrame(f, text="STEP 1.5 — A가 요청한 키워드 실측 (STEP 1 실행 후 A가 키워드를 요청하면 여기서 조회)", padding=8)
        research_f.grid(row=4, column=0, columnspan=2, sticky="ew", pady=(0, 8))
        research_f.columnconfigure(1, weight=1)

        ttk.Label(research_f, text="검색 키워드:").grid(row=0, column=0, sticky="w")
        self.tab2_research_keyword_var = tk.StringVar(value="")
        ttk.Entry(research_f, textvariable=self.tab2_research_keyword_var).grid(
            row=0, column=1, sticky="ew", padx=(5, 4))
        # [Ver10.04 신규] 검색 키워드 칸만 비우는 버튼 — 키워드를 바꿔 다시 조회할 때
        # 칸을 직접 지우지 않아도 되게 한다. 다른 입력값(핵심 키워드·제목 등)은 건드리지 않는다.
        ttk.Button(research_f, text="✖ 입력 지우기",
                   command=self._clear_tab2_research_keyword).grid(
            row=0, column=2, padx=(0, 8))
        ttk.Button(research_f, text="🔍 키워드 리서치 실행",
                   command=self._run_tab2_keyword_research, style="Copy.TButton").grid(
            row=0, column=3)
        # [Ver8.21 추가, Ver8.22 수정] "🔍 키워드 리서치 실행"(캐시에 저장,
        # 아래 "📋 A에게 결과 전달"이 이 캐시를 읽음)과는 완전히 별도로
        # 동작하는 버튼 — 클릭 즉시 자체적으로 리서치를 실행하고 끝나면
        # 바로 팝업으로 검색량·자동완성 결과를 보여준다. 두 버튼은
        # 서로의 결과를 공유하지 않으므로 어느 쪽을 먼저 눌러도 무방하다.
        ttk.Button(research_f, text="🔍 검색량·자동완성 조회",
                   command=self._show_research_summary_popup).grid(
            row=0, column=4, padx=(8, 0))
        # [Ver9.09 신규] 위 "🔍 키워드 리서치 실행"으로 캐시된 결과를,
        # A가 [2단계]에서 요청한 형식(키워드별 검색량·자동완성)에 맞춰
        # 정리해 클립보드에 복사한다 — 사람이 결과를 손으로 다시
        # 타이핑해 A와의 대화창에 붙여넣지 않아도 되게 하기 위함.
        ttk.Button(research_f, text="📋 A에게 결과 전달",
                   command=self._copy_research_reply_for_a, style="Copy.TButton").grid(
            row=0, column=5, padx=(8, 0))

        self.tab2_research_status_var = tk.StringVar(value="")
        ttk.Label(research_f, textvariable=self.tab2_research_status_var, foreground="gray",
                  wraplength=900, justify="left").grid(
            row=1, column=0, columnspan=4, sticky="w", pady=(4, 0))
        ttk.Label(research_f,
                  text="① STEP 1로 프롬프트A를 먼저 실행하세요(원문만 필요, 사전 리서치 불필요). "
                       "A가 콤마로 구분한 키워드 요청 코드블럭을 냅니다.\n"
                       "② 그 키워드를 그대로 복사해 위 '검색 키워드' 칸에 붙여넣고(콤마 구분 그대로 두면 됨) "
                       "'🔍 키워드 리서치 실행'을 누르세요.\n"
                       "③ '📋 A에게 결과 전달'을 눌러 결과를 복사한 뒤, A를 실행했던 그 대화창에 붙여넣어 "
                       "이어서 진행하세요.",
                  style="Info.TLabel", wraplength=900, justify="left").grid(
            row=2, column=0, columnspan=4, sticky="w", pady=(2, 0))


        # 프롬프트A 복사 버튼
        pa_f = ttk.LabelFrame(f, text="STEP 1 — 프롬프트A 복사 (키워드 전략 분석)", padding=8)
        # [Ver9.15 수정] 옆자리(col1)에 있던 STEP3(키워드만으로 블로그탭
        # 검색 — 제목 없이는 판단 의미가 없어 실사용 안 함)를 삭제하면서,
        # col0/col1로 나눠 배치했던 이유가 없어져 다시 가로 전체
        # (columnspan=2)로 되돌린다. (Ver9.04에서 STEP3와 나란히 놓으려고
        # col0 단독으로 줄였던 것을 원복.)
        pa_f.grid(row=1, column=0, columnspan=2, sticky="new", pady=(0,8))

        ttk.Label(pa_f,
            text="프롬프트A + 기사정보가 클립보드에 복사됩니다.\n"
                 "Claude(claude.ai)를 직접 열고 Ctrl+V 로 붙여넣기 하세요.",
            style="Info.TLabel").grid(row=0, column=0, columnspan=2, sticky="w", pady=(0,6))

        btn_row = ttk.Frame(pa_f)
        btn_row.grid(row=1, column=0, columnspan=2, sticky="w")
        ttk.Button(btn_row, text="📋 프롬프트A 클립보드 복사",
                   command=self._copy_prompt_a, style="Copy.TButton").pack(side="left", padx=(0,8))
        self.copy_a_status = ttk.Label(btn_row, text="", foreground="darkgreen",
                                       font=("맑은 고딕", 9, "bold"))
        self.copy_a_status.pack(side="left")

        # PDF 첨부
        pdf_f = ttk.LabelFrame(f, text="STEP 1-1 — PDF 첨부 (1개만 첨부)", padding=8)
        pdf_f.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(0,8))
        pdf_f.columnconfigure(0, weight=1)

        # PDF 리스트박스
        list_row = ttk.Frame(pdf_f)
        list_row.grid(row=0, column=0, sticky="ew")
        list_row.columnconfigure(0, weight=1)

        self.pdf_listbox = tk.Listbox(list_row, height=3,
                                       font=("맑은 고딕", 9),
                                       selectmode="single")
        self.pdf_listbox.grid(row=0, column=0, sticky="ew")
        vsb_pdf = ttk.Scrollbar(list_row, orient="vertical",
                                 command=self.pdf_listbox.yview)
        self.pdf_listbox.configure(yscrollcommand=vsb_pdf.set)
        vsb_pdf.grid(row=0, column=1, sticky="ns")

        # 버튼
        btn_pdf = ttk.Frame(pdf_f)
        btn_pdf.grid(row=1, column=0, sticky="w", pady=(4,0))
        ttk.Button(btn_pdf, text="📂 PDF 추가",
                   command=self._add_pdf).pack(side="left", padx=(0,6))
        ttk.Button(btn_pdf, text="👁 선택 파일 열기",
                   command=self._open_selected_pdf).pack(side="left", padx=(0,6))
        ttk.Button(btn_pdf, text="❌ 선택 제거",
                   command=self._remove_selected_pdf).pack(side="left", padx=(0,6))
        ttk.Button(btn_pdf, text="🗑 전체 제거",
                   command=self._clear_pdf_list).pack(side="left")
        self.pdf_guide_var = tk.StringVar(
            value="⚠ 기사를 선택하면 본문유형에 맞는 안내가 여기 표시됩니다.")
        ttk.Label(pdf_f, textvariable=self.pdf_guide_var,
                  style="Info.TLabel", justify="left").grid(
            row=2, column=0, sticky="w", pady=(4,0))

        # 처리 방향 선택 (1차 중복 체크는 제거함 — 제목·키워드만으로 하는
        # 비교는 본문 기준 2차 체크와 같은 핵심DB를 보면서 정확도만 낮았다.
        # 정확한 중복 비교는 본문이 다 갖춰진 TAB3의 2차 체크 한 번으로 충분하다.)
        # 다만 "이번 글을 업데이트 작성으로 할지"는 본문 작성 전에 미리
        # 정해두는 게 자연스러워서 이 자리에 남겨둔다.
        dup1_f = ttk.LabelFrame(f, text="STEP 1-2 — 처리 방향 (중복 비교는 TAB3에서 본문 기준으로 합니다)", padding=8)
        dup1_f.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0,8))

        # 중복이 떠도, 새로운 구체적 정보(숫자·조건·시행일 변경 등)가 추가됐다면
        # "업데이트 작성"으로 명시적으로 표시하고 진행할 수 있게 한다.
        # 단순 재탕과 의도적 후속 발행을 이력에서 구분하기 위한 선택이다.
        dup_action_f = ttk.Frame(dup1_f)
        dup_action_f.pack(fill="x")
        ttk.Label(dup_action_f, text="이번 글 처리 방향:").pack(side="left", padx=(0,6))
        self.dup_action_var = tk.StringVar(value=DUP_ACTION_LIST[0])
        ttk.Combobox(dup_action_f, textvariable=self.dup_action_var,
                     values=DUP_ACTION_LIST, width=22, state="readonly").pack(side="left")
        ttk.Label(dup_action_f,
                  text="← 기존 글의 후속 보강이라면 '업데이트 작성' 선택 (TAB3 포스팅 중복 체크에서 최종 확인)",
                  style="Info.TLabel").pack(side="left", padx=(8,0))

        # 핵심 키워드 / 참고용 키워드 후보 입력
        # [Ver9.08 수정] 한때 "제목은 B가 본문을 다 쓴 뒤 직접 짓는다"는
        # 구조로 바뀌었던 적이 있었으나(그 결과 이 아래 STEP3에 있던
        # 제목 검색 기능이 "아직 제목이 없다"는 이유로 무력화되는 문제가
        # 발생), 제목 결정에 필요한 리서치·경쟁도 판단 근거가 전부 A
        # 단계에만 있다는 원래 설계로 되돌렸다. 프롬프트A는 0~4단계를
        # 출력한다: 0=가치판정, 1=강조할 부분, 2=핵심 키워드·참고용
        # 키워드 후보, 3=전개 방향 제안, 4=제목 후보 3개(+도입부 지시).
        # 소제목 구성만 B가 독자 질문 흐름에 맞춰 스스로 정한다. 제목
        # 후보 확정은 아래 STEP3에서 한다.
        result_f = ttk.LabelFrame(f, text="STEP 2 — 키워드 입력 (Claude 결과에서 복사)", padding=8)
        result_f.grid(row=5, column=0, columnspan=2, sticky="ew", pady=(0,10))
        result_f.columnconfigure(1, weight=1)

        # 발표 유형 / 경쟁 강도 — 프롬프트A 0단계·2단계 점검 결과를 기록해
        # 이력에서 "사전 선점당한 키워드였는지" 나중에 추적할 수 있게 한다.
        meta_f = ttk.Frame(result_f)
        meta_f.grid(row=0, column=0, columnspan=3, sticky="w", pady=(0,8))
        ttk.Label(meta_f, text="발표 유형:").pack(side="left", padx=(0,4))
        self.announce_type_var = tk.StringVar(value=ANNOUNCE_TYPE_LIST[-1])
        ttk.Combobox(meta_f, textvariable=self.announce_type_var,
                     values=ANNOUNCE_TYPE_LIST, width=12, state="readonly").pack(side="left", padx=(0,16))
        ttk.Label(meta_f, text="경쟁 강도(실측):").pack(side="left", padx=(0,4))
        self.competition_var = tk.StringVar(value=COMPETITION_LIST[-1])
        ttk.Combobox(meta_f, textvariable=self.competition_var,
                     values=COMPETITION_LIST, width=10, state="readonly").pack(side="left")
        ttk.Label(meta_f, text="← 프롬프트A 0단계·3단계 출력에서 확인해 선택 (블로그 검색으로 직접 확인한 경우 반영)",
                  style="Info.TLabel").pack(side="left", padx=(8,0))


        # 자동 채우기 — Claude 웹에서 복사한 프롬프트A 결과를 클립보드에서
        # 그대로 읽어 채운다. [Ver9.09 수정] V5 프롬프트A부터 A가 한
        # 대화 안에서 두 번에 나눠 출력한다(1차: 0~2단계, 코드블럭 없음 /
        # 2차: 3~5단계, 코드블럭). 이 버튼은 두 출력 모두에 쓸 수 있다 —
        # 1차 출력을 붙여넣고 누르면 "강조할 부분"만 채워지고, 2차
        # 출력을 붙여넣고 누르면 핵심 키워드·참고용 후보·전개 방향·
        # 제목 후보가 채워진다(파싱은 parse_prompt_a_result()가 있는
        # 필드만 채우므로 두 번 눌러도 안전하다).
        autofill_f = ttk.Frame(result_f)
        autofill_f.grid(row=1, column=0, columnspan=3, sticky="w", pady=(0,6))
        ttk.Button(autofill_f, text="📥 클립보드에서 자동 채우기 (프롬프트A 결과)",
                   command=self._autofill_from_prompt_a,
                   style="Copy.TButton").pack(side="left", padx=(0,8))
        self.autofill_a_status = ttk.Label(autofill_f, text="",
                                            foreground="darkgreen",
                                            font=("맑은 고딕", 9, "bold"))
        self.autofill_a_status.pack(side="left")

        guide = (
            "프롬프트A는 한 대화 안에서 두 번 출력합니다 — 이 버튼은 두 번 다 쓰세요.\n"
            "  ① 1차 출력(0~2단계, 키워드 실측 요청으로 끝남)을 복사해 누르면 '강조할 부분'만 채워집니다.\n"
            "     요청받은 키워드는 위 STEP 1.5에서 조회해 결과를 A에게 돌려주세요.\n"
            "  ② A가 이어서 낸 2차 출력(3~5단계, 코드블럭)을 복사해 다시 누르면 핵심 키워드 / 참고용 후보 / "
            "전개 방향 / 제목 후보 3개가 한 번에 채워집니다.\n"
            "  • 자동 채우기가 잘 안 되면 아래 칸에 직접 붙여넣거나 입력해도 됩니다.\n"
            "  ※ 제목은 아래 STEP3에서 후보 3개를 네이버로 직접 검색해 확인한 뒤 하나를 확정합니다. 소제목 구성만 B가 본문을 쓰며 스스로 정합니다."
        )
        tk.Label(result_f, text=guide, justify="left",
                 bg="#FFF9E6", fg="#555555",
                 font=("맑은 고딕", 9), relief="flat",
                 padx=8, pady=6, anchor="w").grid(
            row=2, column=0, columnspan=3, sticky="ew", pady=(0,8))

        ttk.Label(result_f, text="핵심 키워드:", font=("맑은 고딕", 10, "bold")).grid(row=3, column=0, sticky="w", pady=3)
        self.core_keyword_var = tk.StringVar()
        ttk.Entry(result_f, textvariable=self.core_keyword_var,
                  font=("맑은 고딕", 10)).grid(row=3, column=1, columnspan=2, sticky="ew", padx=5)
        ttk.Label(result_f,
                  text="(중복체크·프롬프트B 전달에 쓰이는 필수값 — 자동 채우기로 채워지거나 직접 입력)",
                  style="Info.TLabel").grid(row=4, column=0, columnspan=3, sticky="w", pady=(0,4))

        # [Ver8.18 수정] "참고용 키워드 후보 1/2/3" 개별 입력창 3개를
        # 없앴다 — 프롬프트A가 복합 소재형 기사에서 소재별로 후보를
        # 내는 경우 고정된 3칸에 정확히 안 맞아 자동 채우기가 어긋나는
        # 문제가 있었고("가장 마지막 3개만 억지로 끼워맞춰야 하는" 구조),
        # 어차피 참고용 키워드는 프롬프트B에 "참고"로만 전달되는 값이라
        # 아래 결과보기 칸 하나에 다 모아두는 편이 실제 사용 흐름과도
        # 맞는다. 참고용 키워드는 이제 아래 "A 결과 전체보기" 칸 안에
        # "[후보 N] 키워드" 줄로 함께 표시·저장되고, 다운스트림(중복체크·
        # 프롬프트B 전달·제목에 어느 후보가 쓰였는지 감지)은 모두
        # self._get_sub_keywords()가 이 칸에서 정규식으로 추출해서
        # 대체한다 — 화면에 보이는 텍스트 하나가 유일한 소스가 되어
        # 입력창과 실제 반영값이 따로 노는 문제도 함께 없앤다.
        ttk.Label(result_f, text="A 결과 전체보기\n(참고용 키워드·강조할 부분·전개 방향):",
                  font=("맑은 고딕", 9, "bold")).grid(row=5, column=0, sticky="nw", pady=3)
        self.a_brief_text = tk.Text(result_f, height=16, wrap="word", font=("맑은 고딕", 9))
        self.a_brief_text.grid(row=5, column=1, columnspan=2, sticky="ew", padx=5)
        # [Ver9.18 신규] "📥 클립보드에서 자동 채우기" 버튼을 누르지 않고
        # 이 칸에 바로 Ctrl+V로 붙여넣는 경우, 원문 텍스트만 그대로
        # 박히고 핵심 키워드·제목 후보 파싱이 전혀 실행되지 않아 이후
        # TAB2/TAB4에서 핵심 키워드가 비어 진행이 막히는 문제가 있었다.
        # 기본 붙여넣기 동작을 막고(return "break") 대신 자동 채우기
        # 함수를 그대로 호출한다 — 그 함수도 결국 OS 클립보드에서 같은
        # 내용을 읽어 이 칸을 채우므로 결과는 버튼을 누른 것과 동일하다.
        self.a_brief_text.bind("<<Paste>>", self._on_a_brief_paste)
        ttk.Label(result_f,
                  text="자동 채우기를 누르면 참고용 키워드 후보·강조할 부분·전개 방향이\n"
                       "여기에 한 번에 채워집니다. 참고용 키워드는 \"[후보 1] 키워드\" 형식의\n"
                       "줄로 표시되며, 이 형식을 유지한 채 직접 고쳐도 정상 인식됩니다.\n"
                       "프롬프트B 복사 시 이 칸 전체가 함께 전달됩니다. (비워도 진행 가능)",
                  style="Info.TLabel").grid(row=6, column=1, columnspan=2, sticky="w", padx=5)

        # 다음 단계로 이동 (TAB2에서 입력한 키워드 등은 여기서 바로
        # 이력에 기록하지 않는다 — TAB3에서 본문을 작성하고 [MD 파일 저장]을
        # 누르는 시점에 한 번에 기록된다. 이렇게 하면 "검토중" 상태에서
        # 빈 정보로 한 번, 저장할 때 또 한 번 기록하면서 입력값이 누락되던
        # 문제가 없어진다 — 이력 갱신은 항상 저장 시점 단 한 번이다.)
        btn_f3 = ttk.Frame(result_f)
        btn_f3.grid(row=10, column=0, columnspan=3, sticky="e", pady=(8,0))
        ttk.Button(btn_f3, text="→ 글 작성으로 이동",
                   command=lambda: self.nb.select(3),  
                   style="Copy.TButton").pack(side="left")

        # [Ver9.15] STEP3 — 네이버 검색으로 키워드 경쟁도 확인 (선택) 삭제.
        # 키워드만으로 블로그탭을 검색해도 제목 문장 전체·조합 문맥이
        # 없어 실측 판단에 쓸 수 있는 정보가 아니라 실사용이 없었다
        # (실제 경쟁도 판단은 아래 STEP4에서 제목 후보 3개를 문장째로
        # 검색해 이미 하고 있음). search_f 위젯과, 여기서만 쓰이던
        # _open_naver_blog_search_research_kw / _open_naver_search_research_kw /
        # _open_naver_blog_search / _open_naver_search 4개 메서드를
        # 함께 제거했다.

        # ──────────────────────────────────────────────
        # [Ver9.08 신규] STEP 4 — 제목 후보 확정 (네이버 실측)
        # A [4단계]가 낸 후보 3개를 후보별로 네이버에 직접 검색해
        # 실측 경쟁도를 눈으로 확인한 뒤, 사람이 최종 1개를 라디오
        # 버튼으로 선택해 확정한다. 판정 기준(오늘 합의):
        #   - 검색은 되지만 무관하거나 겹치는 글이 1~2건 이하 → 우수
        #   - 1페이지가 관련 글로 빽빽함, 또는 "검색결과가 없습니다" → 회피
        # 3개 전부 회피 판정이면 "탈락" 체크 후 "회피 목록 복사"로
        # 프롬프트A 재추천을 요청하거나, "직접 입력"으로 수동 확정한다.
        # ──────────────────────────────────────────────
        title_f = ttk.LabelFrame(f, text="STEP 4 — 제목 후보 확정 (네이버 실측)", padding=8)
        title_f.grid(row=6, column=0, columnspan=2, sticky="ew", pady=(0,10))
        title_f.columnconfigure(1, weight=1)

        ttk.Label(title_f,
                  text="위 [자동 채우기]로 A 결과를 불러오면 아래 후보 3개가 채워집니다. "
                       "필요할 때만 [▶ 후보 제목정밀검색 실행]을 누르면 셀레니움이 백그라운드로 후보마다 "
                       "(1) 전체 제목 (2) 첫 콤마 앞 '앞 핵심구'를 블로그탭에서 따옴표 없이 검색해, "
                       "제목에 핵심어가 들어간 '관련 글 수/전체 건수'를 후보 아래 줄에 표시합니다"
                       "(후보당 1~3분 안팎, 네이버 차단이 감지되면 중단). 검색은 전체 제목·앞 핵심구·뒷 구절(쉼표 뒤, "
                       "'뒷구도 검색' 체크 시)이고, 결과는 '강N·중N·약N/수집 건수'(제목의 핵심 키워드=앞부분은 개당 3점, 서브 키워드=뒷부분은 개당 "
                       "1점, 여러 개 일치하면 가산한 점수 등급)로 표시됩니다. 수집량은 표준/많이/최대에서 고르며 많을수록 오래 걸리고 차단 위험이 "
                       "커집니다. 복사 결과는 걸러내지 않은 전체 목록이고 원자료도 저장됩니다. 전체 제목은 관련 글 그룹이 "
                       "있고 같은·비슷한 제목이 없어야 하고, 앞 핵심구는 관련 글이 있어야 합니다"
                       "(관련 글 0건은 건수가 적어도 실패). 관련 글 수는 추정치이니 "
                       "🔍 블로그(전체 제목)·🔍 앞구 버튼으로 직접 확인하거나, "
                       "📋 검색결과 복사로 Claude에 검토를 맡긴 뒤 본문 적합도를 먼저 보고 "
                       "라디오버튼으로 최종 확정하세요. 직접 입력한 제목은 입력 줄 오른쪽 [▶ 제목정밀검색]로 따로 "
                       "검색할 수 있습니다.",
                  style="Info.TLabel", wraplength=900, justify="left").grid(
            row=0, column=0, columnspan=4, sticky="w", pady=(0,6))

        self.title_cand_rows_frame = ttk.Frame(title_f)
        self.title_cand_rows_frame.grid(row=1, column=0, columnspan=4, sticky="ew")
